insert into import_summary (wikidata_id, summary, source) values
  ('Q2501640', 'Justice League Task Force est un jeu vidéo de combat sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé par Blizzard Entertainment et Sunsoft, et édité par Acclaim Entertainment. Le jeu est basé sur les personnages de comics la Ligue de justice d''Amérique.', 'https://fr.wikipedia.org/wiki/Justice_League_Task_Force'),
  ('Q2474014', 'Operation Europe: Path to Victory (Europa Sensen au Japon) est un jeu vidéo de stratégie au tour par tour sorti en 1993 et fonctionne sur Mega Drive, Super Nintendo, DOS et MSX. Le jeu a été développé et édité par Koei.', 'https://fr.wikipedia.org/wiki/Operation_Europe:_Path_to_Victory_1939-45'),
  ('Q2480473', 'The Itchy and Scratchy Game est un jeu vidéo de plate-forme et d''action sorti en 1995 sur Game Gear, Mega Drive et Super Nintendo. Le jeu a été développé par Bits Corporations puis édité par Acclaim.

Il est basé sur les personnages Itchy et Scratchy, qui apparaissent dans la série Les Simpson.

Il y a 7 niveaux dans le jeu:

Juracid Bath (Monde Préhistorique)

The Medieval Dead (Château Médiéval)

Mutilation on the Bounty (Bateau de pirates)

The Pusseidon Adventure (Sous la mer)

The Magnificent Severed (Le vieil Ouest)

A Site For Sawed Eyes (Site de construction)

Disassembly Line (Usine)', 'https://fr.wikipedia.org/wiki/The_Itchy_and_Scratchy_Game'),
  ('Q1871848', 'Kirby''s Fun Pak, connu hors Europe sous le titre Kirby Super Star, est un jeu vidéo développé par HAL Laboratory et sorti sur Super Nintendo en 1996. Il s''agit d''une compilation de huit jeux de plates-formes, d''exploration et d''action se déroulant dans l''univers de la série Kirby.

Le jeu est un succès critique et commercial et est souvent considéré comme l''un des meilleurs de la franchise. En 2008, il bénéficie d''un remake sur Nintendo DS: Kirby Super Star Ultra. Il est par la suite réédité numériquement sur Wii, Wii U et Nintendo Switch via les services Console virtuelle et Nintendo Switch Online. Il fait également partie des jeux préinstallés de la Super NES Mini.', 'https://fr.wikipedia.org/wiki/Kirby%27s_Fun_Pak'),
  ('Q2919165', 'Kendo Rage ou Makeruna! Makendō 1 au Japon, est un jeu vidéo d''action et de plates-formes en 2D à thème de Kendo. Le jeu a été développé par Affect et édité par Datam Polystar et Seta sur Super Nintendo. Il est sorti au Japon le 22 janvier 1993, suivi de l''Amérique du Nord en octobre 1993. Il fait partie de la série Makeruna! Makendō.', 'https://fr.wikipedia.org/wiki/Kendo_Rage'),
  ('Q941354', 'Sunset Riders est un jeu vidéo d''action de type shoot''em up développé et édité par Konami, sorti en 1991 sur borne d''arcade. Il a été converti sur Mega Drive en 1992 et sur Super Nintendo en 1993.', 'https://fr.wikipedia.org/wiki/Sunset_Riders'),
  ('Q2913706', 'Super Street Fighter II: The New Challengers est un jeu vidéo de combat en un contre un développé et édité par Capcom sur le nouveau système d''arcade CP System II en septembre 1993. C''est un jeu de la franchise Street Fighter, et plus précisément la quatrième mouture de Street Fighter II publiée par Capcom. Il s''agit, cependant et surtout, du portage du jeu phare sur le système CPS2, là où les trois itérations précédentes étaient sorties sur le système original CPS1.', 'https://fr.wikipedia.org/wiki/Super_Street_Fighter_II:_The_New_Challengers'),
  ('Q2922966', 'Boxing Legends of the Ring est un jeu vidéo de boxe anglaise et de combat sorti en 1993 sur Mega Drive et Super Nintendo. Le jeu a été développé par Sculptured Software et édité par Electro Brain.', 'https://fr.wikipedia.org/wiki/Boxing_Legends_of_the_Ring'),
  ('Q953963', 'Might and Magic II: Gates to Another World (Might and Magic: Gates to Another World sur Mega Drive) est un jeu vidéo de type dungeon crawler sorti en 1988 et fonctionne sur Mega Drive, Amiga, Commodore 64, DOS, Super Nintendo, Apple II et Mac OS. Le jeu a été développé et édité par New World Computing.', 'https://fr.wikipedia.org/wiki/Might_and_Magic_II:_Gates_to_Another_World'),
  ('Q958761', 'Secret of Evermore (parfois abrégé SOE) est un jeu d''action-RPG développé par SquareSoft et édité sur Super Nintendo par Square le 17 octobre 1995 en Amérique du Nord et par Nintendo le 22 février 1996 en Europe. En France, Secret of Evermore voit sa date de sortie retardée à mars 1996. Une version japonaise est prévue, mais ne sort jamais. C''est le seul jeu développé par la filiale américaine de Square.

Le jeu relate l''histoire d''un jeune garçon et de son chien transportés par inadvertance dans le monde fantastique de Perpétua. Le joueur guide à la fois le garçon et le chien qui se métamorphose au cours du périple traversant les quatre régions marquées par différentes époques, la préhistoire, l''Antiquité classique, le Moyen Âge et un univers futuriste. Au cours de son aventure simulant un voyage dans le temps, il aide les quatre amis créateurs de cet univers à rentrer avec lui à Pontoise. Le gameplay partage de nombreuses similitudes avec celui de Secret of Mana sorti deux ans plus tôt sur la même console, telles que des combats en temps réel, un système de menu en forme d''anneau et la possibilité de permuter à tout moment et d''utiliser les deux personnages. Douglas E. Smith, le producteur du jeu, monte une équipe principalement composée de débutants. Le jeu est construit de toutes pièces, pour ressembler à Secret of Mana sur demande de Square, avec des outils créés par le programmeur principal Brian Fehdrau.', 'https://fr.wikipedia.org/wiki/Secret_of_Evermore'),
  ('Q957870', 'Astérix et Obélix est un jeu vidéo développé par Infogrames et Bit Managers sorti en 1995 sur Super Nintendo, en 1996 sur PC, ainsi que, dans une version adaptée, sur Game Boy en 1995 et sur Game Boy Color en 1999. Il s''agit d''un jeu de plates-formes avec une possibilité de jouer à deux pour la version sur ordinateur et Super Nintendo. Le jeu reprend l''univers de la série de bande dessinée du même nom et le joueur peut choisir d''incarner Astérix ou Obélix.

Le jeu fait suite au jeu Astérix sorti en 1993, également édité et développé par Infogrames, dont il reprend des éléments. Le jeu a des aspects comparables à d''autres adaptations de bandes dessinées éditées à la même époque par Infogrames tels que Tintin au Tibet, Spirou, Les Schtroumpfs et Lucky Luke, tels que le style graphique, l''interface et des éléments de gameplay.', 'https://fr.wikipedia.org/wiki/Ast%C3%A9rix_et_Ob%C3%A9lix_(jeu_vid%C3%A9o)'),
  ('Q956155', 'The Lawnmower Man est un jeu vidéo d''action développé par The Sales Curve en 1993 sur PC, 3DO Super Nintendo et Game Boy. Il est édité par Time Warner Interactive en 1993 sur Mega Drive et Mega CD. C''est une adaptation du film Le Cobaye de Brett Leonard.', 'https://fr.wikipedia.org/wiki/The_Lawnmower_Man_(jeu_vid%C3%A9o)'),
  ('Q2924608', 'Brett Hull Hockey 95 est un jeu vidéo de hockey sur glace sorti en 1994 et fonctionne sur DOS, Mega Drive et Super Nintendo. Le jeu a été développé par Radical Entertainment et édité par Accolade.', 'https://fr.wikipedia.org/wiki/Brett_Hull_Hockey_95'),
  ('Q953511', 'Clock Tower est un jeu vidéo de type point-and-click développé par la société japonaise Human Entertainment, édité uniquement au Japon sur Super Nintendo en 1995, sur PC et PlayStation en 1997, rebaptisé pour cette dernière Clock Tower ~The First Fear~ et sur WonderSwan en 1999. Le jeu est en général perçu comme un des jeux les plus terrifiants de la Super Nintendo.

L''histoire se déroule en Norvège, en 1995. Quatre orphelines, Jennifer, Lotte, Anne et Laura, sont adoptées par Mrs. Mary Barrows, qui vit dans son manoir coupé du monde (surnommé Clock Tower à cause de son imposant clocher) avec son mari. Après avoir conduit les filles dans le hall principal, Mrs. Barrows part chercher son mari. Mais au bout de quelques minutes, inquiète de ne voir personne revenir, Jennifer se lance à sa recherche. Après avoir quitté le hall, elle entend un cri et, en revenant sur ses pas, trouve la salle vide et est maintenant poursuivie par un enfant défiguré portant une paire de cisailles à haie, le Scissorman. L''objectif de Jennifer sera maintenant de fuir le manoir, si possible avec ses amies.', 'https://fr.wikipedia.org/wiki/Clock_Tower_(jeu_vid%C3%A9o)'),
  ('Q2909761', 'Bombuzal est un jeu vidéo de réflexion conçu par Antony Crowther et David Bishop, et édité par Image Works en 1988. Le jeu est sorti sur les ordinateurs Commodore 64, Amiga, Atari ST, PC et la console Super Nintendo. Il est connu sous le nom Ka-Blooey aux États-Unis.', 'https://fr.wikipedia.org/wiki/Bombuzal'),
  ('Q2540072', 'Mario and Wario est un jeu vidéo sorti exclusivement au Japon en 1993 sur Super Famicom. Y figurent les deux rivaux de l''univers Nintendo: Mario et Wario.', 'https://fr.wikipedia.org/wiki/Mario_and_Wario'),
  ('Q3088033', 'Unirally (ou Uniracers aux États-Unis) est un jeu vidéo de course de monocycle développé par DMA Design et édité par Nintendo sur Super Nintendo en 1994. Bien qu''étant un jeu Nintendo, Unirally n''a jamais connu de sortie au Japon.', 'https://fr.wikipedia.org/wiki/Unirally'),
  ('Q2962854', 'Chester Cheetah: Too Cool to Fool est un jeu vidéo de plates-formes de Kaneko sorti en 1992 sur Mega Drive et Super Nintendo, uniquement en Amérique du Nord.

Le jeu a donné suite à Chester Cheetah: Wild Wild Quest en 1993.', 'https://fr.wikipedia.org/wiki/Chester_Cheetah:_Too_Cool_to_Fool'),
  ('Q2553382', 'Goof Troop est un jeu vidéo d''action-aventure développé et édité par Capcom. Disponible fin 1993, le joueur y incarne Dingo (nommé Goofy en anglais) et Max.

L''histoire est simple, le joueur doit sauver Pat Hibulaire et son fils Junior, qui ont été capturés par des pirates, et amenés sur une île.

Ce jeu propose de résoudre une multitude d''énigmes. Le joueur doit ainsi pousser des blocs, tuer des méchants, trouver des objets et surtout faire marcher sa cervelle. À travers 5 niveaux (plage, village, château hanté, grotte et bateau pirate), divers ennemis (serpents, hérissons, mais surtout des pirates) vont pouvoir être éliminés de façons différentes, en leur lançant des objets, ou avec un grappin pour certains.', 'https://fr.wikipedia.org/wiki/Goof_Troop'),
  ('Q1058903', 'Super Mario All-Stars est un jeu vidéo de plate-formes développé par Nintendo EAD et édité par Nintendo. Il est sorti en 1993 sur Super Nintendo. Il s''agit d''une compilation qui contient un remake des quatre premiers jeux en deux dimensions de la série Super Mario.', 'https://fr.wikipedia.org/wiki/Super_Mario_All-Stars'),
  ('Q2549185', 'Top Gear 2 est jeu vidéo de course automobile développé par Gremlin Graphics et édité en 1993 sur Super Nintendo et en 1994 sur Amiga, Amiga CD32 et Mega Drive.

Il s''agit de la suite de Top Gear.', 'https://fr.wikipedia.org/wiki/Top_Gear_2'),
  ('Q1052174', 'Pac-Man 2: The New Adventures est un jeu vidéo développé par Namco sorti en 1994 sur Super Nintendo et Mega Drive. Le jeu étant une adaptation de la série animée Pac-Man de 1980, il se différenciera donc énormément des autres aventures de Pac-Man car on n''y dirige pas le personnage principal, mais un lance-pierres qui va attirer l''attention du personnage sur certains éléments. Suivant son humeur, Pac-Man effectuera une action différente. On peut aussi l''interpeller en criant « Look » en appuyant sur un bouton de la manette et une direction.', 'https://fr.wikipedia.org/wiki/Pac-Man_2:_The_New_Adventures'),
  ('Q2933418', 'Cal Ripken Jr. Baseball est un jeu vidéo de baseball sorti en 1992 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Mindscape.', 'https://fr.wikipedia.org/wiki/Cal_Ripken_Jr._Baseball'),
  ('Q1966569', 'Crazy Cars est une série de jeux vidéo de course automobile développée et éditée par la société française Titus Interactive. Elle est apparue début 1987 et comprend trois épisodes.', 'https://fr.wikipedia.org/wiki/Crazy_Cars'),
  ('Q2937649', 'Captain Novolin est un jeu vidéo de plates-formes éducatif sur Super Nintendo qui place le joueur dans la peau d''un super-héros atteint de diabète, Captain Novolin.

Le jeu était sponsorisé par Novo Nordisk, qui fabrique la marque d''insuline Novolin.', 'https://fr.wikipedia.org/wiki/Captain_Novolin'),
  ('Q1052386', 'The Lost Vikings est un jeu vidéo de plate-forme et de réflexion développé par Silicon & Synapse, qui deviendra plus tard Blizzard Entertainment, et édité par Interplay Entertainment en 1992 sur Super Nintendo. Il a été porté en 1993 sur Amiga, DOS et Mega Drive, en 1994 sur Amiga CD32 et en 2003 sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/The_Lost_Vikings'),
  ('Q2962853', 'Chester Cheetah: Wild Wild Quest est un jeu vidéo de plate-forme sorti en 1993 sur Mega Drive et Super Nintendo, uniquement en Amérique du Nord. Le jeu a été développé et édité par Kaneko.

Il est la suite de Chester Cheetah: Too Cool To Fool, sorti en 1992.', 'https://fr.wikipedia.org/wiki/Chester_Cheetah:_Wild_Wild_Quest'),
  ('Q2521841', 'Ultima VI: The False Prophet, est un jeu de rôle sur ordinateur publié par Origin Systems en 1990. Le jeu est le sixième de la série de jeux de rôle Ultima créée par Richard Garriott.', 'https://fr.wikipedia.org/wiki/Ultima_VI:_The_False_Prophet'),
  ('Q973459', 'Killer Instinct est un jeu vidéo de combat, développé par le studio anglais Rare associé avec Midway et Nintendo en 1994. Ce jeu fait partie de la série Killer Instinct.', 'https://fr.wikipedia.org/wiki/Killer_Instinct_(jeu_vid%C3%A9o,_1994)'),
  ('Q3098487', 'Garry Kitchen''s Super Battletank: War in the Gulf (souvent abrégé Super Battletank) est un jeu vidéo de simulation de tank sorti en 1992 sur Game Gear, Mega Drive et Super Nintendo. Le jeu a été développé et édité par Absolute Entertainment. La version Game Gear a été éditée par Majesco Sales.', 'https://fr.wikipedia.org/wiki/Garry_Kitchen%27s_Super_Battletank:_War_in_the_Gulf'),
  ('Q1900111', 'Double Dragon V: The Shadow Falls est un jeu vidéo de combat développé par Leland Interactive Media et publié par Tradewest sur Jaguar, Mega Drive et Super Nintendo en 1994.

Il s''agit du cinquième épisode de la série Double Dragon.', 'https://fr.wikipedia.org/wiki/Double_Dragon_V:_The_Shadow_Falls'),
  ('Q969899', 'Virtual Bart est un jeu vidéo développé par Sculptured Software et édité par Acclaim en 1994 sur et Mega Drive et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Virtual_Bart'),
  ('Q3129978', 'Super Bomberman 2 est un jeu vidéo d''action par Hudson Soft. Il est sorti en 1994 sur Super Nintendo et fait suite à Super Bomberman sorti en 1993 sur la même console.', 'https://fr.wikipedia.org/wiki/Super_Bomberman_2'),
  ('Q3109532', 'Go Go Ackman 2 est un jeu vidéo de plates-formes tiré du manga Go! Go! Ackman d''Akira Toriyama. Il est sorti sur Super Famicom en 1995.', 'https://fr.wikipedia.org/wiki/Go_Go_Ackman_2'),
  ('Q2534891', 'Aero Fighters (nommé Sonic Wings au Japon) est un jeu de type « shoot them up » à défilement verticale sorti sur borne d''arcade en 1992. En 1993, il a été porté sur Super Famicom, puis en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Aero_Fighters'),
  ('Q1965664', 'Zero the Kamikaze Squirrel est un jeu vidéo de plates-formes sorti en 1994. Le jeu a été développé par Iguana Entertainment. Il se situe dans le même univers que le jeu Aero the Acro-Bat.', 'https://fr.wikipedia.org/wiki/Zero_the_Kamikaze_Squirrel'),
  ('Q1055377', 'Art of Fighting 2 est un jeu vidéo de combat en 2D développé et édité par SNK sur Neo-Geo MVS et Neo-Geo AES, Neo-Geo CD (NGM / NGH 056) et Super Famicom en 1994.

Il est réédité sur PlayStation 2 en 2006 et sur Nintendo Switch en 2018.

Il s''agit du deuxième épisode de la série Art of Fighting.', 'https://fr.wikipedia.org/wiki/Art_of_Fighting_2'),
  ('Q2561280', 'Dragon Ball Z: Super butōden (ドラゴンボールZ 超武闘伝, Doragon Bōru zetto: Sūpā butōden, littéralement « Dragon Ball Z: Les supers arts martiaux »), dont le titre du jeu n''a pas été traduit en français et est resté Dragon Ball Z: 超武闘伝 sur la jaquette, est un jeu vidéo de combat par Bandai sur l''univers Dragon Ball Z. Le jeu est distribué en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Super_But%C5%8Dden'),
  ('Q1058736', 'Fantastic Journey, ou Gokujou Parodius! au Japon, est un jeu vidéo de type shoot ''em up développé et édité par Konami en 1994 sur borne d''arcade. Il s''agit d''une transposition du concept de Gradius et d''autres jeux de tir dans un univers décalé et parodique.', 'https://fr.wikipedia.org/wiki/Fantastic_Journey'),
  ('Q1061560', 'Super Mario Kart est un jeu vidéo développé par Nintendo EAD et édité par Nintendo, sorti en 1992 sur Super Nintendo. Il s’agit d’un jeu de course de karts opposant les personnages de l’univers de Super Mario. Il constitue le premier opus de la série de jeux vidéo Mario Kart. Le jeu est sorti au Japon en août 1992, en Amérique du Nord en septembre de cette année, et en Europe en janvier 1993.

Dans Super Mario Kart, le joueur contrôle l’un des huit personnages issus de l’univers Super Mario, ayant chacun des capacités différentes. Dans le mode « solo », le joueur affronte les autres personnages contrôlés par l’ordinateur sur vingt circuits répartis en quatre coupes de cinq courses et trois niveaux de difficulté. Pendant la course, des armes et bonus peuvent être utilisés pour doubler et gêner ses adversaires. Les joueurs peuvent également faire la course contre-la-montre dans le mode de jeu Time Trial. En mode multijoueur, deux joueurs peuvent prendre part à la coupe, ou encore faire une course en tête-à-tête dans le mode Match Race. Ils peuvent également faire un duel dont le but est de détruire les ballons qui entourent le kart de l’autre joueur.', 'https://fr.wikipedia.org/wiki/Super_Mario_Kart'),
  ('Q3107876', 'World Cup USA ''94 est un jeu vidéo de football développé par Tiertex et édité par U.S. Gold en 1994 sur Amiga, DOS, Mega Drive, Mega-CD, Super Nintendo, Master System, Game Boy et Game Gear.', 'https://fr.wikipedia.org/wiki/World_Cup_USA_%2794'),
  ('Q3108499', 'NHLPA Hockey ''93 est un jeu vidéo de hockey sur glace sorti en 1992 sur Mega Drive. Le jeu a été développé par EA Sports et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/NHLPA_Hockey_%2793'),
  ('Q2526874', 'Aerobiz est un jeu vidéo de gestion de compagnie aérienne développé et édité par Koei, sorti en 1992 sur Mega Drive, Super Nintendo, FM Towns, PC-98 et X68000.

Le jeu a pour suite Aerobiz Supersonic, sorti en 1994.', 'https://fr.wikipedia.org/wiki/Aerobiz'),
  ('Q2948683', 'Champion''s World Class Soccer est un jeu vidéo de football sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Park Place Productions et sur Mega Drive par Flying Edge et édité par Acclaim Entertainment.', 'https://fr.wikipedia.org/wiki/Champion%27s_World_Class_Soccer'),
  ('Q2928112', 'Bulls vs. Blazers and the NBA Playoffs est un jeu vidéo de basket-ball sorti en 1992 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Bulls_vs._Blazers_and_the_NBA_Playoffs'),
  ('Q2527040', 'Lemmings 2: The Tribes est un jeu vidéo de réflexion développé par DMA Design et édité par Psygnosis en 1993.

Le jeu fait partie de la série Lemmings.', 'https://fr.wikipedia.org/wiki/Lemmings_2:_The_Tribes'),
  ('Q1047581', 'Undercover Cops est un jeu vidéo de type beat them all développé et édité par la société japonaise Irem sur borne d''arcade en 1992. La Super Famicom a bénéficié d''une adaptation du jeu assez fidèle d''un point de vue technique mais ne disposant pas de mode à deux joueurs.', 'https://fr.wikipedia.org/wiki/Undercover_Cops'),
  ('Q2927096', 'Brutal: Paws of Fury est un jeu vidéo de combat développé par GameTek et Eurocom, commercialisé en 1994 sur Mega Drive, Mega-CD et Super Nintendo et l''année suivante sur Amiga, Amiga CD32 et DOS.', 'https://fr.wikipedia.org/wiki/Brutal:_Paws_of_Fury'),
  ('Q2927402', 'Bubsy II est un jeu vidéo de plate-forme développé et édité par Accolade sorti sur Mega Drive, Game Boy et Super Nintendo en 1994. Il fait suite à Bubsy in: Claws Encounters of the Furred Kind et est le second opus de la série Bubsy. La version GB était publié par Telstar, Publieur notable pour avoir publié des jeux Bubsy en Europe', 'https://fr.wikipedia.org/wiki/Bubsy_II'),
  ('Q2927741', 'Bugs Bunny: Rabbit Rampage est un jeu vidéo de plate-forme pour Super Nintendo sorti en 1994.', 'https://fr.wikipedia.org/wiki/Bugs_Bunny:_Rabbit_Rampage'),
  ('Q2980379', 'Clue est un jeu vidéo sorti en 1992 sur Mega Drive et Super Nintendo. Le jeu a été développé par Sculptured Software et édité par Parker Brothers.

Il s''agit d''une adaptation du jeu de société Cluedo.', 'https://fr.wikipedia.org/wiki/Clue_(jeu_vid%C3%A9o)'),
  ('Q2527522', 'Batman Forever est un beat them all d''Acclaim, sorti en 1995, basé sur le film Batman Forever de Joel Schumacher (lui-même sorti en 1995).', 'https://fr.wikipedia.org/wiki/Batman_Forever_(jeu_vid%C3%A9o)'),
  ('Q93655', 'The Humans est un jeu vidéo de réflexion développé par Imagitec Design et édité par GameTek en 1992 sur micro-ordinateurs et consoles. Atari a édité le jeu sur Jaguar, Atari Falcon 030 et Lynx, respectivement sous les titres Evolution: Dino Dudes et Dinolympics.', 'https://fr.wikipedia.org/wiki/The_Humans'),
  ('Q100096', 'Mega Man X2 est un jeu d''action-plates-formes développé et édité par Capcom sur Super Nintendo en 1995, puis sur téléphone mobile et les Consoles virtuelles (Wii, Wii U), New Nintendo 3DS). C''est la suite du jeu Mega Man X et le second volet de la série Mega Man X.', 'https://fr.wikipedia.org/wiki/Mega_Man_X2'),
  ('Q3007953', 'Cutthroat Island est un jeu vidéo de plate-forme sorti en 1996 sur Game Boy, Game Gear, Mega Drive et Super Nintendo. Le jeu a été développé par Software Creations puis édité par Acclaim.

Il s''agit de l''adaptation du film L''Île aux pirates de Renny Harlin, sorti en 1995.', 'https://fr.wikipedia.org/wiki/Cutthroat_Island'),
  ('Q3064872', 'Famicom Tantei Club Part II: Ushiro ni Tatsu Shōjo est un jeu vidéo d''aventure sorti au Japon en 1989 sur Famicom Disk System. Il fait suite à Famicom Tantei Club: Kieta Kōkeisha sorti l''année précédente.

Il s''agit d''un jeu aventure où le joueur mène des investigations sur plusieurs affaires criminelles au cœur d''un récit très développé. Il est souvent comparé à un roman interactif.

En 1998, le jeu est porté sur Super Famicom. La version originale est ressortie en 2004 sur Game Boy Advance dans la collection Famicom Mini. Toutes les versions du jeu ne sortirent qu''au Japon, la version Super Nintendo fut toutefois traduite puis émulée en anglais. Un remake des deux premiers jeux de la série sort sous le nom de Famicom Detective Club: The Missing Heir & Famicom Detective Club: The Girl Who Stands Behind en 2021, marquant la première fois ou le jeu est accessible en dehors du Japon.', 'https://fr.wikipedia.org/wiki/Famicom_Tantei_Club_Part_II:_Ushiro_ni_Tatsu_Sh%C5%8Djo'),
  ('Q3020587', 'Deadly Moves (nommé aussi Power Moves sur Super Nintendo et Power Athlete au Japon) est un jeu vidéo de combat sorti en 1992 sur Mega Drive et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Deadly_Moves'),
  ('Q3021810', 'Mickey''s Ultimate Challenge est un jeu vidéo de plate-forme et de réflexion sorti en 1994 sur Super Nintendo, Game Boy, Mega Drive, Master System et Game Gear.', 'https://fr.wikipedia.org/wiki/Mickey%27s_Ultimate_Challenge'),
  ('Q2986962', 'Kirby''s Ghost Trap (ou Kirby''s Avalanche en Amérique du Nord) est un jeu vidéo de puzzle sorti en 1995 sur Super Nintendo. Le titre est la version occidentale de Super Puyo Puyo se déroulant dans l''univers de Kirby. Il est le deuxième jeu de la série Puyo Puyo à sortir en Amérique du Nord et en Europe, le premier étant Dr. Robotnik''s Mean Bean Machine.', 'https://fr.wikipedia.org/wiki/Kirby%27s_Ghost_Trap'),
  ('Q2527906', 'The Death and Return of Superman (La Mort et le Retour de Superman) est un jeu vidéo de type beat them all sorti en 1994 sur Super Nintendo, puis en 1995 sur Mega Drive. Le jeu a été développé par Blizzard Entertainment et édité par Sunsoft. Le scénario de The Death and Return of Superman est basé sur l''histoire du comics La mort de Superman.

De nombreux personnages de l’univers de Superman y sont inclus, tels que Superboy, Eradicator ou encore Doomsday.', 'https://fr.wikipedia.org/wiki/The_Death_and_Return_of_Superman'),
  ('Q162562', 'Soul Blazer, sorti au Japon sous le nom Soul Blader, est un jeu vidéo d''action-RPG sorti en 1992 sur Super Nintendo. Le jeu a été développé par Quintet puis édité par Enix.', 'https://fr.wikipedia.org/wiki/Soul_Blazer'),
  ('Q172113', 'Fever Pitch Soccer (Head-On Soccer aux États-Unis) est un jeu vidéo de football sorti en 1995 sur Jaguar, Mega Drive et Super Nintendo. Le jeu a été développé et édité par U.S. Gold sur Mega Drive et Super Nintendo; tandis qu''Atari a assuré l''édition du jeu sur la console Jaguar.', 'https://fr.wikipedia.org/wiki/Fever_Pitch_Soccer'),
  ('Q3062978', 'F1 Pole Position 2 (Human Grand Prix II au Japon) est un jeu vidéo sorti en 1994 sur Super Nintendo. Cette simulation de Formule 1 utilise le Mode 7 utilisé par son prédécesseur, F1 Pole Position. Il s''agit du deuxième et dernier jeu de la série F1 Pole Position paru sur Super Nintendo en Europe. Cependant, deux suites sont éditées au Japon, respectivement nommées Human Grand Prix III et Human Grand Prix IV: F1 Dream Battle.

Bien que paru en octobre 1994, le jeu reprend la saison 1993 et les 16 grand prix qu’elle compte. Celui-ci possédant les licences de la FIA et de la FOCA, on y retrouve 14 véritables pilotes de 7 écuries ayant concouru le championnat 1993. À noter cependant l''absence d''Ayrton Senna (McLaren), dont les droits étaient détenus par Sega et son jeu Super Monaco GP II. C''est donc Mika Häkkinen qui remplace le pilote brésilien, son coéquipier étant Michael Andretti. Or, dans la réalité, c''est ce dernier qui a été remplacé par Mika Häkkinen en cours de saison en raison de résultats insuffisants (Ayrton Senna ayant réalisé l''intégralité de la saison). Ils n''ont donc jamais été coéquipiers en dehors du jeu vidéo.', 'https://fr.wikipedia.org/wiki/F1_Pole_Position_2'),
  ('Q3062976', 'F1 Pole Position (au Japon Human Grand Prix sur Super Nintendo et Nakajima Satoru Kanshuu F-1 Hero GB ''92 sur Game Boy) est un jeu vidéo sorti en 1993 sur Super Nintendo. Cette simulation de Formule 1 utilise le Mode 7.

Le jeu reprend la saison 1992 et les 16 grand prix qu’elle compte.

Le jeu possédant les licences de la FIA et de la FOCA, on y retrouve 14 véritables pilotes issus de 7 écuries ayant concouru le championnat 1992. Parmi les pilotes présents figure Mark Blundell, pilote essayeur pour McLaren Racing n''ayant disputé aucun grand prix cette année-là. Sa présence dans le jeu est due à l''impossibilité pour les développeurs d''inclure Ayrton Senna, dont les droits étaient détenus par Sega et son jeu Super Monaco GP II.', 'https://fr.wikipedia.org/wiki/F1_Pole_Position'),
  ('Q3051587', 'Mega Man and Bass (Rockman & Forte au Japon) est un jeu d''action-plates-formes développé et édité par Capcom en 1998 sur Super Famicom au Japon, puis porté en 2002 sur Game Boy Advance et édité dans le monde entier. C''est un jeu dérivé de la série originale Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_and_Bass'),
  ('Q3019391', 'Daze Before Christmas est un jeu vidéo de plates-formes sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Funcom puis édité par SunSoft.', 'https://fr.wikipedia.org/wiki/Daze_Before_Christmas'),
  ('Q2532658', 'Breath of Fire est un jeu vidéo de type RPG, développé par Capcom, sorti sur Super Nintendo en 1993 et réédité sur Game Boy Advance en 2001.

Il s''agit du premier opus de la saga des Breath of Fire développée par Capcom, et fonde les bases scénaristiques qui seront propres à toute la saga Breath of Fire.', 'https://fr.wikipedia.org/wiki/Breath_of_Fire_(jeu_vid%C3%A9o)'),
  ('Q3072796', 'Fire Emblem: Genealogy of the Holy War est un jeu-vidéo de genre tactical RPG sorti le 14 mai 1996 sur Super Famicom, exclusivement au Japon. Le jeu a été développé par Intelligent Systems et édité par Nintendo. C''est le quatrième épisode de la série Fire Emblem et le deuxième sur la console.

Genealogy of the Holy War se déroule sur le continent de Jugdral, divisé en huit pays fondés par les Douze Croisés, un ancien groupe de soldats qui ont mis fin au règne du dragon Loptous grâce à une intervention divine. Un siècle plus tard, une secte cherchant à faire revivre Loptous attise la guerre entre les nations. L''histoire se développe sur deux générations: la première suit le paladin Sigurd, tandis que la seconde suit son fils Seliph, qui s''efforce de vaincre la secte et de venger son père. Le gameplay s''inscrit dans la continuité de la série Fire Emblem, avec des batailles tactiques se déroulant sur des cartes quadrillées, tout en ajoutant les systèmes de triangle d''armes et de soutien, ce dernier ayant impact direct sur le gameplay et l''histoire.', 'https://fr.wikipedia.org/wiki/Fire_Emblem:_Genealogy_of_the_Holy_War'),
  ('Q2588801', 'Trials of Mana (originellement sorti au Japon sous le titre Seiken densetsu 3) est un jeu vidéo de type action-RPG développé et édité par l''entreprise japonaise Square. Il est sorti au Japon sur Super Famicom en septembre 1995, puis en Occident en 2019 sur Nintendo Switch dans la compilation Collection of Mana sous le titre Trials of Mana.

Il constitue le troisième épisode de la série appelée Seiken densetsu au Japon, et Mana dans le reste du monde. Ce jeu est souvent appelé en occident Secret of Mana 2, bien que ce nom n''ait jamais été enregistré ou annoncé par Square.

Le joueur peut choisir trois personnages pour un total de six, afin d''assembler le groupe qu''il dirige le long de l''aventure, dont le déroulement diffère en fonction du premier personnage sélectionné. Trois scénarios et six introductions différentes sont disponibles au total. À chaque scénario correspond un boss final différent. Chaque personnage possède un certain nombre de classes à choisir, chaque classe donnant des capacités différentes au personnage. Le jeu utilise un système de temps, qui inclut des transitions entre jour et nuit en temps réel, et gère même chaque jour de la semaine.', 'https://fr.wikipedia.org/wiki/Trials_of_Mana'),
  ('Q3077148', 'Foreman For Real est un jeu vidéo de boxe sorti en 1995 sur Game Boy, Game Gear, Mega Drive et Super Nintendo. Le jeu a été développé par Software Creations et édité par Acclaim.', 'https://fr.wikipedia.org/wiki/Foreman_For_Real'),
  ('Q3018106', 'Ultraman: Towards the Future, ou simplement Ultraman au Japon, est un jeu de combat un contre un en 2D à thème de superhéros. Il est édité et développé par Bandai à sa sortie en 1991 sur Super Nintendo et édité par Ma-Ba et développé par Tsuburaya à sa sortie en 1993 sur Mega Drive. Il est basé sur la série télévisée japonaise Ultraman.', 'https://fr.wikipedia.org/wiki/Ultraman_(jeu_vid%C3%A9o,_1991)'),
  ('Q2529000', 'EarthBound, connu au Japon sous le nom Mother 2: Gyiyg Strikes Back, est un jeu vidéo de rôle, développé par Ape et HAL Laboratory (crédité sous le nom de HALKEN), sorti sur Super Nintendo en 1994 au Japon et en 1995 en Amérique du Nord. Cette version du jeu n''est jamais sortie en Europe.

Le jeu est ressorti sur Game Boy Advance dans la compilation Mother 1+2 en 2003 au Japon, et sur la console virtuelle de la Wii U le 20 mars 2013 au Japon, et le 18 juillet 2013 en Amérique du Nord et en Europe.', 'https://fr.wikipedia.org/wiki/EarthBound'),
  ('Q2565615', 'Fire Emblem: Mystery of the Emblem est un tactical RPG sorti en 1994 sur Super Famicom, au Japon exclusivement. Le jeu a été développé par Intelligent Systems et édité par Nintendo. C''est le troisième opus de la série Fire Emblem, et le premier sorti sur Super Famicom.

Le jeu se divise en deux scénarios distincts, qualifiés de "Livres", d''une longueur similaire. Le "Livre 1" est un remake légèrement raccourci du premier jeu de la série, Fire Emblem: Shadow Dragon & the Blade of Light, sorti en 1990 sur Famicom. Le "Livre 2" est un nouveau scénario faisant suite à l''histoire du premier et approfondissant l''univers du jeu.', 'https://fr.wikipedia.org/wiki/Fire_Emblem:_Mystery_of_the_Emblem'),
  ('Q3008213', 'Cyborg 009 est un jeu vidéo d''action plates-formes en 2D à défilement horizontal à thème de science-fiction. Il s''agit d''une adaptation du manga éponyme Cyborg 009 de Shotaro Ishinomori. Le jeu a été développé par Riot et édité par Riot et Interbec. Il est sorti uniquement au Japon, le 30 juillet 1993 sur Mega Drive puis le 25 février 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Cyborg_009_(jeu_vid%C3%A9o)'),
  ('Q3181985', 'John Madden American Football (ou John Madden Football) est un jeu vidéo de football américain sorti en 1990 sur Mega Drive et Amiga. Le jeu a été développé par Park Place Productions et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/John_Madden_Football_(jeu_vid%C3%A9o,_1990)'),
  ('Q3171670', 'Radical Rex est un jeu vidéo de plates-formes à thème de dinosaures sorti en 1994 sur Mega Drive, Mega-CD et Super Nintendo. Le jeu a été développé par Beam Software et édité par Activision.', 'https://fr.wikipedia.org/wiki/Radical_Rex'),
  ('Q3155973', 'Itoi Shigesato no Bass Tsuri No. 1 est un jeu vidéo de pêche sorti en 1997 sur Super Nintendo et en 2001 sur Nintendo 64. Le jeu a été développé par HAL Laboratory et édité par Nintendo.

La version sur Nintendo 64 est la Definitive Edition, c''est-à-dire une version améliorée.', 'https://fr.wikipedia.org/wiki/Itoi_Shigesato_no_Bass_Tsuri_No._1'),
  ('Q1063119', 'Super Mario RPG: Legend of the Seven Stars, ou simplement Super Mario RPG au Japon, est un jeu vidéo d''action-RPG développé par Square et édité par Nintendo sur Super Nintendo. Il est sorti le 9 mars 1996 au Japon et le 13 mai 1996 en Amérique du Nord. Il s''agit du premier jeu de rôle de la série Mario. Le jeu possède des similitudes avec d''autres jeux de rôle de Square, comme Chrono Trigger et la série Final Fantasy, mais l''histoire s''inscrit tout de même dans l''univers de Super Mario Bros..

Celle-ci suit Mario et ses coéquipiers, décidés à éliminer Forgeroi, le principal antagoniste qui a dérobé les sept étoiles de la Route étoilée, route où tous les vœux sont exaucés. Super Mario RPG propose un total de cinq personnages jouables. Il a été réalisé par Yoshihiko Maekawa et Chihiro Fujioka et produit par Shigeru Miyamoto. Yoko Shimomura a composé la musique du jeu, qui a par ailleurs donné lieu à un album.', 'https://fr.wikipedia.org/wiki/Super_Mario_RPG:_Legend_of_the_Seven_Stars'),
  ('Q3036891', 'Doom Troopers: The Mutant Chronicles est un jeu vidéo d''action sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé par Adrenaline Entertainment et Western Technologies puis édité par Playmates Interactive.

Le jeu est situé dans l''univers de Mutant Chronicles.', 'https://fr.wikipedia.org/wiki/Doom_Troopers:_The_Mutant_Chronicles'),
  ('Q2604921', 'Bahamut Lagoon est un jeu vidéo de type tactical RPG développé et édité par la société japonaise Square. Il sort sur Super Nintendo en février 1996 uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Bahamut_Lagoon'),
  ('Q1992329', 'The Combatribes est un jeu d''action de type beat them all en 2D développé et édité par Technos Japan, se déroulant dans un univers urbain. Il est sorti sur arcade puis porté sur Super Nintendo en 1992 au Japon et 1993 en Amérique du Nord. Le jeu est ressorti sur la Console virtuelle Wii en 2009.', 'https://fr.wikipedia.org/wiki/The_Combatribes'),
  ('Q1071730', 'Panel de Pon est un jeu de puzzle développé par Intelligent Systems, et sorti au Japon le 27 octobre 1995 sur Super Famicom. Le jeu est lancé aux États-Unis environ un an plus tard dans une nouvelle version connue sous le nom de Tetris Attack, jouable avec plusieurs personnages du jeu Yoshi''s Island. Le concept est repris plus tard avec Pokémon Puzzle League sur Nintendo 64.

Le jeu sorti en compilation avec Dr. Mario sur Game Boy Advance. Une nouvelle version apparaît également au Japon sur GameCube dans Nintendo Puzzle Collection.

Depuis mai 2020, la version originale Panel de Pon sur Super Nintendo est jouable sur le Nintendo Switch Online, pour la toute première fois dans le monde entier. Le jeu n''est toutefois pas traduit, et la version occidentale n''est pas proposée car elle impliquerait l''utilisation de la licence Tetris.', 'https://fr.wikipedia.org/wiki/Panel_de_Pon'),
  ('Q1045765', 'Super Mario World 2: Yoshi''s Island est un jeu de plate-forme de Nintendo sorti en 1995 sur Super Nintendo, puis en 2002 sur Game Boy Advance sous le titre Yoshi''s Island: Super Mario Advance 3. Il a été réédité sur Nintendo Switch en 2019.

Shigeru Miyamoto et son équipe ont dû mettre en valeur un style graphique particulier, face au comité d''évaluation de Nintendo qui s''attendait plutôt à voir des graphismes en images de synthèse pré-rendues comme l''avait utilisé Donkey Kong Country.

Dans la lignée du premier opus, un deuxième est sorti sur Nintendo DS, à savoir Yoshi''s Island DS, ainsi qu''un troisième du nom de Yoshi''s New Island sur Nintendo 3DS.', 'https://fr.wikipedia.org/wiki/Super_Mario_World_2:_Yoshi%27s_Island'),
  ('Q3176904', 'Jelly Boy est un jeu vidéo de plates-formes sur Game Boy, et Super Nintendo. Le jeu a été développé par Probe Entertainment et édité par Ocean Software et Electronic Arts. Le jeu avait aussi été annoncé sur Mega Drive mais a ensuite été annulé.', 'https://fr.wikipedia.org/wiki/Jelly_Boy'),
  ('Q3046155', 'ESPN National Hockey Night est un jeu vidéo de hockey sur glace sorti en 1994 sur PC, Mega-CD, Mega Drive et Super Nintendo. Le jeu a été développé par Stormfront Studios et édité par Sony Imagesoft.', 'https://fr.wikipedia.org/wiki/ESPN_National_Hockey_Night_(jeu_vid%C3%A9o,_1994)'),
  ('Q3028391', 'Dino Dini''s Soccer est un jeu vidéo de football conçu par Dino Dini, le créateur de la série Kick Off, et édité par Virgin Interactive en 1994 sur Mega Drive et Super Nintendo.

Il s''agit d''une conversion du jeu Goal! (1993).', 'https://fr.wikipedia.org/wiki/Dino_Dini%27s_Soccer'),
  ('Q196255', 'Street Fighter II'': Hyper Fighting (Street Fighter II'' Turbo: Hyper Fighting au Japon) est un jeu de combat en un contre un développé et édité par Capcom en décembre 1992 sur système d''arcade CP System. Il a été porté sur de nombreuses plates-formes, parmi lesquelles la Super Nintendo.

Cette version est la deuxième amélioration de la série Street Fighter II, après Street Fighter II'': Champion Edition. Il s''agit d''une simple modification du jeu effectuée par Capcom USA (James Goddard) dans l''espoir de contrer la prolifération des nombreux hacks non officiels de la seconde version disponibles à l''époque, et d''incorporer dans le jeu officiel certaines des améliorations les plus populaires apportées par ceux-ci, notamment l''augmentation de la vitesse des personnages ainsi que de nouvelles palettes de couleur sur certains hacks.', 'https://fr.wikipedia.org/wiki/Street_Fighter_II%27:_Hyper_Fighting'),
  ('Q3046163', 'ESPN Sunday Night NFL est un jeu vidéo de football américain sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Absolute Entertainment et édité par Sony Imagesoft.', 'https://fr.wikipedia.org/wiki/ESPN_Sunday_Night_NFL'),
  ('Q3190155', 'Jurassic Park est un jeu vidéo d''action, développé par Ocean Software, sorti sur Super Nintendo, NES et Game Boy, ainsi que sur Amiga, Amiga 1200 et PC en 1993.', 'https://fr.wikipedia.org/wiki/Jurassic_Park_(Ocean_Software)'),
  ('Q2607689', 'Castlevania: Vampire''s Kiss, connu au Japon sous le nom Akumajō Dracula XX et Castlevania: Dracula X en Amérique du Nord, est un jeu vidéo d''action et de plates-formes sorti en 1995 sur Super Nintendo. Le jeu est développé par Konami / KCEO et édité par Konami.', 'https://fr.wikipedia.org/wiki/Castlevania:_Vampire%27s_Kiss'),
  ('Q3043052', 'Star Ocean est un jeu vidéo d’action et de rôle développé par tri-Ace et édité par Enix pour la Super Famicom. Premier jeu de la série Star Ocean, il n’est sorti qu’au Japon en juillet 1996, et a été le premier jeu développé par tri-Ace, composé d’un personnel qui avait précédemment quitté la Wolf Team en raison de différents lors du processus de développement de Tales of Phantasia avec Namco en 1995. Le jeu utilisait une puce de compression spéciale dans sa cartouche pour compresser et stocker toutes les données du jeu en raison de la possession de graphismes qui repoussaient les limites de la Super Famicom. De plus, le jeu avait un doublage pour l’intro du jeu et des clips vocaux qui jouaient pendant le gameplay de bataille du jeu, une rareté pour les jeux sur le système.', 'https://fr.wikipedia.org/wiki/Star_Ocean_(jeu_vid%C3%A9o)'),
  ('Q3130597', 'Marvel Super Heroes in War of the Gems est un jeu vidéo de plates-formes/beat them all développé et édité par Capcom en 1996 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Marvel_Super_Heroes_in_War_of_the_Gems'),
  ('Q1984081', 'First Samurai est un jeu vidéo développé par la société anglaise Vivid Image, sorti en 1991. C''est un jeu d''action 2D à défilement qui mêle du combat et de la plates-formes: le joueur incarne un samouraï projeté dans le Japon du XXIVe siècle pour venger la mort de son sensei. Le jeu a été conçu par Raffaele Cecco et est sorti sur les ordinateurs Amiga (1991), Atari ST, Commodore 64, PC (1992) et la console Super Nintendo (1993).

Il a donné suite à Second Samurai en 1993.', 'https://fr.wikipedia.org/wiki/First_Samurai'),
  ('Q1970300', 'ESPN Speed World est un jeu vidéo de course sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Sony Imagesoft.', 'https://fr.wikipedia.org/wiki/ESPN_Speed_World'),
  ('Q3022202', 'Demolition Man est un jeu vidéo d''action, développé par Alexandria Inc et édité par Acclaim, sorti sur Mega Drive, Mega-CD, Super Nintendo, 3DO en 1995.

Il est basé sur le film Demolition Man de Marco Brambilla, sorti en 1993.', 'https://fr.wikipedia.org/wiki/Demolition_Man_(jeu_vid%C3%A9o)'),
  ('Q1987042', '3 Ninjas Kick Back est un jeu vidéo d''action et de plates-formes développé par Malibu Interactive et édité par Psygnosis, sorti en 1994 sur Mega Drive, Mega-CD, et Super Nintendo.

Il s''agit d''une adaptation du film Les trois ninjas contre-attaquent.', 'https://fr.wikipedia.org/wiki/3_Ninjas_Kick_Back'),
  ('Q3138599', 'Hit the Ice est un jeu vidéo de hockey sur glace développé par Williams Electronics Games, sorti en 1990 sur borne d''arcade. Il a été adapté sur Nintendo Entertainment System (1990), PC Engine (1991), Mega Drive (1992) et Super Nintendo (1993). Des versions Game Boy et Game Gear ont également vu le jour.', 'https://fr.wikipedia.org/wiki/Hit_the_Ice'),
  ('Q1984719', 'Spider-Man and Venom: Maximum Carnage est un jeu vidéo de type beat them all sorti en Amérique du Nord le 16 septembre 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Software Creations et édité par LJN (une filiale d''Acclaim). Il est basé sur la saga de comics Spider-Man en 14 parties intitulée Maximum Carnage. Une suite est sortie en 1995 portant le nom Spider-Man and Venom: Separation Anxiety.', 'https://fr.wikipedia.org/wiki/Spider-Man_and_Venom:_Maximum_Carnage'),
  ('Q1001925', 'Flashback (réalisé en France et connu aux États-Unis sous le nom Flashback: The Quest for Identity, littéralement Flashback: La Quête de l''identité) est un jeu vidéo de plates-formes et d''action réalisé par Delphine Software en 1992, sorti sur Amiga la même année et sur les autres supports par la suite.

Un remake également nommé Flashback a été développé par VectorCell et est sorti en 2013 sur PC, PlayStation 3 et Xbox 360.', 'https://fr.wikipedia.org/wiki/Flashback_(jeu_vid%C3%A9o,_1992)'),
  ('Q3190026', 'Jungle Strike est un jeu vidéo d''action développé par High Score Production et édité par Electronic Arts en 1993. Initialement sorti sur Mega Drive et Super Nintendo, il a par la suite été commercialisé sur Amiga, Amiga CD32, DOS, Game Gear et Game Boy.

Il s''agit de la suite de Desert Strike: Return to the Gulf.', 'https://fr.wikipedia.org/wiki/Jungle_Strike'),
  ('Q3038911', 'Drakkhen est un jeu vidéo de rôle français dans un monde ouvert médiéval fantastique (heroic fantasy), en vue à la troisième personne et mêlant 3D en temps réel et 2D. L’intrigue, sur fond de prophétie mystique, se déroule sur une ile-continent de 64 km2 peuplée par différentes races reptiliennes.

En termes de gameplay, le joueur dirige une équipe de quatre humains qui voyageront librement, de jour comme de nuit, dans divers environnements extérieurs et qui exploreront plusieurs donjons, engageant des combats et utilisant de la magie afin d’accomplir une unique quête principale.

Le scénario est original, les tenants et les aboutissants auront été présentés au joueur dans la boite de jeu au travers d’une nouvelle inédite et autres documents imprimés dans un livret physique réel illustré de 80 pages qu''il sera nécessaire de lire au préalable, le jeu commençant immédiatement après avoir été lancé sans autre introduction supplémentaire.', 'https://fr.wikipedia.org/wiki/Drakkhen'),
  ('Q1985746', 'The King of Dragons est un jeu vidéo de type beat them all développé et édité par Capcom sur CP System en juillet 1991.', 'https://fr.wikipedia.org/wiki/The_King_of_Dragons'),
  ('Q1026590', 'Mario''s Super Picross est un jeu vidéo de puzzle développé par Ape Incorporated, Jupiter et édité par Nintendo, sorti à partir de 1995 sur Super Nintendo. Il reprend le principe du picross, jeu de chiffres sur grille. Il n''est sorti à l''origine qu''au Japon, après l''échec commercial de Mario''s Picross en Amérique du Nord, mais il est sorti par la suite sur la Console Virtuelle européenne de la Wii le 14 septembre 2007, puis sur celle de la Wii U le 27 avril 2013.', 'https://fr.wikipedia.org/wiki/Mario%27s_Super_Picross'),
  ('Q2619370', 'Kirby''s Dream Course est un jeu vidéo de golf sorti en 1994 sur Super Nintendo, développé par HAL Laboratory et édité par Nintendo.', 'https://fr.wikipedia.org/wiki/Kirby%27s_Dream_Course'),
  ('Q1112940', 'Columns, aussi appelé Jewels ou Shapes and Columns, est un jeu vidéo de puzzle conçu par Jay Geertsen en 1989. Après en avoir racheté les droits, Sega a commercialisé le jeu sur borne d''arcade en 1990 et de multiples adaptations sur supports familiaux ont suivi, notamment sur les consoles Sega. Le jeu a également engendré plusieurs suites. Le jeu a été porté en 2002 dans une version homebrew sur Neo-Geo MVS.', 'https://fr.wikipedia.org/wiki/Columns_(jeu_vid%C3%A9o)'),
  ('Q1141946', 'Final Fight est un jeu vidéo de type Beat them up développé et édité par Capcom sur système d''arcade CP System en 1989. Considéré comme une référence du genre, le jeu a rencontré un important succès populaire et a été porté sur divers plates-formes.

Ce jeu est le premier volet de la série Final Fight.', 'https://fr.wikipedia.org/wiki/Final_Fight_(jeu_vid%C3%A9o)'),
  ('Q3292201', 'NBA Live 95 est un jeu vidéo de basket-ball sorti en 1994 et fonctionne sur Super Nintendo, Mega Drive et PC. Le jeu a été développé par EA Sports, puis édité par Electronic Arts. C''est la première édition de la série NBA Live.', 'https://fr.wikipedia.org/wiki/NBA_Live_95'),
  ('Q3298503', 'Math Blaster: Episode 1 est un jeu vidéo ludo-éducatif sorti en 1994 et fonctionne sur Mega Drive, DOS et Super Nintendo. Le jeu a été développé par Western Technologies et édité par Davidson and Associates.', 'https://fr.wikipedia.org/wiki/Math_Blaster:_Episode_1'),
  ('Q3296242', 'Mary Shelley''s Frankenstein est un jeu vidéo d''action sorti en 1994 sur Mega-CD, Mega Drive et Super Nintendo. Le jeu a été développé par BITS Corporation et édité par Sony Imagesoft.

Le jeu sort en même temps que le film du même nom, inspirés librement du roman Frankenstein ou le Prométhée moderne de Mary Shelley.', 'https://fr.wikipedia.org/wiki/Mary_Shelley%27s_Frankenstein'),
  ('Q3198012', 'Knights of the Round est un jeu vidéo de beat them all pouvant se jouer à trois simultanément développé et édité par Capcom sur système d''arcade CP System. Le jeu a également été adapté sur Super Nintendo l''année suivante puis en 2006 sur PlayStation 2, Xbox et PlayStation Portable.', 'https://fr.wikipedia.org/wiki/Knights_of_the_Round'),
  ('Q1194825', 'Super Metroid (parfois Metroid 3) est un jeu d''action-aventure développé par Nintendo R&D1 et Intelligent Systems, et édité par Nintendo sur Super Nintendo en mars 1994 au Japon, puis en avril aux États-Unis et en juillet en Europe. C''est le troisième jeu de la série Metroid, dont l''intrigue prend place après les événements qui se déroulent dans Metroid II: Return of Samus sorti en 1991 sur Game Boy. Au cours de son périple, la chasseuse de primes Samus Aran explore la planète Zèbes dans le but de retrouver une larve Metroid dérobée par les Pirates de l''espace et l''un de leurs leaders Ridley.

L''équipe de développement du précédent opus est reconduite, en particulier Yoshio Sakamoto, Makoto Kanoh, et le processus dure deux ans et demi. L''objectif est de réaliser un vrai jeu d''action. Le système de jeu est centré sur l''exploration et la découverte de power-ups, qui permettent au joueur d''accéder à de nouvelles zones auxquelles il ne pouvait précédemment pas se rendre. Le jeu intègre de nouveaux concepts dans la série, tels que l''écran d''inventaire, la mini-carte, ou la possibilité de tirer dans plusieurs directions.', 'https://fr.wikipedia.org/wiki/Super_Metroid'),
  ('Q2632064', 'Fire Emblem: Thracia 776 est un jeu-vidéo de genre tactical RPG développé par Intelligent Systems et édité par Nintendo, sorti sur Super Famicom au Japon exclusivement. C''est le cinquième volet de la saga Fire Emblem et le dernier opus sorti sur la console.

Le jeu se déroule dans le même univers que son prédécesseur Fire Emblem: Genealogy of the Holy War, sorti en 1996 sur la même plate-forme. Il approfondit son univers et se focalise plus particulièrement sur l''histoire de Leif, l''un des personnages du jeu précédent.

Disponible dès le 1er septembre 1999 grâce au service Nintendo Power, la version cartouche fut mise en vente le 21 janvier 2000. Il s''agit du dernier jeu au format cartouche paru sur la Super Famicom. Une édition collector Deluxe comprenant en plus du jeu, deux peluches, une carte du monde et une cassette vidéo était également disponible.', 'https://fr.wikipedia.org/wiki/Fire_Emblem:_Thracia_776'),
  ('Q3190158', 'Jurassic Park Part 2: The Chaos Continues est un jeu vidéo de plate-forme / action, développé par Ocean Software, sorti sur Super Nintendo et Game Boy en 1994.

C''est une suite directe à Jurassic Park sorti un an plus tôt sur Super Nintendo et n''est pas du tout lié à Le Monde perdu: Jurassic Park qui est le deuxième film.', 'https://fr.wikipedia.org/wiki/Jurassic_Park_Part_2:_The_Chaos_Continues'),
  ('Q2628712', 'EVO: Search for Eden est un jeu vidéo édité par Enix sur Super Nintendo en 1992, dont le scénario suit l''évolution sur plusieurs centaines de millions d''années.', 'https://fr.wikipedia.org/wiki/EVO:_Search_for_Eden'),
  ('Q1152450', 'Fatal Fury 2 est un jeu vidéo de combat en 2D développé et édité par SNK en 1992 sur borne d''arcade Neo-Geo MVS et sur consoles Neo-Geo AES et en 1994 sur Neo-Geo CD (NGM / NGH 047). Le jeu fut adapté sur Mega Drive, PC Engine et Super Nintendo.

Il s''agit du deuxième épisode de la série Fatal Fury.', 'https://fr.wikipedia.org/wiki/Fatal_Fury_2'),
  ('Q1305295', 'Pilotwings est un jeu vidéo de simulation aérienne développé par Nintendo, sorti en 1990 sur Super Nintendo. C''est une simulation de vol dans lequel le joueur peut utiliser un avion biplan, un deltaplane, un parachute et un jetpack. Le jeu utilise le Mode 7 pour simuler des environnements avec un effet de profondeur.

Une première suite, Pilotwings 64, est publiée sur Nintendo 64 en 1996 et une seconde, Pilotwings Resort, pour la sortie de la Nintendo 3DS en 2011.', 'https://fr.wikipedia.org/wiki/Pilotwings_(jeu_vid%C3%A9o)'),
  ('Q3194351', 'Kawasaki Superbikes (ou Kawasaki Superbike Challenge en Amérique du Nord) est un jeu vidéo de course de moto sorti en 1994 sur Game Gear, Mega Drive et Super Nintendo. Développé par Lankhor et édité par Domark, le jeu a été conçu par Chris Johnson. Kawasaki Superbikes exploite le même moteur de jeu que F1. Il utilise la licence de la marque Kawasaki.', 'https://fr.wikipedia.org/wiki/Kawasaki_Superbikes'),
  ('Q3195035', 'Ken Griffey Jr. Presents Major League Baseball est un jeu vidéo de baseball sorti en 1994 sur Super Nintendo et sur Game Boy. Le jeu a été développé par Software Creations.', 'https://fr.wikipedia.org/wiki/Ken_Griffey_Jr._Presents_Major_League_Baseball'),
  ('Q1202713', 'Kirby''s Dream Land 3, appelé Hoshi no Kirby 3 au Japon, est un jeu vidéo de plate-forme de la série des Kirby, développé par HAL Laboratory et édité par Nintendo, sorti sur Super Nintendo en 1997 en Amérique du Nord et en 1998 au Japon.

Il est le dernier jeu produit par Nintendo pour la Super Nintendo aux États-Unis et n''est jamais sorti en Europe. Il est cependant disponible sur ce continent via la Console virtuelle de la Wii et le Nintendo Switch Online de la Nintendo Switch.', 'https://fr.wikipedia.org/wiki/Kirby%27s_Dream_Land_3'),
  ('Q2708224', 'Aero the Acro-Bat est un jeu vidéo de plates-formes développé par Iguana Entertainment et édité par Sunsoft, sorti sur Mega Drive et Super Nintendo en 1993, puis converti sur Game Boy Advance en 2002.', 'https://fr.wikipedia.org/wiki/Aero_the_Acro-Bat'),
  ('Q3235344', 'Les Schtroumpfs autour du monde est un jeu vidéo de plates-formes sorti en 1995 sur Game Boy et Master System, puis en 1996 sur Game Gear, Mega Drive et Super Nintendo. Le jeu a été développé par Virtual Studio et édité par Infogrames. Il est basé sur la bande-dessinée du même nom et sur la série animée. Le jeu fait suite à Les Schtroumpfs sorti en 1993 et est suivi par Le Cauchemar des Schtroumpfs sorti en 1997.

La version pour Master System est aussi le dernier jeu commercialisé pour cette console en Europe.', 'https://fr.wikipedia.org/wiki/Les_Schtroumpfs_autour_du_monde'),
  ('Q3197143', 'Kingyo Chūihō! Tobidase Game Gakuen est un jeu vidéo de type party game sorti sur Super Nintendo développé par Jaleco sorti au Japon le 18 mars 1994. Le jeu est une adaptation du manga Goldfish Warning!.', 'https://fr.wikipedia.org/wiki/Kingyo_Ch%C5%ABih%C5%8D!_Tobidase_Game_Gakuen'),
  ('Q3275484', 'Madden NFL ''95 est un jeu vidéo de football américain sorti en 1994 et fonctionne sur Mega Drive, Super Nintendo, Game Boy et Game Gear. Le jeu a été développé et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Madden_NFL_%2795'),
  ('Q2016892', 'Battletoads in Battlemaniacs est un jeu vidéo de type beat them all développé par Rare et édité par Tradewest pour la Super Nintendo Entertainment System. Le jeu est sorti en Amérique du Nord en juin 1993, en Europe en octobre 1993 et au Japon le 7 janvier 1994. Il a également été porté sur la Sega Master System pour une sortie exclusivement au Brésil.', 'https://fr.wikipedia.org/wiki/Battletoads_in_Battlemaniacs'),
  ('Q2016922', 'Barbie: Super Model est un jeu vidéo d''action et de réflexion sorti en 1993 sur Mega Drive, PC et Super Nintendo. Le jeu a été développé par Tahoe Software et édité par Hi-Tech Expressions.', 'https://fr.wikipedia.org/wiki/Barbie:_Super_Model'),
  ('Q2052338', 'Pocky and Rocky, connu au Japon sous le nom de KiKi KaiKai: Nazo no Kuro Manto, est un jeu vidéo de type shoot them up à défilement comportant également certains traits propres aux jeux d''action. Sa licence est signée Taito et Natsume, qui développa et publia le jeu pour sa version japonaise en 1992 puis pour le reste du monde en 1993. Il se présente comme une suite au jeu d''arcade KiKi KaiKai (sortie officieuse en Amérique du Nord sous le titre de Knight Boy) en 1986 et y poursuit les aventures d''une jeune prêtresse shintoïste appelée Pocky (dans la version japonaise: Sayo-chan) et de son nouveau compagnon, Rocky, probablement un tanuki (portant dans la version japonaise le nom de Manuke).', 'https://fr.wikipedia.org/wiki/Pocky_and_Rocky'),
  ('Q1074008', 'Fatal Fury: King of Fighters est un jeu de combat en 2D développé et édité par SNK en 1991 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES et en 1994 sur Neo-Geo CD (NGM / NGH 033). Le jeu a par la suite été adapté sur Mega Drive et Super Nintendo ainsi que sur Neo-Geo CD (1994).

Il s''agit du premier jeu de la série Fatal Fury. Il marque l''apparition de Terry Bogard, un personnage apprécié des joueurs.', 'https://fr.wikipedia.org/wiki/Fatal_Fury:_King_of_Fighters'),
  ('Q2017312', 'Aaahh!!! Real Monsters est un jeu vidéo d''action et de plates-formes sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé par Realtime Associates et édité par Viacom New Media.

Le jeu repose sur Drôles de monstres (Aaahh!!! Real Monsters), la série d''animation du même nom.', 'https://fr.wikipedia.org/wiki/Aaahh!!!_Real_Monsters_(jeu_vid%C3%A9o)'),
  ('Q2019441', 'Saturday Night Slam Masters est un jeu vidéo de catch développé et édité par Capcom sur CP System [Dash] en décembre 1993. Il a été porté sur Mega Drive et Super Nintendo (et au Japon sur FM Towns Marty).', 'https://fr.wikipedia.org/wiki/Saturday_Night_Slam_Masters'),
  ('Q2016787', 'Barkley: Shut Up and Jam!, ou Barkley''s Power Dunk au Japon, est un jeu vidéo de basket-ball sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Accolade.

Le titre du jeu fait référence à Charles Barkley, célèbre basketteur de la NBA.

Le jeu a pour suite Barkley: Shut Up and Jam! 2. Il a également fait l''objet d''une suite parodique Barkley, Shut Up and Jam: Gaiden.', 'https://fr.wikipedia.org/wiki/Barkley:_Shut_Up_and_Jam!'),
  ('Q2634403', 'ClayFighter est un jeu de combat développé par Visual Concepts et édité par Interplay Entertainment, sorti en 1993 sur Super Nintendo et 1994 sur Mega Drive.

La principale originalité du jeu vient de la représentation des personnages en pâte à modeler.', 'https://fr.wikipedia.org/wiki/ClayFighter'),
  ('Q1239244', 'Populous est un jeu de stratégie en temps réel sur ordinateur, développé par Bullfrog et édité par Electronic Arts en 1989.

Imaginé par Peter Molyneux, Populous est considéré comme l’archétype du jeu de simulation divine (god game), un type de jeu dans lequel le joueur incarne une divinité toute puissante. Il a rencontré un important succès critique et commercial. Initialement développé sur les ordinateurs 16/32 bits Amiga et Atari ST, Populous est adapté sur une dizaine de supports, incluant MS-DOS et les consoles Master System, Mega Drive, Super Nintendo, PC-Engine et Game Boy.', 'https://fr.wikipedia.org/wiki/Populous_(jeu_vid%C3%A9o)'),
  ('Q2634825', 'Troy Aikman NFL Football est un jeu vidéo de sport sorti en 1994 et fonctionne sur Jaguar, Mega Drive et Super Nintendo. Le jeu a été développé et édité par Tradewest.

Le jeu tient son nom du joueur et commentateur Troy Aikman.', 'https://fr.wikipedia.org/wiki/Troy_Aikman_NFL_Football'),
  ('Q1276884', 'Daffy Duck: The Marvin Missions est un jeu vidéo de plates-formes développé par ICOM Simulations et édité par Sunsoft en 1993 sur Super Nintendo. Une autre version a été aussi éditée sur Game Boy.', 'https://fr.wikipedia.org/wiki/Daffy_Duck:_The_Marvin_Missions'),
  ('Q2020509', 'Yogi Bear: Cartoon Capers ou Adventures of Yogi Bear aux États-Unis est un jeu vidéo de plates-formes sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Blue Turtle et édité par Empire Interactive.

Le jeu est basé sur le personnage d''animation Yogi l''ours.', 'https://fr.wikipedia.org/wiki/Yogi_Bear:_Cartoon_Capers'),
  ('Q3275483', 'Madden NFL ''94 est un jeu vidéo de football américain sorti en 1993 et fonctionne sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Madden_NFL_%2794'),
  ('Q2629633', 'Aero the Acro-Bat 2 est un jeu vidéo de plates-formes développé par Iguana Entertainment et édité par Sunsoft, sorti sur Mega Drive et Super Nintendo en 1994.

Il est la suite de Aero the Acro-Bat.

Le jeu est dédié au célèbre coureur brésilien Ayrton Senna, décédé dans un accident de voiture lors d''un Grand Prix.', 'https://fr.wikipedia.org/wiki/Aero_the_Acro-Bat_2'),
  ('Q2040884', 'Front Mission: Gun Hazard est un jeu vidéo de type run and gun développé par Omiya Soft et édité par SquareSoft en 1996 sur Super Famicom, uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Front_Mission:_Gun_Hazard'),
  ('Q3196442', 'Kidō Sōkō Dion, intitulé Imperium aux États-Unis, est un jeu vidéo du type shoot them up par Vic Tokai édité en novembre 1992 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam.', 'https://fr.wikipedia.org/wiki/Kid%C5%8D_S%C5%8Dk%C5%8D_Dion'),
  ('Q2628325', 'Demon''s Crest, ou Demon''s Blazon: Makaimura Monshou hen au Japon, est un jeu vidéo de plates-formes développé par Capcom, sorti sur Super Nintendo en 1994. C''est la suite de Gargoyle''s Quest II sur Nintendo Entertainment System.

Demon''s Blazon est publié au Japon le 21 octobre 1994, les versions occidentales de Demon''s Crest sont publiées en Amérique du Nord en novembre 1994 puis en Europe en février 1995.

La jaquette européenne et américaine, représentant Firebrand, a été réalisée par l''artiste Julie Bell.', 'https://fr.wikipedia.org/wiki/Demon%27s_Crest'),
  ('Q1241664', 'Donkey Kong Country 3: Dixie Kong''s Double Trouble! (ou Super Donkey Kong 3: Nazo no Krem au Japon) est un jeu vidéo de plate-forme sorti sur Super Nintendo en 1996 développé par Rare et créé par Nintendo. Il est réédité sur Game Boy Advance en 2005 et, par le biais du service Virtual Console, sur Wii en 2007 et sur Wii U en 2014.', 'https://fr.wikipedia.org/wiki/Donkey_Kong_Country_3:_Dixie_Kong%27s_Double_Trouble!'),
  ('Q3259253', 'Looney Tunes: Road Runner, connu au Japon sous le nom de Looney Tunes: Road Runner vs. Wile E. Coyote et en Amérique du Nord sous celui de Road Runner''s Death Valley Rally, est un jeu vidéo apparu sur Super Nintendo en 1992, basé sur les personnages des Looney Tunes: Bip Bip et Coyote.', 'https://fr.wikipedia.org/wiki/Looney_Tunes:_Road_Runner'),
  ('Q1249187', 'Mystic Quest Legend est un jeu vidéo de rôle développé par Square Co., Ltd. pour la Super Nintendo Entertainment System, le premier de la franchise Final Fantasy à sortir en Europe et en Australie. Développé au Japon pour le marché nord-américain où il s’appelle Final Fantasy Mystic Quest, le nom a été changé pour l''importation en Europe où on a enlevé la partie Final Fantasy du nom. Au Japon, il est sorti sous le nom de Final Fantasy USA: Mystic Quest.

Plutôt différent du restant de la série Final Fantasy, il a été vendu en tant que « jeu vidéo de rôle pour débutant » avec un guide stratégique de 72 pages, comme de nombreux jeux de rôle sortis en Europe. Le jeu est très facile comparé aux autres jeux de la série. Il inclut un mode automatique qui permet à la console de contrôler le compagnon du héros, pendant les combats, à la place du joueur.', 'https://fr.wikipedia.org/wiki/Mystic_Quest_Legend'),
  ('Q3237821', 'Liberty or Death est un jeu vidéo de stratégie au tour par tour sorti en 1993 sur DOS, Mega Drive et Super Nintendo. Développé et édité par Koei, le jeu a été conçu par Stieg Hedlund. Le jeu simule la guerre d''indépendance des États-Unis. Le joueur incarne George Washington ou William Howe et tente de mener a bien la révolte des treize colonies d''Amérique du Nord contre le Royaume de Grande-Bretagne, ou au contraire d''y mettre fin. Il s''appuie sur un système de jeu similaire à celui de Nobunaga''s Ambition. Il se déroule sur une carte des treize colonies, divisées en provinces, sur laquelle le joueur contrôle des officiers auxquels sont rattachées des unités militaires. Il doit également gérer le recrutement de nouvelles troupes et l''approvisionnement de ses unités.', 'https://fr.wikipedia.org/wiki/Liberty_or_Death'),
  ('Q1072051', 'Donkey Kong Country 2: Diddy''s Kong Quest (ou simplement Donkey Kong Country 2, Diddy''s Kong Quest, et DKC2) est un jeu de plates-formes développé par Rare et édité par Nintendo en novembre 1995 en Amérique du Nord et au Japon, puis en décembre 1995 en Europe. C''est le second jeu de la série Donkey Kong Country et la suite directe du jeu homonyme. L''intrigue est centrée sur Diddy Kong et sa fiancée Dixie Kong qui tentent de secourir Donkey Kong alors qu''il a été capturé par Kaptain K. Rool. L''action se déroule sur l''île aux crocodiles, composée de huit mondes variés totalisant 52 niveaux. Diddy''s Kong Quest utilise la même technique que son prédécesseur, une technologie créée par Silicon Graphics, basée sur une imagerie en trois dimensions pré-rendue. Le jeu profite de nombreuses améliorations, notamment visuelle, mais surtout au niveau du gameplay, plus complexe, plus axé sur l''exploration et qui comporte de nombreux secrets et salles bonus cachées, ainsi que divers objets à collecter. La difficulté et la durée de vie du jeu s''en trouvent sensiblement augmentées.', 'https://fr.wikipedia.org/wiki/Donkey_Kong_Country_2:_Diddy%27s_Kong_Quest'),
  ('Q2702756', 'Super Bomberman est un jeu vidéo réalisé par Hudson Soft. Il s’agit d’un jeu d''action sorti sur Super Nintendo en 1993. Il est le premier opus de la série des Bomberman, et le premier jeu vidéo quatre joueurs sur cette console.', 'https://fr.wikipedia.org/wiki/Super_Bomberman'),
  ('Q1198491', 'F-Zero est un jeu vidéo de course futuriste développé et édité par Nintendo pour la Super Nintendo. Il est sorti au Japon le 21 novembre 1990, en Amérique du Nord le 23 août 1991 et en Europe le 11 avril 1992. Le titre était téléchargeable sur le réseau Nintendo Power au Japon et est aussi sorti sous forme de démo sur le Nintendo Super System en 1991. F-Zero est le premier jeu de la longue série des F-Zero et constitue l''un des deux jeux disponibles au lancement de la Super Nintendo au Japon, tandis qu''il était accompagné d''autres titres lors du lancement en Amérique du Nord et en Europe. Fin 2006, F-Zero a été rendu disponible sur la console virtuelle, plate-forme de téléchargement de la Wii.', 'https://fr.wikipedia.org/wiki/F-Zero_(jeu_vid%C3%A9o)'),
  ('Q2642154', 'Donald in Maui Mallard, ou Maui Mallard in Cold Shadow en Amérique du Nord, est un jeu vidéo de plates-formes sorti en 1995 sur Super Nintendo, Mega Drive et Windows. Le jeu a été développé et édité par Disney Interactive. Il a été porté sur Game Boy en 1998, seulement aux États-Unis.', 'https://fr.wikipedia.org/wiki/Donald_in_Maui_Mallard'),
  ('Q2015417', 'WWF Royal Rumble est un jeu vidéo de catch professionnel développé par Sculptured Software, sorti en 1993 sur Super Nintendo et Mega Drive. Comme son prédécesseur, WWF Super WrestleMania, le jeu est basé sur la société américaine World Wrestling Federation. Il met en avant de différents types de matchs dont le nouveau Royal Rumble. Il met également en scène les catcheurs travaillant à l''époque pour la WWF, et chacune des versions du jeu possède ses cinq propres personnages exclusifs. Il précède le jeu Sega Mega-CD WWF Rage in the Cage et suite directe WWF Raw.', 'https://fr.wikipedia.org/wiki/WWF_Royal_Rumble_(jeu_vid%C3%A9o,_1993)'),
  ('Q3283937', 'Congo''s Caper (connu au japon sous le nom Tatakae Genshijin 2: Ruki no Bōken est un jeu vidéo d''action/plates-formes en 2D, développé et édité par Data East sur Super Famicom au Japon le 18 décembre 1992, suivi de l''Amérique du Nord et de l''Europe en 1993. Ce jeu est techniquement le deuxième opus de la série Joe and Mac (Joe and Mac 2), bien que le héros soit différent.', 'https://fr.wikipedia.org/wiki/Congo%27s_Caper'),
  ('Q2712379', 'Cool Spot est un jeu vidéo de plates-formes de David Perry pour Virgin Interactive, sorti sur Amiga, DOS, Mega Drive, Master System, Game Gear, Super Nintendo et Game Boy en 1993, d''après la licence 7 Up.

Le style qui fera le succès de David Perry sur les consoles 16 bits est déjà reconnaissable (voir aussi Global gladiators, Earthworm Jim et Aladdin): l''animation est très réussie, fine et en avance sur son temps (le rendu est plus proche d''un dessin animé que d''un jeu vidéo de cette époque), les graphismes et l''ambiance sonore sont soignés, relativement inventifs malgré la licence commerciale, le gameplay, s''il n''est pas fondamentalement nouveau, est très soigné et propose quelques subtilités.', 'https://fr.wikipedia.org/wiki/Cool_Spot'),
  ('Q2709391', 'X-Men: Mutant Apocalypse est un jeu vidéo de type beat them all développé et édité par Capcom sur Super Nintendo en 1994. Il se déroule dans l''univers des comics X-Men. Le jeu est d''abord publié en Amérique du Nord le 14 novembre 1994, le 3 janvier 1995 au Japon et en mars 1995 en Europe.', 'https://fr.wikipedia.org/wiki/X-Men:_Mutant_Apocalypse'),
  ('Q220174', 'Zool: Ninja of the “Nth” Dimension est un jeu vidéo de plates-formes développé et édité par Gremlin Graphics en 1992 sur Amiga 500, Atari ST et DOS. Il fut ensuite porté sur Amiga 1200, Amiga CD32, Archimedes, borne d''arcade, Game Gear, Master System, Mega Drive, Super Nintendo et Game Boy.

Il connaît une suite en 1994: Zool 2.', 'https://fr.wikipedia.org/wiki/Zool'),
  ('Q3276911', 'Magical Drop II est un jeu vidéo de puzzle développé par Data East en 1996 sur Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD, Super Famicom et Saturn (NGM 221).', 'https://fr.wikipedia.org/wiki/Magical_Drop_II'),
  ('Q2015441', 'WWF Super WrestleMania est un jeu vidéo de catch professionnel de LJN commercialisé en 1992 sur Super Nintendo et Mega Drive. Tous les catcheurs ont les mêmes prises standards comme les slams, suplexes, dropkicks, clotheslines, hip tosses, elbow drops et finishers.

Pour la version Mega Drive, les prises finales peuvent être faites n''importe quand durant le match. La version Super Nintendo contient dix catcheurs, tandis que la version Mega Drive n''en contient que huit. Trois modes de jeux sont présents incluant « One-on-One », « Tag Team », et « Survivor Series ». La version Mega Drive contient un mode championnat pour le WWF Championship, dans ce mode le joueur doit battre les sept autres catcheurs. Il est moyennement accueilli sur GameRankings avec une note de 72 % sur Super Nintendo et 70 % sur Mega Drive.', 'https://fr.wikipedia.org/wiki/WWF_Super_WrestleMania'),
  ('Q2002093', 'Super Punch-Out!! est un jeu vidéo de boxe sorti sur Super Nintendo en 1994. Il est en quelque sorte la suite des Punch-Out!!, les deux jeux de boxe sortis sur NES et borne d''arcade, qui étaient très connus et très appréciés.', 'https://fr.wikipedia.org/wiki/Super_Punch-Out!!_(jeu_vid%C3%A9o,_1994)'),
  ('Q2710813', 'Dragon Ball Z: Ultime Menace est un jeu vidéo de combat, troisième et dernier épisode de la série Super Butōden sorti le 29 septembre 1994 sur Super Nintendo.

Le Weekly Shōnen Jump, qui décrit l''avancement de la série, qui sort au même moment est le Weekly Shōnen Jump 1994 #43 avec le chapitre "Trunks et Goten entrent dans la salle de l''esprit et du temps". Malgré l''avancement de la série, où on a pu voir Goku en SSJ3, Gotenks, et Majin Boo dans sa deuxième forme, ces personnages ne seront pas présents, et il faudra se contenter du tout début de la saga de Boo.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z_:_Ultime_Menace'),
  ('Q2016278', 'MTV''s Beavis and Butt-Head est un jeu vidéo d''action basé sur la série d''animation Beavis et Butt-Head. La version Super Nintendo est développée par Realtime Associates, la version Game Gear par NuFX, et la version Mega Drive par Radical Entertainment, elles sont toutes éditées par Viacom New Media en 1994 pour l''Amérique du Nord et en 1995 pour l''Europe. Une version sur Game Boy développée par Torus Games sort en 1998.', 'https://fr.wikipedia.org/wiki/MTV%27s_Beavis_and_Butt-Head'),
  ('Q3275487', 'Madden NFL ''96 est un jeu vidéo de football américain sorti en 1996 et fonctionne sur Mega Drive, Super Nintendo, Game Boy, Game Gear et Windows. Le jeu a été développé par Tiburon Entertainment et High Score Productions et a été édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Madden_NFL_%2796'),
  ('Q2709518', 'Animaniacs est un jeu vidéo de plates-formes sorti en 1994 sur Game Boy, Mega Drive et Super Nintendo. Le jeu a été développé et édité par Konami.

Le jeu s''inspire de la série d''animation Animaniacs.', 'https://fr.wikipedia.org/wiki/Animaniacs_(jeu_vid%C3%A9o)'),
  ('Q2709557', 'Dragon Ball Z: La Légende Saien, typographié Dragon Ball Z: LA Légende SAIEN, est un jeu vidéo de combat, deuxième jeu de la série Super Butōden, sorti sur Super Nintendo le 17 décembre 1993.

Lors de la sortie du jeu, qui arrive seulement 9 mois après le premier épisode, le chapitre le plus récent alors sorti est le chapitre 451 ("Le repas de Yakon, la créature magique"), publié dans le Weekly Shōnen Jump 1994 #02 (14 décembre 1993), au début la saga Boo. A ce stade, on ne sait pas à ce moment à quoi ressemblera Boo. C''est la raison pour laquelle le jeu est basé sur la fin de la saga Cell (les cyborgs ne sont pas présents), et afin de proposer de nouveaux personnages, ce sont les deux films Broly le super guerrier (sorti en Mars) et Les Mercenaires de l''espace (sorti en Juillet) qui sont mis en avant. Les développeurs n''ont eu que quelques mois pour ajouter ces personnages, et inventer un scénario parfois éloigné du film pour les besoins du jeu. Le titre du jeu est erroné du fait qu''à l''époque le terme Saiyan était encore instable. De nos jours, le titre correct serait La Légende Saiyan.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z_:_La_L%C3%A9gende_Saien'),
  ('Q1999554', 'King of the Monsters est un jeu vidéo de combat développé et édité par SNK en 1991 sur Neo-Geo MVS, Neo-Geo AES (NGM 016), puis sur Super Nintendo en 1992 et Mega Drive en 1993.', 'https://fr.wikipedia.org/wiki/King_of_the_Monsters'),
  ('Q1196400', 'Mega Man X est un jeu d''action-plates-formes développé et édité par Capcom sur Super Nintendo et PC (DOS) en 1993, faisant partie de la franchise Mega Man. C''est le premier de la série dérivée Mega Man X. Un portage est publié sur téléphone mobile au Japon en 2007 ainsi qu''une adaptation sur la Console virtuelle de la Wii en 2011, de la Wii U en 2013, et de la New Nintendo 3DS en 2016, ainsi que sur Android et iOS en 2011.', 'https://fr.wikipedia.org/wiki/Mega_Man_X_(jeu_vid%C3%A9o)'),
  ('Q3282001', 'Pac-Panic (Pac-Attack aux États-Unis) est un jeu vidéo de puzzle sorti en 1993 sur Mega Drive, CD-I, Game Boy, Game Gear et Super Nintendo. Il est développé et édité par Namco.

Le jeu devient disponible en téléchargement sur la console virtuelle de la Wii à partir de 2008.', 'https://fr.wikipedia.org/wiki/Pac-Panic'),
  ('Q1197149', 'Terranigma est un jeu vidéo de type action-RPG développé par Quintet. Il est édité sur Super Nintendo par Enix en 1995 au Japon puis par Nintendo en 1996 en Europe (Royaume-Uni, Italie, Allemagne) et en Australie et en 1997 en France et en Espagne. Terranigma raconte l''aventure d''Ark, un jeune homme chargé de ressusciter la surface de la Terre, détruite à la suite d''une bataille entre le Bien et le Mal.', 'https://fr.wikipedia.org/wiki/Terranigma'),
  ('Q219804', 'Zombies Ate My Neighbors (littéralement: « Les zombies ont mangé mes voisins »), connu sous le nom Zombies en Europe, est un jeu vidéo d''action développé par LucasArts, sorti sur Mega Drive et Super Nintendo en 1993.', 'https://fr.wikipedia.org/wiki/Zombies_Ate_My_Neighbors'),
  ('Q2656776', 'Live A Live est un RPG développé et édité par Squaresoft, sorti uniquement au Japon sur Super Famicom le 2 septembre 1994 et sur la console virtuelle de la Wii U le 24 juin 2015. Il a cependant été traduit en anglais par des fans.

Live A Live raconte l''histoire de sept personnages différents, vivant chacun à une époque apparemment indépendante (préhistoire, dynastie Han, Moyen-Âge, Far West, période Tokugawa, époque contemporaine, futur « proche » et futur « lointain »). Chaque chapitre possède ses spécificités, comme le côté infiltration pour l''époque ninja, mais le gameplay reste le même. Après avoir fini les sept premiers chapitres, deux nouveaux apparaissent l''un après l''autre pour lier les différents chapitres et conclure l''histoire. Chaque design des personnages des chapitres du jeu a été réalisé par un auteur de manga différent: Yoshinori Kobayashi (Obocchama-kun), Yoshihide Fujiwara (Kenji), Gōshō Aoyama (Détective Conan), Osamu Ishiwata (Passport Blue), Ryōji Minagawa (Spriggan, Arms), Shimamoto Kazuhiko (Comic Bomber) et Yumi Tamura (Basara, 7 Seeds).', 'https://fr.wikipedia.org/wiki/Live_A_Live'),
  ('Q2637335', 'Lufia and the Fortress of Doom, ou Estpolis Denki au Japon, est un jeu vidéo de rôle développé par Neverland Co., Ltd. et édité par Taito en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Lufia_and_the_Fortress_of_Doom'),
  ('Q1197521', 'Puzzle Bobble, (Bust-a-Move aux États-Unis) est un jeu vidéo de puzzle développé et édité par Taito en 1994 sur Taito System B en juin, sur Neo-Geo MVS en décembre et sur Neo-Geo CD en 1995 (NGM 083) et a été porté sur de nombreux supports. C''est le premier jeu de la série Puzzle Bobble.', 'https://fr.wikipedia.org/wiki/Puzzle_Bobble_(jeu_vid%C3%A9o)'),
  ('Q1200598', 'Desert Strike: Return to the Gulf est un jeu vidéo d''action mettant le joueur aux commandes d''un hélicoptère de combat dans le désert du Moyen-Orient. Développé et édité par Electronic Arts en 1992 sur Mega Drive, Master System et Super Nintendo, le jeu a été édité en 1993 sur Amiga et Lynx, et en 1994 sur DOS, Game Boy et Game Gear. Une version Game Boy Advance est également sortie en 2002, sous le titre Desert Strike Advance.', 'https://fr.wikipedia.org/wiki/Desert_Strike:_Return_to_the_Gulf'),
  ('Q2062867', 'California Games II est un jeu vidéo de sport développé et édité par Epyx, sorti en 1990 sur DOS, en 1992 sur Amiga et Atari ST et en 1993 sur Master System et Super Nintendo. Il s''agit de la suite de California Games. Une version sur Atari Lynx a été aussi annoncée et vue dans différents magazines, mais n''est jamais sortie.', 'https://fr.wikipedia.org/wiki/California_Games_II'),
  ('Q3280284', 'Super Bomberman 4 est un jeu vidéo d''action et de labyrinthe développé par Produce! et édité par Hudson Soft, sorti en 1996 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Bomberman_4'),
  ('Q267368', 'U.N. Squadron est un jeu vidéo de shoot ''em up développé et édité par Capcom sur CP System en août 1989. C''est le premier épisode d''une série de jeux vidéo basés sur l''univers du manga japonais Area 88.', 'https://fr.wikipedia.org/wiki/U.N._Squadron'),
  ('Q2081774', '2020 Super Baseball est un jeu vidéo de baseball développé par Pallas et édité par SNK en 1991 sur Neo-Geo MVS, Neo-Geo AES et Neo-Geo CD (NGM / NGH 030). Il a été porté sur console Mega Drive et Super Nintendo.', 'https://fr.wikipedia.org/wiki/2020_Super_Baseball'),
  ('Q3279162', 'Super Bomberman 5 est un jeu vidéo d''action et de labyrinthe développé et édité par Hudson Soft en 1997 sur Super Nintendo, exclusivement au Japon. Il s''agit du 5e opus de la série Super Bomberman.', 'https://fr.wikipedia.org/wiki/Super_Bomberman_5'),
  ('Q3281949', 'WWF RAW est un jeu vidéo basé sur l''émission télévisée et branche professionnelle du même nom dirigée par la World Wrestling Federation, commercialisé sur consoles Super Nintendo, Sega 32X, Mega Drive, Game Gear et Game Boy fin 1994 et début 1995 par Acclaim Entertainment. Il s''agit de la suite du jeu WWF Royal Rumble commercialisé en 1993, concluant la trilogie des jeux vidéo WWF de chez LJN. Le joueur peut combattre dans des matchs à un-contre-un, en tag team, bedlam (tornado tag), aux Survivor Series, au Royal Rumble, ou dans un match Raw Endurance.

WWF RAW met en scène les différents catcheurs possédant chacun ses propres prises et coups. Le jeu ajoute également de nombreuses prises exclusives qui n''ont pas été ajoutées dans les jeux précédents, comme le DDT, fallaway slam, et autres types de souplesses. les catcheurs diffèrent selon leurs attributs en vélocité, force, stamina et poids.', 'https://fr.wikipedia.org/wiki/WWF_Raw_(jeu_vid%C3%A9o,_1994)'),
  ('Q1321249', 'Final Fight 2 est jeu vidéo de beat them all sorti sur Super Nintendo en 1993. Il fait partie de la série des Final Fight. Il a été réédité sur la console virtuelle de la Wii en 2009.

Dans ce jeu, le joueur a la possibilité de jouer avec l''un des trois personnages: Haggar, Maki ou Carlos. Le but du jeu est d''éliminer à nouveau le clan Mad Gear (déjà présent dans le premier opus) et cela dans différents pays.', 'https://fr.wikipedia.org/wiki/Final_Fight_2'),
  ('Q257469', 'Another World est un jeu vidéo d''action-aventure conçu et développé par Éric Chahi et édité par Delphine Software. Particulièrement remarqué à sa sortie pour sa conception cinématographique, ses graphismes et son gameplay, il est considéré aujourd''hui comme un jeu culte. Sorti initialement le 15 novembre 1991 sur Amiga et Atari ST, le jeu a par la suite été porté sur un grand nombre de machines et a été réédité en 2006 dans une version collector graphiquement améliorée ainsi qu''en 2013 sur Atari Jaguar avec l''autorisation de l''auteur.

Le jeu est sorti sous plusieurs titres différents: Another World en Europe et en Australie, Out of this World en Amérique du Nord, Outer World au Japon.', 'https://fr.wikipedia.org/wiki/Another_World_(jeu_vid%C3%A9o)'),
  ('Q2151598', 'Pit-Fighter est un jeu vidéo de combat développé et commercialisé par Atari Games en 1990 sur borne d''arcade. Il a été adapté sur Amiga, Amstrad CPC, Atari ST, Commodore 64, DOS, Master System, Mega Drive, Super Nintendo et ZX Spectrum en 1991 et sur Game Boy et Lynx en 1992.

Il s''agit du premier jeu de combat dont les personnages sont des acteurs digitalisés, une technique ensuite reprise dans des jeux comme Mortal Kombat ou NBA Jam.', 'https://fr.wikipedia.org/wiki/Pit-Fighter'),
  ('Q2083777', 'Pitfall: The Mayan Adventure est un jeu vidéo de plate-forme sorti en 1994 sur Super Nintendo et Mega-CD puis porté en 1995 sur 32X, Jaguar, Mega Drive et Windows et en 2001 sur Game Boy Advance. Le jeu a été développé par Activision et Imagitec Design puis édité par Activision, Atari et Majesco Sales.

Pitfall: The Mayan Adventure est l''une des suites du jeu Pitfall! sorti en 1982.', 'https://fr.wikipedia.org/wiki/Pitfall:_The_Mayan_Adventure'),
  ('Q3278677', 'Shaq Fu est un jeu vidéo de combat en 2D développé par Delphine Software, sorti sur Mega Drive, Game Gear, Game Boy, Super Nintendo, Amiga et Amiga 1200 en 1994. Le héros du jeu est le joueur de basket-ball Shaquille O''Neal. Malgré cela, on ne joue pas au basket-ball dans le jeu.', 'https://fr.wikipedia.org/wiki/Shaq_Fu'),
  ('Q2169654', 'ActRaiser 2 est un jeu vidéo de plates-formes, développé par Quintet, sorti sur Super Nintendo en 1994. Il est la suite d''ActRaiser, sorti en 1992 sur Super Nintendo. La musique est composée par Yūzō Koshiro.', 'https://fr.wikipedia.org/wiki/ActRaiser_2'),
  ('Q1326889', 'Star Wing (également écrit Starwing), intitulé Star Fox au Japon et en Amérique du Nord, est un jeu vidéo développé par Nintendo EAD avec l’assistance d''Argonaut Games et édité par Nintendo. Il s’agit d’un shoot them up de type rail shooter, sorti sur Super Famicom le 21 février 1993 au Japon, puis le 23 mars 1993 mars aux États-Unis. En Europe, Star Wing sort le 3 juin 1993, le 5 juin 1993 au Royaume-Uni et le 9 juin 1993 en France. Il constitue le premier opus de la série de jeux vidéo Star Fox. Ce jeu est ressorti en 2017 sur SNES Mini puis dans le Nintendo Switch Online de la Nintendo Switch en septembre 2019.', 'https://fr.wikipedia.org/wiki/Star_Wing'),
  ('Q2186293', 'The Aquatic Games: Starring James Pond and the Aquabats est un jeu vidéo de type party game développé par le studio anglais Vectordean et édité par Millennium Interactive et Electronic Arts en 1992. Le jeu est sorti sur l''ordinateur Amiga et les consoles Mega Drive et Super Nintendo. C''est un spin-off de la série James Pond: il délaisse le jeu de plates-formes pour une série de mini-jeux parodiant les Jeux olympiques.', 'https://fr.wikipedia.org/wiki/The_Aquatic_Games'),
  ('Q1313980', 'Ultimate Mortal Kombat 3 (communément abrégé UMK3) est un jeu vidéo de combat, développé et édité par la société américaine Midway en 1995 sur borne d''arcade. UMK3 constitue une évolution de Mortal Kombat 3, l''histoire est donc en tout point identique.', 'https://fr.wikipedia.org/wiki/Ultimate_Mortal_Kombat_3'),
  ('Q2158049', 'PGA Tour Golf est un jeu vidéo de golf développé par BlueSky Software et édité par Electronic Arts. Originellement sorti en 1990 sur DOS, il est porté en 1991 sur Mega Drive et Mac, SNES et Amiga, puis en 1993 sur Master System et Game Gear.', 'https://fr.wikipedia.org/wiki/PGA_Tour_Golf'),
  ('Q254723', 'Cannon Fodder est un jeu vidéo d''action et de stratégie développé par Sensible Software et édité par Virgin Interactive en 1993 sur Amiga. Le jeu a été porté sur Atari ST, DOS et consoles de jeu en 1994. Il appartient à la série Cannon Fodder.', 'https://fr.wikipedia.org/wiki/Cannon_Fodder_(jeu_vid%C3%A9o)'),
  ('Q3281960', 'Super Famicom Wars est un jeu vidéo de tactique au tour par tour développé par Intelligent Systems et édité par Nintendo. Il est seulement sorti au Japon, le 1er mai 1998 sur Super Famicom, puis réédité le 16 février 2010 sur Wii, le 2 octobre 2013 sur Wii U et le 28 novembre 2016 sur Nintendo 3DS grâce aux magasins en ligne de ces plateformes. Il fait partie de la série Nintendo Wars.

Une fan-traduction en anglais est disponible depuis décembre 2017.', 'https://fr.wikipedia.org/wiki/Super_Famicom_Wars'),
  ('Q2741882', 'Addams Family Values est un jeu vidéo de type action-RPG développé et édité par Ocean Software en 1995 sur Mega Drive et sur Super Nintendo.

Il s''agit d''une adaptation du film Les Valeurs de la famille Addams de Barry Sonnenfeld, sorti en 1993.', 'https://fr.wikipedia.org/wiki/Addams_Family_Values'),
  ('Q2297364', 'Tortues ninja: Les tortues réécrivent l’histoire, ou Teenage Mutant Ninja Turtles: Turtles in Time en dehors d''Europe, est un jeu vidéo de type beat them all développé et édité par Konami sur borne d''arcade en 1991. Il fut porté sur Super Nintendo un an après et est renommé Teenage Mutant Ninja Turtles IV: Turtles in Time.

Le jeu est publié sur Super Famicom au Japon le 24 juillet 1992, le 15 août 1992 aux États-Unis et le 15 novembre 1992 en Europe.', 'https://fr.wikipedia.org/wiki/Teenage_Mutant_Hero_Turtles:_Turtles_in_Time'),
  ('Q1511144', 'SimEarth: The Living Planet est un jeu vidéo de simulation élaboré par Will Wright et publié en 1990 par Maxis dans lequel le joueur contrôle le développement d''une planète entière. Le jeu existe sur de nombreux supports. Il modélise l''hypothése Gaïa de James Lovelock (qui a assisté l''élaboration du jeu et écrit l''introduction du manuel) et une des options du jeu disponibles est d''utiliser son modèle simplifié Daisyworld.

Bien que le jeu soit admiré à sa sortie, ses ventes ne furent pas aussi importantes que le succès précédent: SimCity.', 'https://fr.wikipedia.org/wiki/SimEarth:_The_Living_Planet'),
  ('Q2743913', 'King of the Monsters 2: The Next Thing est un jeu vidéo de combat développé et édité par SNK en 1992 sur Neo-Geo MVS, Neo-Geo AES (NGM 039), puis sur Super Famicom, Neo-Geo CD et Mega Drive en 1994. Le portage sur Mega Drive et Super Nintendo a été réalisé par la société Takara. Il s''agit de la suite du jeu King of the Monsters.', 'https://fr.wikipedia.org/wiki/King_of_the_Monsters_2:_The_Next_Thing'),
  ('Q1405093', 'Top Gear 3000 est un jeu vidéo de course automobile développé par Gremlin Graphics et édité en 1995 sur Super Nintendo.

Il s''agit de la suite Top Gear 2 (1993).', 'https://fr.wikipedia.org/wiki/Top_Gear_3000'),
  ('Q1442104', 'Test Drive II: The Duel est un jeu vidéo de course automobile développé par Distinctive Software et édité par Accolade en 1989. Le jeu fonctionne sur Amiga, Amstrad CPC, Apple II, Commodore 64, DOS, Mega Drive, MSX, Super Nintendo et ZX Spectrum.', 'https://fr.wikipedia.org/wiki/Test_Drive_II:_The_Duel'),
  ('Q275122', 'Super Ghouls ''n Ghosts, ou Choh Makaimura au Japon, est un jeu vidéo de plates-formes, développé par Capcom, et sorti sur Super Nintendo en 1991. Un portage est sorti sur Game Boy Advance en 2002.

Super Ghouls ''n Ghosts est publié au Japon le 4 octobre 1991, le 28 novembre 1991 en Amérique du Nord puis en octobre 1992 pour l''Europe.', 'https://fr.wikipedia.org/wiki/Super_Ghouls_%27n_Ghosts'),
  ('Q1557589', 'Mr. Do! est un jeu d''arcade sorti en 1982 par Universal (devenu Aruze) et distribué par Taito.

Il a été adapté sur un grand nombre de systèmes dont l''Atari 2600, la ColecoVision, l''Apple II, le MSX, le Commodore 64 et de manière plus évoluée sur la Game Boy et la Super Nintendo.', 'https://fr.wikipedia.org/wiki/Mr._Do!'),
  ('Q2736832', 'Lethal Enforcers est un jeu vidéo de tir au pistolet développé et édité par Konami, sorti en 1992 sur borne d''arcade. Il a été adapté sur Mega Drive et Mega-CD en 1993 et sur Super Nintendo en 1994. Il a aussi été porté sur PlayStation en 1997 dans une compilation regroupant Lethal Enforcers et sa suite, Lethal Enforcers II: Gunfighters. Une autre suite a été réalisée bien qu''elle soit très différentes des deux premiers opus, il s''agit de Lethal Enforcers 3. L''action se déroule dans la ville de Chicago aux États-Unis.', 'https://fr.wikipedia.org/wiki/Lethal_Enforcers'),
  ('Q284064', 'Stunt Race FX est un jeu vidéo de course en 3D dans un style dessin animé. Ce jeu vidéo développé et publié par Nintendo pour la Super Nintendo est le second pour lequel on a utilisé la puce Super FX. Codéveloppé avec Argonaut Games, on le connaît sous le nom Wild Trax au Japon. Malgré l''utilisation de la puce Super FX, le jeu n''a pas reçu autant d''attention de la part du public que Star Fox. La seule réédition de ce jeu est sur le Nintendo Switch Online de la Nintendo Switch.

Le jeu propose des niveaux de courses, d''obstacle et un mode « affrontement ».', 'https://fr.wikipedia.org/wiki/Stunt_Race_FX'),
  ('Q3334222', 'NBA All-Star Challenge est un jeu vidéo de basket-ball sorti en 1993 et sur Mega Drive, Super Nintendo et Game Boy. Le jeu a été développé par Beam puis édité par Acclaim Entertainment et Flying Edge.', 'https://fr.wikipedia.org/wiki/NBA_All-Star_Challenge'),
  ('Q2716211', 'Yoshi''s Safari, connu au Japon sous le titre Yoshi no Road Hunting, est un jeu vidéo de tir au pistolet sorti en 1993 sur Super Nintendo et se jouant à l''aide du Super Scope de Nintendo.', 'https://fr.wikipedia.org/wiki/Yoshi%27s_Safari');

insert into import_summary (wikidata_id, summary, source) values
  ('Q2746048', 'Earth Defense Force (E.D.F.) est un jeu vidéo de type shoot ''em up développé par Jaleco, sorti en 1991 sur borne d''arcade. Il est adapté la même année sur Super Nintendo, sous le titre Super Earth Defense Force.', 'https://fr.wikipedia.org/wiki/Earth_Defense_Force_(jeu_vid%C3%A9o)'),
  ('Q3312139', 'Taz-Mania est le nom de plusieurs jeux vidéo inspirés du dessin animé du même nom, avec différents développeurs selon la console. Hormis la version Super Nintendo, qui est de vue de dos du personnage et peut être considéré comme un jeu de course, les jeux sont de type plate-formes à défilement horizontal.', 'https://fr.wikipedia.org/wiki/Taz-Mania_(jeu_vid%C3%A9o)'),
  ('Q1385731', 'Eye of the Beholder est un jeu vidéo de type dungeon crawler développé par Westwood Associates (futur Westwood Studios) et publié par Strategic Simulations, Inc. en 1991. Initialement sorti sur PC, le jeu a été adapté sur Amiga, Mega-CD, Super Nintendo et la console portable Lynx.', 'https://fr.wikipedia.org/wiki/Eye_of_the_Beholder_(jeu_vid%C3%A9o)'),
  ('Q2721899', 'Top Gear (Top Racer au Japon) est un jeu vidéo de course automobile développé par Gremlin Graphics et publié par Kemco en 1992 sur la console de jeu Super Nintendo. Premier épisode de la série Top Gear, il s''agit de l''adaptation de Lotus Turbo Challenge 2 (1991, Amiga). Top Gear est l''un des premiers du genre à paraître sur Super Nintendo.

Le but du jeu est de devenir le pilote de course le plus rapide du monde et ceci en gagnant des courses contre divers adversaires à travers le monde.', 'https://fr.wikipedia.org/wiki/Top_Gear_(jeu_vid%C3%A9o,_1992)'),
  ('Q2273067', 'FIFA International Soccer (parfois nommé FIFA 94 et FIFA International Soccer: Championship Edition sur Mega-CD) est un jeu vidéo de football sorti en 1993 et fonctionne sur 3DO, Amiga, DOS, Game Boy, Game Gear, Master System, Mega-CD, Mega Drive et Super Nintendo. Le jeu a été développé par Extended Play Productions et édité par EA Sports.', 'https://fr.wikipedia.org/wiki/FIFA_International_Soccer'),
  ('Q1408193', 'Ardy Lightfoot est un jeu d''action plates-formes de type 2D, développé et publié par ASCII au Japon, et publié par Titus Interactive en Amérique du Nord. Il est originellement sorti sur Super Famicom au Japon le 26 novembre 1993, suivi de l''Europe et l''Amérique du Nord en 1994.', 'https://fr.wikipedia.org/wiki/Ardy_Lightfoot'),
  ('Q1486269', 'Gods est un jeu vidéo de plates-formes / action développé par The Bitmap Brothers et édité par Renegade en 1991 sur Amiga et Atari ST. Il est sorti sur Archimedes, DOS, Mega Drive et Super Nintendo en 1992.

Le jeu se distingue par sa réalisation soignée et son gameplay ingénieux.', 'https://fr.wikipedia.org/wiki/Gods_(jeu_vid%C3%A9o)'),
  ('Q2248339', 'NBA Jam: Tournament Edition est un jeu vidéo de basket ball sorti en 1994 sur arcade, puis porté sur Mega Drive, Super Nintendo et Game Gear, et en 1995 sur PC, Game Boy, PlayStation, Saturn, 32X et Jaguar. Le jeu a été développé par Midway et édité par Acclaim Entertainment.

Il fait partie de la série NBA Jam, dont il est le second épisode.', 'https://fr.wikipedia.org/wiki/NBA_Jam:_Tournament_Edition'),
  ('Q2723021', 'Rudra no Hihō est un jeu vidéo de rôle de Squaresoft sorti en 1996 au Japon sur Super Famicom.', 'https://fr.wikipedia.org/wiki/Rudra_no_Hih%C5%8D'),
  ('Q1527988', 'Darius Force, connu sous le titre Super Nova en Amérique du Nord, est un jeu vidéo de type shoot ''em up développé et édité par Taito, sorti en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Darius_Force'),
  ('Q3334266', 'NCAA Football est un jeu vidéo de football américain sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par The Software Toolworks et édité par Mindscape.', 'https://fr.wikipedia.org/wiki/NCAA_Football'),
  ('Q1587638', 'Dungeon Master est un jeu vidéo de rôle de type dungeon crawler développé par FTL Games. Le jeu est d''abord publié sur Atari ST en 1987 avant d''être porté les années suivantes sur Amiga, Sharp X68000, PC, FM Towns, PC-98012, PC-Engine et Super Nintendo. Il se déroule dans un univers médiéval-fantastique dans lequel le joueur incarne un apprenti au service d''un puissant magicien. Lors d''une expérience, l''âme de ce dernier se scinde en deux parties antagonistes, l''une d''elles — appelée Chaos — se révélant maléfique et menaçant d''envahir le monde. Pour l''en empêcher, le joueur contrôle quatre champions devant explorer le donjon de Chaos afin de retrouver le seul objet capable de réunifier l''âme du magicien.', 'https://fr.wikipedia.org/wiki/Dungeon_Master'),
  ('Q2269596', 'Populous II: Trials of the Olympian Gods est un jeu vidéo de stratégie en temps réel développé par Bullfrog, sorti en 1991 sur MS-DOS, Amiga et Atari ST. Il a été édité sur DOS, Mega Drive, Super Nintendo en 1993 et sous MacOS en 1994. Il fait suite à Populous.

La version Mega Drive porte le nom Populous II: Two Tribes.', 'https://fr.wikipedia.org/wiki/Populous_2:_Trials_of_the_Olympian_Gods'),
  ('Q3307249', 'Metal Warriors est un jeu vidéo de plates-formes-action développé par LucasArts puis édité par Konami en 1995 sur Super Nintendo uniquement en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Metal_Warriors'),
  ('Q3308280', 'Michael Jordan: Chaos in the Windy City (littéralement, Michael Jordan: Chaos dans la ville venteuse en référence au surnom de la ville de Chicago, où il a effectué la majorité de sa carrière de basketteur) est un jeu de plates-formes sorti en 1994 pour la Super Nintendo. Le jeu met en scène le célèbre joueur de basket-ball Michael Jordan en tant que personnage joueur, mais on n''y joue pas vraiment au basket-ball.', 'https://fr.wikipedia.org/wiki/Michael_Jordan:_Chaos_in_the_Windy_City'),
  ('Q3312023', 'Micro Machines 2: Turbo Tournament est un jeu vidéo de course développé et édité par Codemasters en 1994. Il est disponible sur Mega Drive, PC (DOS), Super Nintendo, Game Boy et Game Gear.', 'https://fr.wikipedia.org/wiki/Micro_Machines_2:_Turbo_Tournament'),
  ('Q1545458', 'Syndicate est un jeu vidéo de tactique en temps réel développé par Bullfrog Productions et édité par Electronic Arts en 1993 sur Amiga et MS-DOS. Il propose un univers futuriste à l''ambiance cyberpunk. Ce jeu a eu une extension, Syndicate: American Revolt, et a été porté sur diverses consoles de jeu.', 'https://fr.wikipedia.org/wiki/Syndicate_(jeu_vid%C3%A9o,_1993)'),
  ('Q3334265', 'NCAA Final Four Basketball est un jeu vidéo de basket-ball sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Bitmasters et édité par Mindscape.', 'https://fr.wikipedia.org/wiki/NCAA_Final_Four_Basketball'),
  ('Q1445705', 'Dragon Ball Z: Hyper Dimension est un jeu vidéo de combat par Bandai sur l''univers de Dragon Ball Z. Le jeu est distribué en 1996 sur Super Nintendo. C''est le dernier jeu Dragon Ball Z à y être développé.

Dragon Ball Z: Hyper Dimension est publié au Japon le 29 mars 1996 puis distribué en Europe d''abord en France fin d''année 1996 puis en Espagne en février 1997.

Le contexte du jeu s''étend de la saga de Freezer à celle de Boo. Il s''agit, selon certaines critiques, de l''épisode le plus abouti sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Hyper_Dimension'),
  ('Q3334247', 'NBA Showdown (également nommé au Japon NBA Pro Basketball ''94: Bulls vs. Suns sur Super Nintendo et NBA Pro Basketball ''94 sur Mega Drive et NBA Showdown ''94 sur Mega Drive aux États-Unis) est un jeu vidéo de basket-ball sorti en 1993 sur Super Nintendo et en 1994 sur Mega Drive. Le jeu a été développé par EA Sports et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/NBA_Showdown'),
  ('Q2748343', 'Spider-Man and the X-Men: Arcade''s Revenge est un jeu vidéo de plates-formes sorti en 1993 sur Super Nintendo. Le jeu a été développé par Software Creations et édité par Acclaim (sous label LJN). Il a ensuite été porté sur Game Boy, Game Gear et Mega Drive sous le label Flying Edge. Le jeu est basé sur l''univers des comics Spider-Man et X-Men, œuvres de Marvel.', 'https://fr.wikipedia.org/wiki/Spider-Man_and_the_X-Men:_Arcade%27s_Revenge'),
  ('Q2748421', 'Striker est un jeu vidéo de football développé et édité par Rage Software, sorti en 1992 sur Amiga et Atari ST. Il est sorti sur DOS, Mega Drive, Super Nintendo en 1993 et Amiga CD32 en 1994.

La version française de Striker sur Super Nintendo est connue sous le nom Eric Cantona Football Challenge; et la version sortie en Amérique du Nord est connu sous le nom World Soccer 94: Road to Glory.', 'https://fr.wikipedia.org/wiki/Striker_(jeu_vid%C3%A9o,_1992)'),
  ('Q369264', 'Super Bomberman 3 est un jeu vidéo d''action développé et édité par Hudson Soft. Il est sorti en 1995 sur Super Nintendo au Japon et en Europe, et est le 3e épisode de la série Bomberman sur cette console, mais le premier à permettre de jouer à 5 en même temps.', 'https://fr.wikipedia.org/wiki/Super_Bomberman_3'),
  ('Q343033', 'ActRaiser est un jeu vidéo de gestion et de plates-formes développé par Quintet et distribué par Enix, sorti en Europe en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/ActRaiser'),
  ('Q2751109', 'Kid Klown in Crazy Chase est un jeu vidéo d''action développé et édité par Kemco et sorti en 1994 sur Super Nintendo. Un portage sur Game Boy Advance est sorti en 2002 sous le titre Crazy Chase en Europe et en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Kid_Klown_in_Crazy_Chase'),
  ('Q2140297', 'Rock N’ Roll Racing est un jeu vidéo de course créé par Silicon & Synapse (connu aujourd’hui sous le nom de Blizzard Entertainment) et publié par Interplay Entertainment le 4 juin 1993 sur les consoles Mega Drive et Super Nintendo. En 2003, il a été porté sur Game Boy Advance.', 'https://fr.wikipedia.org/wiki/Rock_N%27_Roll_Racing'),
  ('Q2748662', 'Mighty Morphin Power Rangers: The Movie est un jeu vidéo beat them all sorti en 1995 sur Mega Drive et Game Boy. Le jeu a été développé par SIMS et édité par Sega.

Le jeu est basé sur le film Power Rangers, le film.', 'https://fr.wikipedia.org/wiki/Mighty_Morphin_Power_Rangers:_The_Movie_(jeu_vid%C3%A9o)'),
  ('Q2116167', 'Exhaust Heat (aussi connu sous le nom de F1 Race of Champions) est un jeu vidéo sorti en 1992 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Exhaust_Heat'),
  ('Q1634991', 'Operation Thunderbolt est un jeu vidéo de tir au pistolet développé et édité par Taito, sorti en 1988 sur borne d''arcade.

Il s''agit de la suite d''Operation Wolf.', 'https://fr.wikipedia.org/wiki/Operation_Thunderbolt'),
  ('Q2112232', 'Judge Dredd est un jeu de plateforme-action en deux dimensions développé par Probe Entertainment et édité par Acclaim Entertainment sur Mega Drive, Game Gear, Super Nintendo, Game Boy, et PC (DOS) en 1995. C''est une adaptation du personnage de comics Judge Dredd, plus précisément de l''adaptation cinématographique éponyme sortie la même année, Judge Dredd.', 'https://fr.wikipedia.org/wiki/Judge_Dredd_(jeu_vid%C3%A9o,_1995)'),
  ('Q3334369', 'NFL Quarterback Club est une série de jeux vidéo de football américain développée par Acclaim de 1994 à 2002.', 'https://fr.wikipedia.org/wiki/NFL_Quarterback_Club'),
  ('Q2881443', 'Ballz (ou Ballz 3D: The Battle of the Balls) est un jeu vidéo de combat, développé par PF Magic et édité par Accolade, sorti sur Mega Drive, Super Nintendo et 3DO en 1994.', 'https://fr.wikipedia.org/wiki/Ballz'),
  ('Q2757541', 'Mr. Nutz est un jeu vidéo de plate-forme créé par deux Français, Philippe Dessoly (graphiste) et Pierre Adane (programmeur), de Ocean France. Le jeu est développé sur Super Nintendo, Mega Drive, Game Boy, Game Boy Color et Game Boy Advance.

Le jeu est sorti pour la première fois à la fin de l''année 1993 sur la console Super Nintendo.

Bien que le jeu original ait été prévu à l''origine sur Amiga sur lequel il a été initialement présenté à Ocean, une version a par la suite été très librement adaptée sur cette machine par l''équipe allemande de Neon Studios et éditée par Ocean Software en 1994.', 'https://fr.wikipedia.org/wiki/Mr._Nutz'),
  ('Q3342399', 'No Escape est un jeu vidéo d''action et de plates-formes développé par Bits Corporation et édité par Sony Imagesoft, sorti en 1994 sur Mega Drive et Super Nintendo. Il est basé sur le film Absolom 2022.', 'https://fr.wikipedia.org/wiki/No_Escape_(jeu_vid%C3%A9o)'),
  ('Q430868', 'Devil''s Course est un jeu vidéo de golf sorti en 1993 sur Super Nintendo puis l''année suivante sur Mega Drive. Le jeu a été développé par T&E Soft.', 'https://fr.wikipedia.org/wiki/Devil%27s_Course'),
  ('Q2881009', 'Ball Bullet Gun (ou encore B.B.GUN) est un tactical RPG sorti sur Super Famicom en 1995, seulement au Japon.', 'https://fr.wikipedia.org/wiki/Ball_Bullet_Gun'),
  ('Q2903390', 'Bill Walsh College Football est un jeu vidéo de football américain sorti en 1993 sur Mega-CD, Mega Drive et Super Nintendo. Le jeu a été développé par Visual Concepts et édité par EA Sports.', 'https://fr.wikipedia.org/wiki/Bill_Walsh_College_Football'),
  ('Q2814018', 'The Mask est un jeu vidéo de plates-formes en défilement horizontal développé et édité en 1995 par Black Pearl Software sur système Super Nintendo, et basé sur le premier film de The Mask. Le film, en revanche, est basé sur la série des comics Dark Horse du même nom.', 'https://fr.wikipedia.org/wiki/The_Mask_(jeu_vid%C3%A9o)'),
  ('Q2789389', 'James Pond 3: Operation Starfish est un jeu vidéo de plates-formes développé par Vectordean, sorti en 1993 sur Mega Drive. Le jeu a été édité en 1994 sur Amiga 1200, Amiga CD32 et Super Nintendo.', 'https://fr.wikipedia.org/wiki/James_Pond_3:_Operation_Starfish'),
  ('Q2906318', 'Blazing Skies est un jeu d''arcade de combats aériens, sorti sur Super Nintendo en 1992.', 'https://fr.wikipedia.org/wiki/Blazing_Skies'),
  ('Q3342057', 'Nintendo Scope 6, nommé Super Scope 6 au Japon et aux États-Unis, est un jeu vidéo de tir au pistolet sorti uniquement en bundle avec le Super Scope, un accessoire en forme de bazooka, en février 1992 aux États-Unis, en Octobre 1992 en Europe et en Australie, et le 21 juin 1993 au Japon sur la Super Nintendo.', 'https://fr.wikipedia.org/wiki/Nintendo_Scope_6'),
  ('Q389254', 'Super Castlevania IV (悪魔城ドラキュラ, Akumajō Dorakyura, Demon Castle Dracula) est un jeu vidéo d''action et de plates-formes développé et édité par Konami en 1991 sur Super Nintendo. Le jeu a été conçu par Masahiro Ueno. Le jeu est d''abord publié au Japon le 31 octobre 1991 puis fin août 1992 pour l''Europe.

Super Castlevania IV fut l''un des premiers jeux de la Super Nintendo et encore aujourd''hui, son aura dépasse largement celle d''un simple jeu d''action. Si le jeu a été présenté au Japon comme un remake du premier Castlevania, il a été, en revanche, vendu en dehors de l''archipel comme un épisode original de la saga, faisant suite à Simon''s Quest.', 'https://fr.wikipedia.org/wiki/Super_Castlevania_IV'),
  ('Q2887292', 'Bass Masters Classic est un jeu vidéo de pêche sorti en 1994 sur Game Boy Color, Mega Drive et Super Nintendo. Le jeu a été développé par Black Pearl et édité par THQ et Malibu Games.', 'https://fr.wikipedia.org/wiki/Bass_Masters_Classic'),
  ('Q3334421', 'NHL 95 est un jeu vidéo de hockey sur glace sorti le 8 décembre 1994 et fonctionne sur Mega Drive et Super Nintendo. Le jeu a été développé par Electronic Arts puis édité par EA Sports. L''ailier droit Alexei Kovalev des Rangers de New York déjouant le gardien de but Kirk McLean des Canucks de Vancouver lors de la Finale de Coupe Stanley de 1994 figurent sur la couverture du jeu NHL 95.', 'https://fr.wikipedia.org/wiki/NHL_95'),
  ('Q524267', 'Frogger est un jeu vidéo d''arcade développé par Konami et sorti en 1981. Il est généralement considéré comme un classique de ce média.

Avant sa sortie, le jeu a failli être abandonné par la direction de Sega/Gremlin qui le jugeait trop enfantin. C''est Elizabeth Falconer, une analyste de marché de l''entreprise, qui a convaincu ses supérieurs de tester le jeu. Le prototype a été installé au ''''Spanky''s Saloon'''', un bar de San Diego fréquenté par une clientèle masculine adulte, où il a rencontré un succès immédiat, validant sa production.', 'https://fr.wikipedia.org/wiki/Frogger'),
  ('Q2816655', '3×3 Eyes: Seima Kōrin-den est un jeu vidéo sorti en 1992 sur Super Famicom. Il s''agit du tout premier jeu 3×3 Eyes à être réalisé. C''est un jeu vidéo de rôle avec la traditionnelle vue de dessus et les personnages en SD, avec quelques scènes animées. Le scénario est assez similaire au sixième volume du manga.', 'https://fr.wikipedia.org/wiki/3%C3%973_Eyes:_Seima_K%C5%8Drin-den'),
  ('Q3339129', 'Newman Haas IndyCar featuring Nigel Mansell est un jeu vidéo de course sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Gremlin Interactive et édité par Acclaim Entertainment.', 'https://fr.wikipedia.org/wiki/Newman_Haas_IndyCar_featuring_Nigel_Mansell'),
  ('Q2887296', 'Bass Masters Classic: Pro Edition est un jeu vidéo de pêche sorti en 1994 sur Mega Drive et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Bass_Masters_Classic:_Pro_Edition'),
  ('Q3342014', 'Ninja Gaiden Trilogy est une compilation de jeu vidéo d''action/plates-formes par Tecmo. Elle est distribuée en 1995 sur Super Nintendo.

Elle regroupe les 3 jeux de la série Ninja Gaiden parut sur Nintendo Entertainment System:

1988 - Ninja Gaiden

1990 - Ninja Gaiden II: The Dark Sword of Chaos

1991 - Ninja Gaiden III: The Ancient Ship of Doom

Les trois jeux de la compilation sont aussi déverrouillables en version Super Nintendo dans le nouveau titre original Ninja Gaiden paru en 2004 sur Xbox. Les versions Super Nintendo ne sont plus jamais reparus par la suite, les rééditions sur des services comme la Console Virtuelle utilisant plutôt les jeux d''origine de la Nintendo Entertainment System.', 'https://fr.wikipedia.org/wiki/Ninja_Gaiden_Trilogy'),
  ('Q388247', 'Might and Magic III: Les Îles de Terra (titre original: Isles of Terra) est un jeu vidéo de type dungeon crawler sorti en 1991. Il a été développé par le studio New World Computing. C''est le troisième volet de la série Might and Magic.', 'https://fr.wikipedia.org/wiki/Might_and_Magic_III_:_Les_%C3%8Eles_de_Terra'),
  ('Q3334422', 'NHL 96 est un jeu vidéo de hockey sur glace sorti en 1996 et fonctionne sur Mega Drive et Super Nintendo. Le jeu a été développé par Electronic Arts puis édité par EA Sports. Scott Stevens des Devils du New Jersey et Steve Yzerman des Red Wings de Détroit figurent sur la couverture du jeu.', 'https://fr.wikipedia.org/wiki/NHL_96'),
  ('Q3338898', 'New 3D Golf Simulation: Harukanaru Augusta est un jeu vidéo de golf sorti en 1991 sur Super Nintendo, puis en 1993 sur Mega Drive. Le jeu a été développé et édité par T&E Soft. Il est sorti uniquement au Japon.', 'https://fr.wikipedia.org/wiki/New_3D_Golf_Simulation:_Harukanaru_Augusta'),
  ('Q2904717', 'Alien vs Predator est un jeu vidéo de type beat them all développé par Jorudan et édité par Activision et Information Global Service, sorti en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Alien_vs._Predator_(jeu_vid%C3%A9o,_1993)'),
  ('Q2756952', 'Super Tennis est un jeu vidéo de tennis sorti sur Super Nintendo en 1992. Développé par le studio Tokyo Sosheki et édité par Nintendo, il est un des premiers jeux au lancement de la console lors de sa sortie en Europe.', 'https://fr.wikipedia.org/wiki/Super_Tennis'),
  ('Q1807798', 'Plok! est un jeu vidéo pour Super Nintendo développé par Software Creations et publié par Tradewest en 1993 aux États-Unis, et ensuite par Nintendo en Europe et Activision au Japon.', 'https://fr.wikipedia.org/wiki/Plok!'),
  ('Q2841430', 'David Crane''s Amazing Tennis est un jeu vidéo de tennis sorti en 1992 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Absolute Software.

Le jeu tient son nom du programmeur David Crane.', 'https://fr.wikipedia.org/wiki/David_Crane%27s_Amazing_Tennis'),
  ('Q2846258', 'Andre Agassi Tennis est un jeu vidéo de tennis sorti en 1992 et fonctionne sur Game Gear, Master System, Mega Drive et Super Nintendo. Le jeu a été développé par TecMagik puis édité par TecMagik et Lance Investments.

Le jeu tient son nom du champion Andre Agassi.', 'https://fr.wikipedia.org/wiki/Andre_Agassi_Tennis'),
  ('Q2316943', 'Tetris Attack, nommé Panel de Pon au Japon, est un jeu vidéo de puzzle sorti en 1995 sur Super Nintendo et en 1996 sur Game Boy. Reprenant le concept général de Columns et Puyo Puyo, il a la particularité de contenir deux jeux de types différents: un jeu de réflexes où à l''instar de Tetris, la rapidité est essentielle, et un jeu de puzzle proprement dit.', 'https://fr.wikipedia.org/wiki/Tetris_Attack'),
  ('Q1827675', 'Harley''s Humongous Adventure est un jeu vidéo d''action développé par Visual Concepts et sorti en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Harley%27s_Humongous_Adventure'),
  ('Q595860', 'The Incredible Hulk est un jeu vidéo d''action sorti en 1994 sur Master System, Mega Drive et Super Nintendo, puis en 1995 sur Game Gear. Le jeu a été développé par Probe Entertainment et édité par U.S. Gold. Il est basé sur le comics The Incredible Hulk.', 'https://fr.wikipedia.org/wiki/The_Incredible_Hulk_(jeu_vid%C3%A9o,_1994)'),
  ('Q1785007', 'Pushover est un jeu vidéo de plates-formes et de réflexion développé par Red Rat Software et édité par Ocean Software en 1992 sur Amiga, Atari ST, DOS et Super Nintendo.

Le jeu a donné suite à One Step Beyond (1993).', 'https://fr.wikipedia.org/wiki/Pushover'),
  ('Q1853282', 'Jammit est un jeu vidéo de basket-ball sorti en 1994 sur 3DO, DOS, Mega Drive et Super Nintendo. Le jeu a été développé par GTE Vantage et édité par Virgin Interactive.', 'https://fr.wikipedia.org/wiki/Jammit'),
  ('Q2876628', 'B.O.B. ou Space Funky B.O.B. au Japon, est un

jeu d''action plates-formes en 2D à thème futuriste. Le jeu a été développé par Foley High-Tech Systems et Gray Matter Interactive, et édité par Electronic Arts. Il est sorti sur Mega Drive et Super Nintendo en 1993.', 'https://fr.wikipedia.org/wiki/B.O.B.'),
  ('Q2860688', 'Arcus Odyssey ou Arcus Spirits est un jeu vidéo de rôle de type Action-RPG en vue aérienne à thème fantasy. Il a été développé par Wolf Team, édité par Renovation Products et Sammy Studios, et sorti en 1991 sur Sharp X68000, Mega Drive et porté en 1993 sur Super Nintendo. Une sortie nord-américaine prévue sur Super Nintendo fut annulée. Le jeu fait partie de la série Arcus.', 'https://fr.wikipedia.org/wiki/Arcus_Odyssey'),
  ('Q2816656', '3×3 Eyes: Jūma Hōkan est un jeu vidéo d''action-aventure sorti en 1995 sur Super Famicom.', 'https://fr.wikipedia.org/wiki/3%C3%973_Eyes:_J%C5%ABma_H%C5%8Dkan'),
  ('Q1851017', 'International Superstar Soccer est un jeu vidéo de football développé par Konami Deutschland et édité par KCEO, sorti en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/International_Superstar_Soccer_(jeu_vid%C3%A9o,_1994)'),
  ('Q1800173', 'Secret of Mana (Seiken densetsu 2 au Japon) est un jeu vidéo de type action-RPG développé et édité par Square sur Super Nintendo en 1993 au Japon et en Amérique du Nord, puis en 1994 en Europe. C''est le second opus de la série de jeux vidéo Mana. L''intrigue prend place dans un univers d''heroic fantasy et suit l''histoire de trois héros qui tentent d''empêcher un empire de conquérir le monde à l''aide d''une ancienne forteresse volante.

Secret of Mana mêle action-aventure et éléments de jeu vidéo de rôle, comme l''évolution des personnages et la magie. Il intègre également un système de combat en temps réel plutôt que l''habituel tour par tour du genre RPG et un système de menu circulaire typique. Le joueur dirige simultanément un groupe de trois personnages, dont deux sont dirigés par l''intelligence artificielle. Le jeu permet à un deuxième et troisième joueur de rentrer à tout moment dans la partie, permettant ainsi de jouer en multijoueur coopératif. Le jeu est conçu par Kōichi Ishii et Hiromichi Tanaka, produit par ce dernier et réalisé par le premier, et programmé par Nasir Gebelli. La bande-son est composée par Hiroki Kikuta.', 'https://fr.wikipedia.org/wiki/Secret_of_Mana'),
  ('Q1854477', 'Urban Strike est un jeu vidéo d''action sorti en 1994 et sur Mega Drive puis converti sur Game Boy, Game Gear et Super Nintendo. Le jeu a été développé par The Edge, Foley Hi-Tech et Ganite Bay Software puis édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/Urban_Strike'),
  ('Q1848990', 'Shadowrun est un jeu vidéo d''action-RPG développé par Beam Software et édité par Data East sur Super Nintendo en mai 1993. Il est vaguement inspiré du jeu de rôle cyberpunk Shadowrun publié par FanPro.

Le joueur incarne le rôle de Jake Armitage, un messager presque tué au cours d''une fusillade dans les rues de Seattle, en 2050, par un commando de tueurs. Il se réveille à la morgue, souffrant d''une grave amnésie.', 'https://fr.wikipedia.org/wiki/Shadowrun_(jeu_vid%C3%A9o,_1993)'),
  ('Q3459375', 'SD Gundam: GX est un jeu vidéo de stratégie développé et édité par Bandai en mai 1994 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam.', 'https://fr.wikipedia.org/wiki/SD_Gundam:_GX'),
  ('Q3459390', 'SD Gundam: G Next est un jeu vidéo de stratégie développé et édité par Bandai en décembre 1995 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. Ce jeu a connu une extension appelée SD Gundam: G Next - Unit and map collection.', 'https://fr.wikipedia.org/wiki/SD_Gundam:_G_Next'),
  ('Q3459395', 'SD Gundam: Power Formation Puzzle est un jeu vidéo de puzzle au tour par tour développé et édité par Bandai en 1996 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam.', 'https://fr.wikipedia.org/wiki/SD_Gundam:_Power_Formation_Puzzle'),
  ('Q3459415', 'SD Gundam Gaiden: Knight Gundam Monogatari - Ooinaru Isan est un jeu vidéo de rôle développé et édité par Bandai en décembre 1991 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. Il est notamment basé sur l''univers de SD Gundam Gaiden Sieg Zion Hen et c''est le troisième opus d''une série composée de cinq jeux vidéo de rôle.', 'https://fr.wikipedia.org/wiki/SD_Gundam_Gaiden:_Knight_Gundam_Monogatari_-_Ooinaru_Isan'),
  ('Q1773728', 'Super Double Dragon, ou Return of Double Dragon: "Sleeping Dragon" has Awoke au Japon, est un jeu vidéo de type beat them all développé par Technos et édité par Tradewest sur Super Nintendo en 1992.

Contrairement aux autres volets de la série Double Dragon, cet épisode n''a été commercialisé que sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Double_Dragon'),
  ('Q1809250', 'Mario Paint est un jeu vidéo ludo-éducatif de création sorti sur Super Nintendo en 1992. Mario Paint consiste en plusieurs modes de créations différents conçus pour être utilisés avec la souris Super Nintendo, soit un éditeur d''image matricielle, un programme de création d''animation 2D et un programme de création musicale. Le jeu propose aussi un mini-jeu d''adresse.', 'https://fr.wikipedia.org/wiki/Mario_Paint'),
  ('Q2827341', 'Aguri Suzuki F-1 Super Driving (également connu sous le nom de Redline F-1 Racer en Amérique du Nord) est un jeu vidéo sorti en 1992 sur Super Nintendo. Il a ensuite été porté sur Game Boy en 1993. Cette simulation de Formule 1 propose au joueur de se mettre dans la peau d''Aguri Suzuki, un ancien pilote de Formule 1 jouissant d''une grande notoriété dans son pays d''origine, le Japon (qu''il peut renommer à sa guise). Le joueur roule par défaut à bord d''une Footwork Racing (ancienne écurie d''Aguri Suzuki), mais peut opter pour une monoplace aux couleurs de Ferrari ou Williams.

Le jeu reprend la saison 1992 du championnat du monde de Formule 1 et les seize Grands Prix qu''elle compte. On y retrouve en plus d''Aguri Suzuki quinze des pilotes ayant concouru cette année-là, ce qui quantitativement représente un record pour une simulation de Formule 1 sur une console 16 bits. Si les pilotes sont officiels, les écuries ne sont en revanche pas nommées (bien que reconnaissables à leurs couleurs), et pas nécessairement affectées aux pilotes conformément à la saison 1992.', 'https://fr.wikipedia.org/wiki/Aguri_Suzuki_F-1_Super_Driving'),
  ('Q607073', 'NHL Hockey 94 (aussi appelé NHL ''94) est un jeu vidéo de hockey sur glace sorti en 1993 sur Mega Drive. Le jeu a été développé par EA Sports et édité par Electronic Arts. Le jeu contient les licences officielles de la ligue nationale de hockey.

NHL''94 est classé en 2003 par IGN en position 16 parmi les 100 meilleurs jeux de tous les temps et a été nommé meilleur jeu de sport de tous les temps par le site Boston.com ainsi que plusieurs autres sites de jeux vidéo.', 'https://fr.wikipedia.org/wiki/NHL_Hockey_94'),
  ('Q3388790', 'Pinocchio est un jeu vidéo de plates-formes sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé par Virgin Studios London, Bit Managers et NMS Software en collaboration avec Walt Disney Feature Animation puis édité par Buena Vista Games, THQ et Virgin Interactive.

Il s''agit d''une adaptation du film Pinocchio de Disney, sorti en 1940.', 'https://fr.wikipedia.org/wiki/Pinocchio_(jeu_vid%C3%A9o)'),
  ('Q3386242', 'Spider-Man and Venom: Separation Anxiety est un jeu vidéo de type beat them all sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé par Software Creations et édité par Acclaim. Il est basé sur le comics Spider-Man. Il fait suite à Spider-Man and Venom: Maximum Carnage sorti l''année précédente. Le jeu a aussi été porté sur PC.', 'https://fr.wikipedia.org/wiki/Spider-Man_and_Venom:_Separation_Anxiety'),
  ('Q3496985', 'Star Trek: Deep Space Nine - Crossroads of Time est un jeu vidéo d''action et d''aventure sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé par Novotrade et édité par Virgin Interactive. Il est basé sur la série télévisée Star Trek: Deep Space Nine.', 'https://fr.wikipedia.org/wiki/Star_Trek:_Deep_Space_Nine_-_Crossroads_of_Time'),
  ('Q634300', 'TNN Bass Tournament of Champions est un jeu vidéo de pêche sorti en 1993 sur Mega Drive et Super Nintendo. Le jeu a été développé par ASCII Entertainment et édité par ASC Games. Il a connu une suite portant le nom de TNN Outdoors ''96.', 'https://fr.wikipedia.org/wiki/TNN_Bass_Tournament_of_Champions'),
  ('Q3397941', 'Popful Mail est un jeu vidéo d''action-RPG sorti en 1994 et fonctionne sur Mega-CD, Super Famicom, PC-Engine CD, PC-88 et PC-98. Le jeu a été développé par Falcom et édité par Working Designs.', 'https://fr.wikipedia.org/wiki/Popful_Mail'),
  ('Q619025', 'R-Type III: The Third Lightning est un jeu vidéo de type shoot ''em up développé et édité par Irem en 1993 sur Super Nintendo.

Il s''agit du troisième épisode de la série R-Type.', 'https://fr.wikipedia.org/wiki/R-Type_III:_The_Third_Lightning'),
  ('Q3522153', 'The Pagemaster est un jeu vidéo de plates-formes sorti sur Super Nintendo, Mega Drive et Game Boy en 1994 pour la France, développé par Probe Entertainment Limited et édité par Fox Interactive.

Il s''agit d''une adaptation du film Richard au pays des livres magiques.', 'https://fr.wikipedia.org/wiki/The_Pagemaster_(jeu_vid%C3%A9o)'),
  ('Q2394252', 'PGA European Tour est un jeu vidéo de golf développé et édité par Electronic Arts, sorti en 1994 sur Amiga, CD32 DOS, Mega Drive, Game Boy et Super Nintendo (en 1996 pour cette dernière version).', 'https://fr.wikipedia.org/wiki/PGA_European_Tour_(jeu_vid%C3%A9o,_1994)'),
  ('Q2362863', 'Go Go Ackman est un jeu vidéo de plates-formes tiré du manga Go! Go! Ackman d''Akira Toriyama. Il est sorti sur Super Famicom en 1994.', 'https://fr.wikipedia.org/wiki/Go_Go_Ackman_(jeu_vid%C3%A9o,_1994)'),
  ('Q2425425', 'WildSnake est un jeu vidéo de type puzzle game développé par Bullet-Proof Software et édité par Spectrum Holobyte, sorti en 1994 sur Super Nintendo et Game Boy. Le jeu existe également à l''état de prototype sur Mega Drive.', 'https://fr.wikipedia.org/wiki/WildSnake'),
  ('Q3528972', 'Timecop est un jeu vidéo d''action et de plates-formes de science-fiction développé par Cryo Interactive et édité par Victor Interactive en 1995. Il s''agit d''une adaptation du film du même nom sorti en 1994, dans lequel Jean-Claude Van Damme tient le rôle principal.', 'https://fr.wikipedia.org/wiki/Timecop_(jeu_vid%C3%A9o)'),
  ('Q2387100', 'Obitus est un jeu vidéo de rôle développé par Scenario Developments et édité par Psygnosis en 1991 sur Amiga, puis porté fin 1991 sur Atari ST et DOS.', 'https://fr.wikipedia.org/wiki/Obitus'),
  ('Q2406801', 'ESPN Baseball Tonight est un jeu vidéo de baseball sorti en 1994 sur PC, Mega-CD, Mega Drive et Super Nintendo. Le jeu a été développé par Stormfront Studios et édité par Sony Imagesoft.', 'https://fr.wikipedia.org/wiki/ESPN_Baseball_Tonight'),
  ('Q2440904', 'Super Adventure Island est un jeu vidéo de plates-formes, développé par Produce! et édité par Hudson Soft, sorti en 1992 sur Super Nintendo.C''est le troisième jeu de la série Adventure Island.', 'https://fr.wikipedia.org/wiki/Super_Adventure_Island'),
  ('Q3342577', 'Nobunaga no Yabō: Haōden est un jeu vidéo de grande stratégie développé et édité par Koei, sorti en 1992 sur PC-98. Il a été adapté sur DOS, FM Towns, 3DO, Mega Drive, Mega-CD, PlayStation, Super Nintendo et Sharp X68000.

Le jeu fait partie de la série Nobunaga''s Ambition.', 'https://fr.wikipedia.org/wiki/Nobunaga_no_Yab%C5%8D:_Ha%C5%8Dden'),
  ('Q609155', 'Aerobiz Supersonic est un jeu vidéo de gestion sorti en 1993 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Koei.', 'https://fr.wikipedia.org/wiki/Aerobiz_Supersonic'),
  ('Q610749', 'Mega Man 7 (Rockman 7: Shukumei no Taiketsu! au Japon) est un jeu d''action-plate-formes développé et édité par Capcom sur Super Nintendo en 1995, puis porté sur Console virtuelle (Wii U, New Nintendo 3DS). C''est le septième jeu de la série principale de Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_7'),
  ('Q3532345', 'Torneko no Daibōken: Fushigi no Dungeon est un jeu vidéo réalisé par le développeur Chunsoft en 1993 pour l''éditeur japonais Enix. C''est une suite directe de Dragon Quest IV.', 'https://fr.wikipedia.org/wiki/Torneko_no_Daib%C5%8Dken:_Fushigi_no_Dungeon'),
  ('Q3496990', 'Star Trek: Starfleet Academy - Starship Bridge Simulator est un jeu vidéo de simulation sorti en 1995 sur 32X et Super Nintendo. Le jeu a été développé et édité par Interplay (la version 32X a été développé par High Voltage Software). Il est basé sur l''univers de Star Trek.', 'https://fr.wikipedia.org/wiki/Star_Trek:_Starfleet_Academy_-_Starship_Bridge_Simulator'),
  ('Q3496991', 'Star Trek: The Next Generation - Echoes from the Past est un jeu vidéo de rôle développé par Spectrum HoloByte, sorti en 1994 sur Mega Drive et Super Nintendo. La version Super Nintendo s''intitule Star Trek: The Next Generation - Future''s Past.

Il est basé sur la série télévisée Star Trek: La Nouvelle Génération.', 'https://fr.wikipedia.org/wiki/Star_Trek:_The_Next_Generation_-_Echoes_from_the_Past'),
  ('Q601336', 'Majin Tensei est un jeu vidéo de rôle tactique T-RPG originellement sorti sur SNES le 28 janvier 1994, développé et édité par Atlus. C''est le premier jeu de la série Majin Tensei. Il est également ressorti sur console virtuelle (Wii) en 2011, ainsi que sur console virtuelle (Wii U) en 2015.', 'https://fr.wikipedia.org/wiki/Majin_Tensei_(jeu_vid%C3%A9o)'),
  ('Q610138', 'SimAnt est un jeu vidéo de simulation de fourmis, développé et édité chez Maxis en 1991. Il est conçu par Will Wright, le créateur des autres Sims comme SimCity et Les Sims. Le jeu propose au joueur de faire évoluer une jeune reine fourmi pour ensuite prendre contrôle d’une fourmi de la colonie pour conquérir une à une les zones d’un jardin et d’un appartement.

Outre les fourmis rouges et les araignées, le danger provient aussi des pieds humains et de la tondeuse à gazon.

Le but premier de ce jeu est de détruire la reine des fourmis adverses, les fourmis rouges. Pour cela, il faut construire une colonie en creusant et en cherchant de la nourriture. À la première naissance, le personnage est une fourmi ouvrière mais il est aussi possible d''incarner un soldat ou un reproducteur.', 'https://fr.wikipedia.org/wiki/SimAnt'),
  ('Q3529116', 'Tin Star est un jeu vidéo de tir au pistolet développé par Software Creations, sorti en 1994 sur Super Nintendo. Il est compatible avec le Super Scope et la souris Super Nintendo. L''univers du jeu mêle western et science-fiction.', 'https://fr.wikipedia.org/wiki/Tin_Star'),
  ('Q3529218', 'Tintin au Tibet est un jeu vidéo d''aventure à la troisième personne sorti en octobre 1995 sur Super Nintendo, en avril 1996 sur Mega Drive, Game Gear, Game Boy et PC, et en 2001 sur Game Boy Color. Il a été conçu et édité par Infogrames, et développé par Bit Managers (versions Game Boy, Game Gear et Game Boy Color) et Infogrames (versions PC, Mega Drive, Super Nintendo).', 'https://fr.wikipedia.org/wiki/Tintin_au_Tibet_(jeu_vid%C3%A9o)'),
  ('Q1661310', 'Indiana Jones'' Greatest Adventures est un jeu de plates-formes développé par Factor 5 et LucasArts, publié par JVC, et sorti exclusivement sur Super Nintendo. Il s''agit de l''adaptation des trois films Indiana Jones: Les Aventuriers de l''arche perdue, Le Temple maudit et La Dernière Croisade. Il est considéré aujourd''hui encore comme un des meilleurs jeux vidéo jamais sorti sur la licence Indiana Jones. Cependant, les trois jeux étant réunis sur une même cartouche, il y a moins de niveaux et peu de boss à affronter, d''où son succès moindre par rapport à Super Star Wars sorti pourtant deux ans plus tôt et aussi édité par LucasArts. Ce jeu a tout de même été apprécié pour sa beauté graphique, sa difficulté mesurée, sa maniabilité et sa fidélité envers les films (chaque niveau représente une scène de la trilogie).', 'https://fr.wikipedia.org/wiki/Indiana_Jones%27_Greatest_Adventures'),
  ('Q2376909', 'Ultima VII: La Porte noire et Ultima VII: Serpent Isle sont deux jeux vidéo publiés successivement en 1992 puis 1993, et constituant le septième épisode de la série de jeux de rôle sur ordinateur Ultima. Il commence la troisième trilogie dite de l’« Âge de l''Armageddon », qui se poursuit avec Ultima VIII et IX.

Ultima VII fut publié en deux parties, constituant chacune un jeu: La Porte noire en 1992 et Serpent Isle en 1993. Chacune de ces parties possède une extension, respectivement Forge of Virtue et The Silver Seed. Le moteur du jeu des deux parties est quasiment identique.

Le jeu se déroule dans deux mondes parallèles - Britannia et l’Île Serpent - menacés par une entité malveillante d’une tierce dimension. Parmi les nombreuses quêtes que peut accomplir le joueur, la principale consiste à conjurer cette menace.', 'https://fr.wikipedia.org/wiki/Ultima_VII_:_La_Porte_noire_et_Serpent_Isle'),
  ('Q1658920', 'Illusion of Time, ou Illusion of Gaïa au Japon et en Amérique du Nord, est un jeu vidéo de type action-RPG sur Super Nintendo développé par Quintet et édité par Enix en 1993 au Japon et Nintendo aux États-Unis en 1994 et en 1995 en France. L''histoire a été écrite par la romancière Mariko Ōhara, le design des personnages a été réalisé par la célèbre mangaka Moto Hagio, et la musique est de Yasuhiro Kawasaki, qui a également composé celles de plusieurs jeux Takara et Tomy.', 'https://fr.wikipedia.org/wiki/Illusion_of_Time'),
  ('Q2362159', 'Outlander est un jeu vidéo d''action et de combat motorisé sorti en 1992 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Mindscape.', 'https://fr.wikipedia.org/wiki/Outlander_(jeu_vid%C3%A9o)'),
  ('Q3497781', 'Steel Talons est un simulateur de vol de combat développé par Atari Games, sorti en 1991 sur borne d''arcade. Il a été adapté sur Lynx (1991), sur Mega Drive (1992), Super Nintendo (1992) et Falcon 030 (1995).', 'https://fr.wikipedia.org/wiki/Steel_Talons'),
  ('Q3373888', 'Pebble Beach Golf Links est un jeu vidéo de golf sorti en 1994 et fonctionne sur Mega Drive, Saturn, Super Nintendo et 3DO. Le jeu a été développé par T&E Soft et édité par Sega.

Le jeu tire son nom du parcours de golf réputé Pebble Beach Golf Links en Californie.', 'https://fr.wikipedia.org/wiki/Pebble_Beach_Golf_Links_(jeu_vid%C3%A9o)'),
  ('Q2423838', 'Phantom 2040 est un jeu vidéo de plates-formes sorti en 1995 sur Mega Drive, Game Gear et Super Nintendo. Le jeu a été développé et édité par Viacom New Media.

Il est basé sur la sérié télévisée d''animation Fantôme 2040.', 'https://fr.wikipedia.org/wiki/Phantom_2040'),
  ('Q2414296', 'Axelay est un jeu vidéo de type shoot them up développé et édité par Konami en 1992 sur Super Nintendo.

Il utilise, un niveau sur deux, un rendu classique type plateforme (vue de côté, deux dimensions avec défilement différentiel pour le décor) et un rendu original qui fait défiler le décor sous le vaisseau, de manière courbe, comme s''il avançait droit devant au-dessus d''une sphère que serait la planète: une sorte de fausse 3D.', 'https://fr.wikipedia.org/wiki/Axelay'),
  ('Q1724425', 'Super Soccer, connu au Japon sous le titre Super Formation Soccer, est un jeu vidéo de football développé par Human Entertainment et édité par Nintendo. Il s''agit du premier jeu de football de la Super Nintendo lors de sa sortie en 1992.

Super Soccer fait partie des cinq jeux de lancement de la nouvelle console 16-bits de Nintendo en Europe, au même titre que Super Tennis, F-Zero et Super R-Type. Super Mario World étant directement vendu avec la console.', 'https://fr.wikipedia.org/wiki/Super_Soccer'),
  ('Q3497140', 'Stargate est un jeu vidéo de plate-forme et d''action sorti en 1995 sur Game Boy, Mega Drive et Super Nintendo. Le jeu a été développé par Torus Games et édité par Acclaim.

Il est basé sur le film Stargate, la porte des étoiles, sorti en 1994. En 2015, dans le cadre d''un projet, les responsables du site Internet Archive ont mis en ligne 2 300 jeux MS-DOS jouables sur navigateur dont celui sur Stargate édité par Acclaim en 1995.', 'https://fr.wikipedia.org/wiki/Stargate_(jeu_vid%C3%A9o,_1995)'),
  ('Q3523014', 'The Tick est un jeu vidéo de plates-formes sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Software Creations et édité par Fox Interactive.

Il est basé sur la série animée Super Zéro de Ben Edlund, elle-même adaptée des comics The Tick.', 'https://fr.wikipedia.org/wiki/The_Tick_(jeu_vid%C3%A9o)'),
  ('Q2414743', 'Breath of Fire II est un jeu vidéo de rôle, développé et édité par Capcom, sorti en 1994 sur Super Nintendo. C''est le second épisode de la série Breath of Fire.', 'https://fr.wikipedia.org/wiki/Breath_of_Fire_II'),
  ('Q2440245', 'Shin Kidō Senshi Gundam W: Endless Duel est un jeu vidéo de combat développé et édité par Bandai en 1996 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment l''anime Gundam Wing.', 'https://fr.wikipedia.org/wiki/Shin_Kid%C5%8D_Senshi_Gundam_W:_Endless_Duel'),
  ('Q2404768', 'Winter Olympics: Lillehammer ''94 est un jeu vidéo de sport d''hiver développé par Tiertex Design Studios et édité par U.S. Gold sur plusieurs plates-formes en 1993. c''est le jeu vidéo officiel des XVIIes Jeux Olympiques d''hiver de Lillehammer en Norvège.

Toutes les versions ont été publiées par U.S. Gold, le titulaire des droits. Les versions pour ordinateur domestique (Amiga et PC) ont été développées par ID Software (à ne pas confondre avec id Software) et les versions console (Game Gear, Mega Drive / Mega Drive II, Master System, Super NES) ont été développées par Tiertex. Il existe également des différences majeures entre les plates-formes. La version Game Boy s''appelle Winter Gold en Europe.', 'https://fr.wikipedia.org/wiki/Winter_Olympics:_Lillehammer_%2794'),
  ('Q3496959', 'Star Fox 2 est un jeu vidéo de type shoot ''em up développé par Nintendo et Argonaut Games pour la Super Nintendo. Il s''agit du deuxième opus de la série Star Fox, succédant ainsi à Star Wing (Star Fox en version originale). Prévu pour sortir en 1996, le jeu est annulé en raison de l''arrivée imminente de la Nintendo 64. Star Fox 2 sort finalement en 2017, étant préinstallé sur la Super NES Mini. Il est également réédité le 12 décembre 2019 dans le catalogue Super Nintendo du service Online de la console hybride Nintendo Switch.', 'https://fr.wikipedia.org/wiki/Star_Fox_2'),
  ('Q3504191', 'Super Gachapon World: SD Gundam X est un jeu vidéo de stratégie développé par Bandai, et édité par Yutaka en septembre 1992 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam.', 'https://fr.wikipedia.org/wiki/Super_Gachapon_World:_SD_Gundam_X'),
  ('Q3532667', 'Total Carnage est un jeu vidéo d''action développé et commercialisé par Midway Manufacturing Company en 1992 sur borne d''arcade. Il a été adapté sur Super Nintendo en 1993 et sur Amiga 500, 1200, CD32 et DOS en 1994. Songbird Productions l''a adapté sur Jaguar en 2004.

C''est la suite du hit Smash TV (1990) de Williams Electronics Games.', 'https://fr.wikipedia.org/wiki/Total_Carnage'),
  ('Q636246', 'Sparkster est un jeu vidéo d''action et de plates-formes à défilement horizontal sorti en 1994. Développé et édité par Konami sur Super Nintendo, le jeu est réalisé par Hideo Ueda.

Sparkster partage un titre identique en Europe et en Amérique du Nord avec une version sortie sur Mega Drive, notamment titrée Sparkster: Rocket Knight Adventures 2 au Japon. La version sur Mega Drive est la suite de Rocket Knight Adventures, le premier jeu de la série, dont la version sur Super Nintendo ne partage pas la continuité, les deux versions étant différentes.', 'https://fr.wikipedia.org/wiki/Sparkster'),
  ('Q3566321', 'Warlock ou Beware of the ultimate evil! Warlock, est un jeu vidéo d''action et de plates-formes à thème de d''horreur fantasy. Le jeu a été développé par Realtime Associates et Trimark Interactive, et édité par Acclaim et LJN. Il est sorti en 1994 sur Super Nintendo et sur Mega Drive. Il s''agit d''une adaptation de la série de films d''horreur Warlock (1989).', 'https://fr.wikipedia.org/wiki/Warlock_(jeu_vid%C3%A9o)'),
  ('Q3521126', 'The Great Circus Mystery starring Mickey and Minnie est un jeu vidéo de plate-forme et d''action sorti en 1994 sur Mega Drive et Super Nintendo. C''est le second épisode de la série The Magical Quest. Le jeu a été développé et édité par Capcom.

Le jeu est ressorti en 2003 sur Game Boy Advance développé par Capcom Production Studio 3 sous le titre Disney''s Magical Quest 2 starring Mickey and Minnie.', 'https://fr.wikipedia.org/wiki/The_Great_Circus_Mystery_starring_Mickey_and_Minnie'),
  ('Q3541110', 'True Lies est un jeu vidéo d''action sorti en 1994 sur Game Boy, Game Gear, Mega Drive et Super Nintendo. Le jeu a été développé par Beam Software et édité par Acclaim.

Il s''agit de l''adaptation du film True Lies de James Cameron, sorti en 1994.', 'https://fr.wikipedia.org/wiki/True_Lies_(jeu_vid%C3%A9o)'),
  ('Q3516989', 'Tecmo Super NBA Basketball est un jeu vidéo de basket-ball sorti en 1992 sur Super Nintendo. Le jeu a été développé et édité par Tecmo. Il a ensuite été porté sur Mega Drive l''année suivante.', 'https://fr.wikipedia.org/wiki/Tecmo_Super_NBA_Basketball'),
  ('Q3504105', 'Super Battleship: The Classic Naval Combat Game est un jeu vidéo de réflexion sorti en 1993 sur Super Nintendo. Le jeu a été développé par The Software Toolworks et édité par Mindscape. Mindscape a développé le jeu sur Mega Drive l''année suivante. Il est basé sur un jeu de société, la bataille navale, et fait suite au jeu vidéo Battleship.', 'https://fr.wikipedia.org/wiki/Super_Battleship:_The_Classic_Naval_Combat_Game'),
  ('Q3511972', 'Terminator 2: Judgment Day est un jeu vidéo de tir au pistolet développé et commercialisé par Midway en 1991. Sorti initialement sur borne d''arcade, le jeu a été renommé T2: The Arcade Game pour les conversions sur supports familiaux afin de ne pas interférer avec les autres adaptations du film Terminator 2: Le Jugement dernier de James Cameron. Le jeu a été converti en 1992 et 1993 sur Amiga, DOS, Master System, Mega Drive, Super Nintendo, Game Boy et Game Gear sous le titre T2: The Arcade Game.', 'https://fr.wikipedia.org/wiki/T2:_The_Arcade_Game'),
  ('Q2471838', 'Great Courts est un jeu vidéo de tennis développé par Blue Byte et édité par Ubisoft en 1989. Il est également connu sous le nom de Pro Tennis Tour et de Jimmy Connors Pro Tennis Tour.

Il est développé sur les ordinateurs 16 bits Amiga, Atari ST et sur compatibles PC (MS-DOS). Il est considéré à sa sortie comme l''une des premières « véritables » simulations du genre. Ce premier hit de la société, Tilt d''or de la « meilleure simulation sportive » de l''année 1989, fut adapté sur les ordinateurs 8 bits Amstrad CPC, Commodore 64, ZX Spectrum, la console 16 bits Super Nintendo et la console portable Lynx.', 'https://fr.wikipedia.org/wiki/Great_Courts'),
  ('Q3549559', 'Variable Geo, également connue sous le titre V.G., est une série de jeux vidéo de combat/eroge en 2D, développée et publiée par la société Giga sur ordinateur. Elle est aussi adaptée et distribuée par Technical Group Laboratory (TGL) sur consoles de salon. La série se concentre sur les participantes d''une compétition d''arts martiaux durant laquelle elles doivent faire la publicité pour des restaurants familiaux en tant que serveuses lorsqu''elles ne se battent pas.', 'https://fr.wikipedia.org/wiki/Variable_Geo'),
  ('Q2420037', 'Bart''s Nightmare est un jeu vidéo sorti en 1992 sur Super NES et Mega Drive. Développé par Sculptured Software et édité par Acclaim, ce jeu est basé sur la série Les Simpson.', 'https://fr.wikipedia.org/wiki/Bart%27s_Nightmare'),
  ('Q3536083', 'Toys: Let the Toy Wars Begin! (souvent abrégé en Toys) est un jeu vidéo d''action sorti en 1993 sur Mega Drive. Le jeu a été développé par Imagineering Inc. et édité par Absolute Entertainment. Il est basé sur le film Toys sorti en 1992.', 'https://fr.wikipedia.org/wiki/Toys:_Let_the_Toy_Wars_Begin!'),
  ('Q2414752', 'Toy Story est un jeu vidéo de plates-formes sorti à partir de 1995 sur Mega Drive, Super Nintendo, PC puis sur Game Boy. Le jeu est l''adaptation du film de Disney/Pixar Toy Story. Le jeu a été nommé au titre de meilleur jeu vidéo aux Kids'' Choice Awards 1997.', 'https://fr.wikipedia.org/wiki/Toy_Story_(jeu_vid%C3%A9o)'),
  ('Q3504196', 'Super High Impact est un jeu vidéo de football américain développé par Midway Manufacturing Company, sorti en 1991 sur borne d''arcade. Il a été adapté sur Mega Drive en 1992 et sur Super Nintendo en 1993. Il fait suite à High Impact Football (1990).', 'https://fr.wikipedia.org/wiki/Super_High_Impact'),
  ('Q3516983', 'Tecmo Super Baseball est un jeu vidéo de baseball sorti en 1994 et fonctionne sur Mega Drive et Super Nintendo. Le jeu a été développé puis édité par Tecmo.', 'https://fr.wikipedia.org/wiki/Tecmo_Super_Baseball'),
  ('Q3519716', 'The Adventures of Mighty Max est un jeu vidéo d''action et de plates-formes développé par WJS Design et édité par Ocean Software, sorti en 1994 sur Mega Drive.

Le jeu se base sur la série télévisée et la gamme de jouet Mighty Max.', 'https://fr.wikipedia.org/wiki/The_Adventures_of_Mighty_Max'),
  ('Q3539815', 'Troddlers est un jeu vidéo de réflexion développé par le studio suédois ATOD Design et édité par The Sales Curves en 1992 sur Amiga. Le jeu a été adapté sur DOS et Super Nintendo en 1993.

À mi-chemin entre Spherical (1989) et Lemmings (1991), le but du jeu est de rapatrier de petites créatures, les Troddlers, jusqu''à la porte de sortie du niveau en posant opportunément des blocs de pierre sur le parcours.', 'https://fr.wikipedia.org/wiki/Troddlers'),
  ('Q3566369', 'WarpSpeed est un simulateur de vol de combat sorti en 1993 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Accolade.', 'https://fr.wikipedia.org/wiki/WarpSpeed'),
  ('Q3504101', 'Super Adventure Island II est un jeu vidéo de plates-formes par Hudson Soft sorti en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Adventure_Island_II'),
  ('Q3564651', 'WCW Super Brawl Wrestling est un jeu vidéo de catch professionnel commercialisé sur console SNES en 1994. Troisième jeu vidéo basé sur la World Championship Wrestling (WCW), le titre vient du pay-per-view du même nom, SuperBrawl. Il s''agit du seul jeu vidéo WCW à être commercialisé sur Super Nintendo, et le dernier à être développé par FCI.', 'https://fr.wikipedia.org/wiki/WCW_SuperBrawl_Wrestling'),
  ('Q644838', 'Rise of the Robots est un jeu vidéo de combat sorti en 1994 sur 3DO, Amiga, Amiga CD32, CD-I, DOS, Game Boy, Game Gear, Master System, Mega Drive et Super Nintendo. Le jeu a été développé par Instinct Design et Mirage Technologies et édité par Time Warner Interactive.

Il a pour suite Rise 2: Resurrection.', 'https://fr.wikipedia.org/wiki/Rise_of_the_Robots'),
  ('Q3493433', 'Spider-Man: The Animated Series est un jeu vidéo de plates-formes sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par Western Technologies et édité par LJN. Il est basé sur le dessin animé Spider-Man.', 'https://fr.wikipedia.org/wiki/Spider-Man:_The_Animated_Series'),
  ('Q2444666', 'RoboCop versus The Terminator est un jeu vidéo d''action de type run and gun développé par Interplay Entertainment et Virgin Games, et édité sur Game Boy, Game Gear, Master System, Mega Drive et Super Nintendo en 1993. Il s''agit d''une adaptation de la bande-dessinée éponyme, RoboCop versus The Terminator.', 'https://fr.wikipedia.org/wiki/RoboCop_versus_The_Terminator_(jeu_vid%C3%A9o)'),
  ('Q2444696', 'The 7th Saga est un jeu vidéo de rôle développé par Produce! et édité par Enix, sorti en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/The_7th_Saga'),
  ('Q3476003', 'Scooby-Doo Mystery est un jeu vidéo d''aventure sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé par The Illusions Gaming Company sur Mega Drive et par Argonaut Software sur Super Nintendo, et il a été édité par Acclaim Entertainment. Il est basé sur le dessin animé Scooby-Doo.', 'https://fr.wikipedia.org/wiki/Scooby-Doo_Mystery'),
  ('Q682463', 'Wild Guns est un jeu vidéo de tir à la troisième personne développé par Natsume, sorti à partir de 1994 sur Super Nintendo. Il met en scène Clint et Annie, à la poursuite du Kid dans un western de science-fiction (aussi appelé space western). Il se compose de deux modes de jeu pouvant être pratiqués en solo ou à deux joueurs: en coopération pour le mode « Scénario » et en duel pour le mode « Versus ».', 'https://fr.wikipedia.org/wiki/Wild_Guns'),
  ('Q683630', 'Pinball Dreams est un jeu vidéo de flipper édité en 1992 par Digital Illusions Creative Entertainment sur Amiga, Atari Falcon030, DOS, Super Nintendo, Game Boy, Game Gear, GP32, PlayStation Portable et iOS.', 'https://fr.wikipedia.org/wiki/Pinball_Dreams'),
  ('Q2457059', 'Sengoku ou Sengoku Denshō au Japon, est un jeu vidéo du type beat them all en 2D mélangeant les thèmes urbain et du japon médiéval. Le jeu a été développé et édité par SNK en 1991 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES et en 1995 sur Neo-Geo CD (NGM 017). Il a été porté sur les consoles Mega-CD et Super Nintendo en 1993. C''est le premier opus d''une série de trois jeux vidéo.', 'https://fr.wikipedia.org/wiki/Sengoku_(jeu_vid%C3%A9o,_1991)'),
  ('Q739658', 'Sink or Swim est un jeu vidéo d''action et de réflexion développé et édité par Zeppelin Games, sorti en 1993 sur Amiga et PC (DOS). Il a été adapté sur Super Nintendo (S.O.S.: Sink or Swim) et Mega Drive et Game Gear (S.S. Lucifer Man Overboard!) en 1994.', 'https://fr.wikipedia.org/wiki/Sink_or_Swim'),
  ('Q720440', 'Darius Twin est un jeu vidéo de type shoot ''em up développé et édité par Taito, sorti en 1991 sur Super Nintendo et Console virtuelle (Wii).', 'https://fr.wikipedia.org/wiki/Darius_Twin'),
  ('Q3476647', 'SeaQuest DSV est un jeu vidéo d''action sorti en 1994 sur Game Boy, Mega Drive et Super Nintendo. Le jeu a été développé par Sculptured Software (pour les versions Mega Drive et Super Nintendo) et Unexpected Development (pour la version Game Boy); et, édité par Black Pearl Software (sur Mega Drive) et Malibu Games (sur les consoles Nintendo). Il est basé sur la série télévisée SeaQuest, police des mers.', 'https://fr.wikipedia.org/wiki/SeaQuest_DSV'),
  ('Q2450491', 'Ys V: Lost Kefin, Kingdom of Sand est un jeu vidéo de type action-RPG développé et édité par Nihon Falcom, sorti en 1995 sur Super Nintendo et en 2006 sur PlayStation 2.', 'https://fr.wikipedia.org/wiki/Ys_V:_Lost_Kefin,_Kingdom_of_Sand'),
  ('Q681057', 'Powermonger est un jeu de stratégie en temps réel développé par Bullfrog et publié en 1990 par Electronic Arts sur Amiga et Atari ST. Le jeu a été conçu par Peter Molyneux et reprend certaines caractéristiques de son précédent titre, Populous.', 'https://fr.wikipedia.org/wiki/Powermonger'),
  ('Q743550', 'John Madden Football ''93 est un jeu vidéo de sport (football américain) sorti en 1992 sur Mega Drive et Super Nintendo. Le jeu a été développé par EA Sports (pour la version Super Nintendo) et Blue Sky Productions (pour la version Mega Drive), et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/John_Madden_Football_%2793'),
  ('Q743523', 'Super Aleste est un shoot them up à scrolling vertical sorti en 1992 sur Super Nintendo. Le jeu a été développé par Compile puis édité par Toho. Ce titre a été très remarqué lors de sa sortie par sa fluidité, car il est un des tout premiers, à faire gérer une partie des sprites par le processeur sonore de la Super Famicom, ceci afin d''en finir avec les ralentissements systématiques de ce type de jeu sur la console de Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Aleste'),
  ('Q647377', 'Super Dany est un jeu vidéo de plate-forme développé par Cryo Interactive et publié par Virgin Games en 1994, uniquement en Europe. Il est conçu pour être joué sur la console Super Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Dany'),
  ('Q744175', 'Lord Monarch: Tokoton Sentō Densetsu est un jeu vidéo de rôle et de stratégie sorti en 1991 sur PC-98 et FM Towns, puis a été porté sur Mega Drive, Satellaview et Super Famicom. Le jeu a été développé par Nihon Falcom. Il est sorti uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Lord_Monarch:_Tokoton_Sent%C5%8D_Densetsu'),
  ('Q3459440', 'SD Kidō Senshi Gundam 2 est un jeu vidéo du type shoot them up développé par Bandai et Angel, et édité par Bandai en septembre 1993 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. C''est le dernier opus d''une série de deux jeux vidéo.', 'https://fr.wikipedia.org/wiki/SD_Kid%C5%8D_Senshi_Gundam_2'),
  ('Q3459441', 'SD Kidō Senshi Gundam: V Sakusen Shidō est un jeu vidéo du type shoot them up développé par Bandai et Angel, et édité par Bandai en septembre 1992 sur Super Nintendo. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. C''est le premier opus d''une série de deux jeux vidéo.', 'https://fr.wikipedia.org/wiki/SD_Kid%C5%8D_Senshi_Gundam:_V_Sakusen_Shid%C5%8D'),
  ('Q3493594', 'Spirou est un jeu vidéo de plates-formes développé et édité par Infogrames, sorti en 1995 sur Super Nintendo, Mega Drive et MS-DOS. Le jeu est porté sur Game Boy par Bit Managers. Il est aussi converti en 1996 sous Windows par East Point Software. Une version Game Gear était prévue, mais abandonnée, bien qu''une version prototype avec le jeu complet complet ait été divulguée en ligne.

Il est basé sur l''univers de la bande dessinée Spirou et Fantasio, créé par Rob-Vel en 1938. Il présente l''aventure de Spirou essayant de sauver son ami kidnappé le comte de Champignac et d''empêcher son ennemi juré Cyanure d''asservir le monde par son armée de robots.', 'https://fr.wikipedia.org/wiki/Spirou_(jeu_vid%C3%A9o)'),
  ('Q3492971', 'Speedy Gonzales: Los Gatos Bandidos est un jeu vidéo développé par Sunsoft et édité par Acclaim sortie sur Super Nintendo en août 1995 en Amérique du Nord. Le jeu est une adaptation du cartoon Speedy Gonzales.', 'https://fr.wikipedia.org/wiki/Speedy_Gonzales:_Los_Gatos_Bandidos'),
  ('Q3461639', 'Sailor Moon est un jeu vidéo de type beat them all développé et édité par Angel au Japon, et édité par Bandai en France (uniquement sur Super Nintendo). Il est sorti en 1993 sur Super Nintendo et en 1994 sur Mega Drive. C''est le seul jeu vidéo fondé sur la franchise Sailor Moon qui soit sorti en Occident.

La version Mega Drive comporte des graphismes et des niveaux améliorés.', 'https://fr.wikipedia.org/wiki/Sailor_Moon_(jeu_vid%C3%A9o)'),
  ('Q3636838', 'Battle Blaze est un jeu vidéo de combat un contre un en 2D se déroulant dans un univers fantasy médiéval. Le jeu a été développé et édité par Sammy Studios. Il est sorti sur Arcade en 1992, puis porté sur Super Nintendo au Japon en 1992 et en Amérique du Nord en 1994.', 'https://fr.wikipedia.org/wiki/Battle_Blaze'),
  ('Q3569675', 'Wolfchild est un jeu vidéo d''action en 2D à thème de science-fiction développé et édité par Core Design en 1992 sur Amiga et Atari ST. Le jeu a été adapté sur GameGear, Master System, Mega-CD, Mega Drive et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Wolfchild'),
  ('Q3569743', 'Wolverine: Adamantium Rage est un jeu vidéo de plates-formes sorti en 1994 sur Super Nintendo et Mega Drive. La version Mega Drive a été développée par Teeny Weeny Games et édité par Acclaim; et, la version Super Nintendo a été développée par Bits Corporation et édité par LJN. Dans le reste du monde, le jeu est publié en France le 9 décembre 1994 ainsi qu''au Japon le 27 janvier 1995.', 'https://fr.wikipedia.org/wiki/Wolverine:_Adamantium_Rage'),
  ('Q3566712', 'Waterworld est un jeu vidéo d''action basé sur le film Waterworld, édité par Ocean Software en 1995 sur Game Boy et Super Nintendo en Europe, et sur Virtual Boy aux États-Unis.', 'https://fr.wikipedia.org/wiki/Waterworld_(jeu_vid%C3%A9o,_1995)'),
  ('Q3566952', 'Weaponlord est un jeu de combat en deux dimensions développé par Visual Concepts et édité par Namco sorti sur Mega Drive et Super Nintendo en 1995.

Le jeu se déroule dans un univers médiéval-fantastique. À noter que Simon Bisley a fourni la jaquette et le logo du jeu.', 'https://fr.wikipedia.org/wiki/Weaponlord'),
  ('Q3566834', 'Wayne Gretzky and the NHLPA All-Stars est un jeu vidéo de hockey sur glace sorti en 1995 sur Mega Drive et Super Nintendo. Le jeu a été développé et édité par Time Warner Interactive.', 'https://fr.wikipedia.org/wiki/Wayne_Gretzky_and_the_NHLPA_All-Stars'),
  ('Q3661053', 'Cyber Knight est un jeu vidéo de rôle de stratégie au tour par tour à thème de science-fiction. Le jeu a été développé par Compile et Advance Communication Co. et édité par Tonkin House. Il est sorti uniquement au Japon initialement le 12 octobre 1990 sur PC-Engine puis adapté sur Super Nintendo le 30 octobre 1992. Il fait partie de la série Cyber Knight.', 'https://fr.wikipedia.org/wiki/Cyber_Knight'),
  ('Q762130', 'The Chaos Engine est un jeu vidéo d''action en 2D développé par The Bitmap Brothers et édité par Renegade en 1993. Initialement développé sur Amiga et Atari ST, le jeu a été adapté sur Amiga 1200, Amiga CD32, Mega Drive, PC et Super Nintendo.

L''histoire est inspirée du roman la Machine à différences de Bruce Sterling et l''action prend place dans une époque victorienne uchronique steampunk.

Le jeu connaît une suite en 1996, The Chaos Engine 2.', 'https://fr.wikipedia.org/wiki/The_Chaos_Engine'),
  ('Q771109', 'MLBPA Baseball (Fighting Baseball au Japon) est un jeu vidéo de baseball sorti en 1994 sur Mega Drive et Super Nintendo. Le jeu a été développé par High Score Productions et édité par Electronic Arts.', 'https://fr.wikipedia.org/wiki/MLBPA_Baseball'),
  ('Q3868738', 'Mutant Fighter ou Mutant Fighters: Death Brade, est un jeu de combat un contre un en 2D à thème mythologique. Le jeu a été développé et édité par Data East sur Arcade en 1991 puis porté sur Sharp X68000 et sur Super Nintendo par I''Max en 1993, uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Mutant_Fighter'),
  ('Q3928360', 'RPM Racing est un jeu vidéo de course développé par Silicon & Synapse et édité par Interplay Entertainment en 1991 sur Super Nintendo. C’est un remake du jeu Racing Destruction Set développé par Electronic Arts et publié en 1985 sur Commodore 64. D’après ses développeurs, RPM Racing est le premier jeu développé aux États-Unis pour la Super Nintendo.', 'https://fr.wikipedia.org/wiki/RPM_Racing'),
  ('Q3744718', 'Fighter''s History est un jeu vidéo de combat en 2D de la série éponyme, développé et édité par Data East en 1993 sur borne d''arcade et en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Fighter%27s_History'),
  ('Q865277', 'Hong Kong 97 est un jeu vidéo de tir développé par Kowloon Kurosawa (sous le faux nom de « Happysoft ») sorti en 1995 sur Super Famicom et uniquement au Japon.

Ce jeu ne bénéficie pas de la licence Nintendo et est considéré comme de piètre qualité. Pour cette raison, il fait l''objet d''un culte particulier auprès de certains fans au Japon et à Taïwan. Luke Plunkett de Kotaku décrit le jeu comme « raciste, violent et fou ».', 'https://fr.wikipedia.org/wiki/Hong_Kong_97'),
  ('Q863419', 'Romancing SaGa 2 est un jeu vidéo de rôle sur Super Famicom développé par Square sorti au Japon en décembre 1993. Il est le cinquième épisode de la série de jeux SaGa et remporte lui aussi un grand succès, se vendant à 1,49 million d''exemplaires, dont 1,3 million au Japon.

Un remake intitulé Romancing SaGa 2: Revenge of the Seven est sorti le 24 octobre 2024 sur Nintendo Switch, PlayStation 4, PlayStation 5 et Windows, sur Nintendo Switch 2 le 31 juillet 2025 et enfin sur Xbox Series le 25 septembre 2025. Contrairement à l''original, ce remake bénéficie d''une traduction en français. Le remake rencontre aussi un succès important avec plus d''un million de ventes, et confirme la volonté de Square-Enix de se lancer dans une vague de remakes de sa licence.', 'https://fr.wikipedia.org/wiki/Romancing_SaGa_2'),
  ('Q3782393', 'Hagane: The Final Conflict est un jeu vidéo d''action de type beat them all, développé par CAProductions, et édité par Hudson Soft en novembre 1994 au Japon, suivi de l''Amérique du Nord et de l''Europe en 1995 sur Super Nintendo. Hagane est connu pour son excellente réalisation et sa grande difficulté.', 'https://fr.wikipedia.org/wiki/Hagane:_The_Final_Conflict'),
  ('Q846203', 'Super R-Type est un jeu vidéo du genre shoot them up sorti sur Super Nintendo en mai 1992 en France. Développé par le studio Irem, c''est un des cinq premiers jeux au lancement de la console lors de sa sortie en France.', 'https://fr.wikipedia.org/wiki/Super_R-Type'),
  ('Q890852', 'The Adventures of Batman and Robin est un beat them all développé par Clockwork Tortoise et édité par Sega, sorti sur Mega Drive en 1994. Le jeu est basé sur la série animée Batman, la série animée.

Le jeu est également sorti sur Super Nintendo par Konami ainsi que sur Game Gear par Sega et développé par Novotrade en 1995. The Adventures of Batman and Robin est orienté jeu de plate-forme, le joueur incarne Batman et doit sauver Robin qui a été enlevé par le Joker. Avant d''affronter votre ennemi juré, celui-ci va mettre sur votre route plusieurs méchants connus de la série animée comme le Chapelier Fou, Mr Freeze, l''Épouvantail et Harley Quinn.', 'https://fr.wikipedia.org/wiki/The_Adventures_of_Batman_and_Robin_(jeu_vid%C3%A9o)'),
  ('Q880945', 'Blackhawk (Blackthorne en Amérique du Nord) est un jeu vidéo d’action et de plates-formes, d’un style similaire aux jeux 2D de la série Prince of Persia et à Flashback.

Le jeu a été développé par Blizzard Entertainment et édité par Interplay Entertainment. Il est d’abord sorti en 1994 sur Super Nintendo et sur PC sous MS-DOS, puis, avec des meilleurs graphismes et une palette de couleurs améliorée, sur Sega 32X en 1995 et macOS en 1996. Une version Game Boy Advance est sortie en 2003, dans la collection Blizzard Classic Arcade où on peut aussi trouver, notamment, The Lost Vikings.', 'https://fr.wikipedia.org/wiki/Blackhawk'),
  ('Q906895', 'Prince of Persia 2: The Shadow and the Flame (en français: Prince de Perse 2: L''Ombre et la Flamme) est un jeu vidéo d''action/plate-forme développé par Brøderbund et sorti en 1993 pour DOS et Macintosh. Le jeu est porté sur Super Nintendo par Titus Software en 1996.

L''histoire fait directement suite au premier Prince of Persia développé par Jordan Mechner et sorti en 1989. Après onze jours de bonheur avec la princesse, le prince est chassé du palais par un sosie qui prend sa place. Au cours de ses aventures dans des terres lointaines, il en apprendra plus sur ses origines, puis cherchera à venger ses parents et retrouver son épouse. Une fois de plus, Jordan Mechner mise la réussite de son jeu dans le scénario, inspiré des contes des Mille et Une Nuits. Le jeu est de bonne qualité: musique inspirée, animation fluide, graphismes et environnements détaillés.', 'https://fr.wikipedia.org/wiki/Prince_of_Persia_2:_The_Shadow_and_the_Flame'),
  ('Q3930130', 'Ranma ½: Chōnai Gekitōhen est un jeu de combat édité par Masaya Games le 27 mars 1992 au Japon sur Super Famicom.', 'https://fr.wikipedia.org/wiki/Ranma_%C2%BD:_Ch%C5%8Dnai_Gekit%C5%8Dhen'),
  ('Q3930132', 'Ranma ½: Hard Battle, est un jeu de combat en 2-D développé par Atelier Double et édité par Masaya au Japon exclusivement sur Super Nintendo. Le jeu est édité par Ocean Software en Europe et intitulé tout simplement Ranma ½. Il s''agit du second épisode d''une trilogie de jeu de combat de la série Ranma ½ sorti sur Super Nintendo.

Ranma ½: Hard Battle dispose de trois modes de jeu, incluant un mode histoire, un mode duel et un mode tournoi permettant deux équipes de 5 personnages s''affronter. Le jeu comporte 10 personnages (12 en comptabilisant les formes) avec un scénario différent pour chaque personnage.', 'https://fr.wikipedia.org/wiki/Ranma_%C2%BD:_Hard_Battle'),
  ('Q936565', 'ACME Animation Factory est un jeu vidéo de genre éducatif édité par Sunsoft et basé sur l''univers des Looney Tunes. Il est sorti sur Super NES en 1994 et permet de créer ses propres cartoons mettant en scène les personnages Looney Tunes. Il est compatible avec la souris Super NES.', 'https://fr.wikipedia.org/wiki/ACME_Animation_Factory'),
  ('Q939597', 'Mega lo Mania est un jeu vidéo de stratégie temps réel développé par Sensible Software et édité par Image Works sur Amiga et Atari ST en 1991. Le jeu a été adapté sur DOS, FM Towns, Mega Drive et Super Nintendo. Il est sorti sous le nom de Tyrants: Fight Through Time en Amerique du Nord et Mega-Lo-Mania: Jikū Daisenryaku au Japon.', 'https://fr.wikipedia.org/wiki/Mega_lo_Mania'),
  ('Q4006784', 'Utopia: The Creation of a Nation est un jeu vidéo de gestion de type city-builder développé par Celestial Software et initialement publié sur PC et Amiga par Gremlin Interactive en 1991. Le jeu a également été publié sur Atari ST par Jaleco et sur SNES par Epic/Sony Records. Le jeu se déroule dans un univers de science-fiction dans lequel le joueur doit coloniser différentes planètes puis développer ses colonies afin d’améliorer le niveau de vie de ses habitants. Sur chaque planète, le joueur est en compétition avec des races extraterrestres tentant elles aussi de développer leurs colonies.

Le jeu inclut dix scénarios correspondant chacun à une planète. Sur chacune d’entre elles, le joueur est en compétition avec une nouvelle race extraterrestre. Le jeu a fait l’objet d’une extension intitulée Utopia: The new worlds, également publié par Gremlin Interactive, qui inclut dix missions supplémentaires.', 'https://fr.wikipedia.org/wiki/Utopia:_The_Creation_of_a_Nation'),
  ('Q3977633', 'Super Turrican 2 est un jeu vidéo de type run and gun développé par Factor 5 et édité par Ocean Software, sorti en 1995 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Turrican_2'),
  ('Q4035116', 'BioMetal est un jeu vidéo d''action de type shoot them up à défilement horizontal, développé et édité par Athena Co. au Japon, il est et édité par Activision en Amérique du Nord. Il est sorti au Japon le 19 mars 1993, suivi de l''Amérique du Nord et l''Europe la même année sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/BioMetal'),
  ('Q4048363', 'Robotrek, ou Slap Stick au Japon, est un jeu vidéo de rôle développé par Quintet et édité par Enix en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Robotrek'),
  ('Q4043876', 'Battletech (MechWarrior en Amérique du Nord) est un jeu vidéo d''action sorti en 1993 sur Super Nintendo. Le jeu a été développé par Beam Software et édité par Activision.', 'https://fr.wikipedia.org/wiki/Battletech_(jeu_vid%C3%A9o)'),
  ('Q4051546', 'Todd McFarlane''s Spawn: The Video Game est un jeu vidéo de type beat them all mettant en scène le personnage Spawn de l''auteur de bandes dessinées, Todd McFarlane. Il est développé par Ukiyotei et édité par Acclaim Entertainment sur Super Nintendo en 1995.', 'https://fr.wikipedia.org/wiki/Todd_McFarlane%27s_Spawn:_The_Video_Game'),
  ('Q4051081', 'The Flintstones: The Treasure of Sierra Madrock est un jeu vidéo de plates-formes édité par Taito en 1994 sur Super Nintendo. Il s''agit d''une adaptation de la série d''animation La Famille Pierrafeu.', 'https://fr.wikipedia.org/wiki/The_Flintstones:_The_Treasure_of_Sierra_Madrock'),
  ('Q4051519', 'Tiny Toon Adventures: Buster Busts Loose! est un jeu vidéo d''action/plates-formes en 2D, développé et édité par Konami. Il est sorti au Japon sur Super Famicom le 18 décembre 1992, suivi de l''Amérique du Nord le 16 août 1993 et de l''Europe en 1993. Il est fondé sur le dessin animé Les Tiny Toons.', 'https://fr.wikipedia.org/wiki/Tiny_Toon_Adventures:_Buster_Busts_Loose!'),
  ('Q4048413', 'Romancing SaGa 3 est un jeu vidéo de rôle sur Super Famicom développé par Square sorti au Japon en novembre 1995. Il est le sixième épisode de la série de jeux SaGa (le dernier sur Super Famicom) et remporte un grand succès au Japon, se vendant à 1,3 million d''exemplaires. Un remake 3D complet du jeu est prévu pour 2027, qui est traduit en français contrairement au jeu original.', 'https://fr.wikipedia.org/wiki/Romancing_SaGa_3'),
  ('Q4353245', 'Alcahest est un jeu vidéo de type action-RPG développé par HAL Laboratory et édité par Squaresoft le 17 décembre 1993 au Japon sur Super Famicom. Son système de jeu est similaire à la série The Legend of Zelda et au jeu Secret of Mana.', 'https://fr.wikipedia.org/wiki/Alcahest'),
  ('Q4669736', 'Ace o Nerae! est un jeu vidéo de tennis développé et édité par Telenet Japan en 1993 sur Super Famicom.

Il est une adaptation de l''anime et manga du même nom (Jeu, set et match ! en français).

Ace o Nerae! est l''un des premiers jeux qui a, non sans restreindre la jouabilité, expérimenté les effets du mode 7 (simulant la trois dimensions).', 'https://fr.wikipedia.org/wiki/Ace_o_Nerae!_(jeu_vid%C3%A9o)'),
  ('Q4384620', 'Mega Man Soccer (Rockman''s Soccer au Japon) est un jeu vidéo de football développé par Sun L et édité par Capcom en 1994 sur Super Nintendo. C''est un jeu dérivé de la série Mega Man.', 'https://fr.wikipedia.org/wiki/Mega_Man_Soccer'),
  ('Q4356532', 'Xak: The Art of Visual Stage est un jeu vidéo de type action-RPG développé et édité par Micro Cabin, sorti en 1989 sur Windows, PC-Engine, Super Nintendo et téléphone mobile.', 'https://fr.wikipedia.org/wiki/Xak:_The_Art_of_Visual_Stage'),
  ('Q4707360', 'The Legend of the Mystical Ninja est un jeu vidéo d''action-aventure développé et édité par Konami en 1991 sur Super Nintendo. Il fait partie de la série Ganbare Goemon. En Europe, le jeu n''a connu qu''une localisation anglaise et allemande.', 'https://fr.wikipedia.org/wiki/The_Legend_of_the_Mystical_Ninja'),
  ('Q4677160', 'Joe and Mac 3: Lost in the Tropics, ou bien Joe and Mac 2: Lost in the Tropics en Amérique du Nord, est un jeu vidéo de plates-formes développé et édité par Data East en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Joe_and_Mac_3:_Lost_in_the_Tropics'),
  ('Q4920000', 'BlaZeon: The Bio-Cyborg Challenge ou simplement BlaZeon

est un jeu vidéo d''action de type shoot ''em up développé par A.I et édité par Atlus sur borne d''arcade et sur la console Super Nintendo. Il est sorti sur Super Nintendo au Japon le 24 juillet 1992, suivi de l''Amérique du Nord.', 'https://fr.wikipedia.org/wiki/BlaZeon'),
  ('Q4994671', 'Equinox, connu au Japon sous le nom de Solstice II, est un jeu vidéo d''aventure/réflexion développé par Software Creation Ltd. et édité par Sony Imagesoft en 1993 sur Super Nintendo. Il s''agit de la suite du jeu Solstice sorti en 1989 sur NES.', 'https://fr.wikipedia.org/wiki/Equinox_(jeu_vid%C3%A9o)'),
  ('Q4955774', 'Brain Lord est un jeu vidéo de type action-RPG développé par Produce! et édité par Enix sur Super Nintendo en 1994.', 'https://fr.wikipedia.org/wiki/Brain_Lord');

insert into import_summary (wikidata_id, summary, source) values
  ('Q5129819', 'ClayFighter 2: Judgment Clay est un jeu de combat sorti exclusivement sur Super Nintendo en 1995. Le jeu est développé et édité par Interplay Entertainment et est la suite de ClayFighter. Le jeu est sorti en France le 23 mai 1995. Le jeu était également annoncé dans certaines revues nord-américaines pour une sortie sur 32X, mais cette version a été annulée. Le titre du jeu est une référence au film Terminator 2: Judgment Day.', 'https://fr.wikipedia.org/wiki/ClayFighter_2:_Judgment_Clay'),
  ('Q5130099', 'Claymates est un jeu de plates-formes de type 2D, développé par Visual Concepts et Danger Productions, publié par Interplay. Il est sorti en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Claymates'),
  ('Q5104837', 'Choplifter III est un jeu vidéo de type shoot ''em up développé par Beam Software et édité par Extreme Entertainment, sorti en 1994 sur Super Nintendo, Game Boy et Game Gear.', 'https://fr.wikipedia.org/wiki/Choplifter_III'),
  ('Q5275469', 'Dig and Spike Volleyball - aussi connu sous le nom de Volleyball Twin au Japon - est un jeu vidéo de Volleyball développé par TOSE. Le joueur a le choix entre jouer du volleyball indoor et du Beach-volley féminin.', 'https://fr.wikipedia.org/wiki/Dig_and_Spike_Volleyball'),
  ('Q5278473', 'DinoCity, connu au Japon sous le titre Dinowars Kyōryū Oukoku e no Daibouken est un jeu vidéo de plates-formes en 2D à thème préhistorique et de science-fiction. Il s''agit d''une adaptation du film télévisé Adventures in Dinosaur City. Il a été développé et édité par Irem en 1992 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/DinoCity'),
  ('Q5280947', 'Dirt Trax FX est un jeu vidéo de course développé par Sculptured Software et édité par Acclaim Entertainment, sorti en 1995 sur Super Nintendo. Il utilise la puce Super FX.', 'https://fr.wikipedia.org/wiki/Dirt_Trax_FX'),
  ('Q5305302', 'Dragon View, ou Super Drakkhen au Japon, est un jeu vidéo de type Action-RPG développé par Kemco et sorti en 1994 au Japon et en Amérique du Nord sur Super Nintendo. Il s''agit d''une suite de Drakkhen, dont il ne reprend que la carte du monde en 3D.', 'https://fr.wikipedia.org/wiki/Dragon_View'),
  ('Q5310171', 'Dual Orb II est un jeu vidéo de rôle développé par Nippon Ichi Software et édité par I''Max, sorti en 1994 sur Super Famicom. Il s''agit de la suite de Dual Orb: Seireiju Densetsu.

Il s''agit du premier jeu auquel Hiroyuki Kotani, connu pour la série Patapon, a participé.', 'https://fr.wikipedia.org/wiki/Dual_Orb_II'),
  ('Q5340147', 'Edo no Kiba (Edono 牙) est un jeu vidéo de type beat them all en 2D à thème cyberpunk. Le jeu a été développé par Riot Co. et édité par Micro World le 12 mars 1993 sur Super Famicom, uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Edo_no_Kiba'),
  ('Q5463439', 'Flying Hero: Bugyuru no Daibōken est un jeu vidéo de type shoot ''em up à scrolling vertical, développé par Sting Entertainment et édité par SOFEL sorti uniquement au Japon le 18 décembre 1992 sur Super Famicom.

Les graphismes de Flying Hero s''orientent vers un style dessin animé avec des couleurs vives qui se dégagent des niveaux, contrairement à la plupart des jeux de shoot ''em up de l''époque (Gradius, R-Type). Le bestiaire est cohérent avec l''aspect artistique du jeu, les ennemis se constituent de singes volant, de chauves-souris, de corbeaux, d''ours ou encore de lions. Les objets à récupérer dans les niveaux renforcent également le style dessin animé du jeu, ils sont représentés par des petits gâteaux à la crème et octroient un bonus pour les armes à feu, permettant de multiplier le nombre de tirs par deux ou par trois selon le nombre d''objets récupéré. Les tirs sont dirigés en face du personnage en pressant la touche « B » de la manette, des tirs en diagonal peuvent aussi s''exécuter en pressant la touche « B » plus les gâchettes (« L+B » pour les tirs en diagonal vers la gauche et « R+B » vers la droite). Le joueur dispose de trois vies ainsi que de trois continues pour terminer le jeu. Le joueur peut ajuster sa vitesse de jeu en pleine partie à l''aide du bouton « Select », la vitesse se décline en trois niveaux. Les effets du Mode 7 sont souvent utilisés sur les boss, qui sont présents sur chaque niveau du jeu.', 'https://fr.wikipedia.org/wiki/Flying_Hero'),
  ('Q5508155', 'Full Throttle: All-American Racing, connu au Japon sous le titre Full Power, est un jeu vidéo de course sorti sur la Super Nintendo.', 'https://fr.wikipedia.org/wiki/Full_Throttle:_All-American_Racing'),
  ('Q5508636', 'Fun ''n'' Games est un jeu vidéo éducatif sorti en 1993 et fonctionne sur Mega Drive et Super Nintendo. Le jeu a été développé par Leland Interactive Media et édité par Tradewest.', 'https://fr.wikipedia.org/wiki/Fun_%27n%27_Games'),
  ('Q5618284', 'GunForce: Battle Fire Engulfed Terror Island est un jeu vidéo de type run and gun à défilement horizontale développé et édité par Irem sur borne d''arcade en 1991, puis porté en novembre 1992 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/GunForce'),
  ('Q5620510', 'Gourmet Sentai Barayarō est un jeu vidéo d''action Beat them all à thème mélangeant cyberpunk et de gastronomie. Le jeu a été développé par Winds Co. et édité par Virgin Entertainment. Il est sorti uniquement au Japon le 29 septembre 1995 sur Super Famicom.', 'https://fr.wikipedia.org/wiki/Gourmet_Sentai_Barayar%C5%8D'),
  ('Q5968677', 'Fighting Spirit: Tuff E Nuff, ou simplement Tuff E Nuff (argot anglais de Tough Enough, signifiant « Suffisamment dur »), est un jeu vidéo de combat un contre un en 2D à thème post-cataclysmique. Le jeu a été développé et édité par Jaleco sur Super Nintendo. Il est sorti le 26 mars 1993 au Japon sous le titre Dead Dance, suivi de l''Europe et de l''Amérique du Nord (sous le titre complet Hey Punk! Are you Tuff E Nuff?: Master the moves to master me!).', 'https://fr.wikipedia.org/wiki/Fighting_Spirit:_Tuff_E_Nuff'),
  ('Q5957614', 'Hyper Iria est un jeu vidéo de type run and gun adapté du dessin animé japonais, Iria - Zeiram the Animation. Il est développé par TamTam et édité par Banpresto en 1995 sur Super Famicom, uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Hyper_Iria'),
  ('Q6038377', 'Inspector Gadget est un jeu vidéo de plates-formes et d''action développé par AIM et édité par Hudson Soft en décembre 1993 sur Super Nintendo. C''est une adaptation de la série animée Inspecteur Gadget.', 'https://fr.wikipedia.org/wiki/Inspector_Gadget_(jeu_vid%C3%A9o)'),
  ('Q6138822', 'Pop''n TwinBee: Rainbow Bell Adventures est un jeu de plates-formes développé par Konami sur Super Nintendo, sorti au Japon le 7 janvier 1994 et en Europe la même année. Le jeu est sorti sur la console virtuelle de la Wii en 2014. Contrairement au reste de la série TwinBee, il ne s''agit pas d''un shoot ''em up.', 'https://fr.wikipedia.org/wiki/Pop%27n_TwinBee:_Rainbow_Bell_Adventures'),
  ('Q6120028', 'Sonic Blast Man est un jeu vidéo développé et édité par Taito. La première version sortie en 1990 sur borne d''arcade se contrôle à l''aide d''un punching ball. L''autre version est sortie en 1992 sur Super Nintendo, et est de type beat them all.', 'https://fr.wikipedia.org/wiki/Sonic_Blast_Man'),
  ('Q6143748', 'Lufia, ou Lufia II: Rise of the Sinistrals en Amérique du Nord, ou Estpolis Denki II au Japon, est un jeu vidéo de rôle développé par Neverland Co., Ltd. et édité par Taito en 1995 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Lufia_II:_Rise_of_the_Sinistrals'),
  ('Q6146317', 'Treasure Hunter G est un jeu vidéo de type Tactical RPG développé par Sting et édité par Squaresoft en 1996 sur Super Nintendo, uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Treasure_Hunter_G'),
  ('Q6470551', 'Lady Stalker: Challenge from the Past est un jeu vidéo de type action-RPG développé par Climax Entertainment et édité par Taito sur Super Famicom en 1995. Le titre est une suite à Landstalker. Lady Stalker est le seul jeu lié à Landstalker à n''avoir été publié en dehors du Japon, bien que le personnage principal apparaisse dans le titre Time Stalkers sorti sur Dreamcast.

Un jeu intitulé Lady Stalker est sorti sur téléphone mobile uniquement au Japon en 2006. Il n''est pas un remake du titre original Lady Stalker.', 'https://fr.wikipedia.org/wiki/Lady_Stalker:_Challenge_from_the_Past'),
  ('Q6411248', 'King Arthur and the Knights of Justice est un jeu vidéo d''action-aventure développé par Manley & Associates et édité par Enix, sorti en 1995 sur Super Nintendo.

Le jeu est basé sur la série animée Le Roi Arthur et les Chevaliers de Justice.', 'https://fr.wikipedia.org/wiki/King_Arthur_and_the_Knights_of_Justice_(jeu_vid%C3%A9o)'),
  ('Q6675669', 'Looney Tunes Basketball, ou bien Looney Tunes B-Ball en Amérique du Nord, est un jeu vidéo de basket-ball mettant en scène les personnages des Looney Tunes. Il est édité par Sunsoft sur Super Nintendo en 1995.', 'https://fr.wikipedia.org/wiki/Looney_Tunes_Basketball'),
  ('Q6798595', 'Mazinger Z est un jeu d''action Beat them all développé par Winkysoft et édité par Bandai. Il est sorti uniquement au Japon le 25 juin 1993. Il s''agit d''une adaptation de l''anime et manga éponyme Mazinger Z de Go Nagai.', 'https://fr.wikipedia.org/wiki/Mazinger_Z_(jeu_vid%C3%A9o)'),
  ('Q6804434', 'MechWarrior 3050 (ou BattleTech: A Game of Armored Combat) est un jeu vidéo de simulation de mecha développé par Malibu Interactive et sorti en 1994 sur Mega Drive et 1995 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/MechWarrior_3050'),
  ('Q6952900', 'World League Basketball (NCAA Basketball en Amérique du Nord, Super Dunk Shot au Japon) est un jeu vidéo de basket-ball sorti en 1992 sur Super Nintendo. Le jeu a été développé par Sculptured Software.', 'https://fr.wikipedia.org/wiki/World_League_Basketball_(jeu_vid%C3%A9o,_1992)'),
  ('Q6951121', 'Mōryō Senki Madara 2 est un jeu vidéo de rôle à thème de mythologie japonaise. Le jeu a été développé et édité par Konami pour la SNES. Il est sorti uniquement au Japon le 16 juillet 1993. Il s''agit du deuxième opus de la série Mōryō Senki Madara tiré du manga Madara (1987, 2008 pour la traduction française) de Eiji Ōtsuka et l''anime (1991) qui a fait suite.', 'https://fr.wikipedia.org/wiki/M%C5%8Dry%C5%8D_Senki_Madara_2'),
  ('Q7061794', 'Nosferatu est un jeu vidéo de plates-formes développé et édité par SETA Corporation. Il est sorti en 1994 au Japon et en 1995 en Amérique du Nord sur Super Nintendo. Il s''inscrit dans la catégorie des jeux de plates-formes cinématographiques, semblable aux jeux Prince of Persia, Flashback ou encore Blackthorne.', 'https://fr.wikipedia.org/wiki/Nosferatu_(jeu_vid%C3%A9o)'),
  ('Q7038956', 'The Ninja Warriors: The New Generation, ou The Ninja Warriors Again au Japon, est un jeu vidéo de type beat them all développé par Natsume et édité par Taito en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/The_Ninja_Warriors:_The_New_Generation'),
  ('Q7001764', 'Neugier: Umi to Kaze no Kodō (The Journey Home en anglais) est un jeu vidéo de type action-RPG en 2D isométrique, développé par Wolf Team et édité par Telenet Japan. Il est sorti uniquement au Japon sur Super Famicom le 26 mars 1993. Neugier est un mot allemand signifiant « curiosité ».', 'https://fr.wikipedia.org/wiki/Neugier:_Umi_to_Kaze_no_Kod%C5%8D'),
  ('Q7121840', 'Pac-In-Time est un jeu vidéo d''action/plates-formes en 2D développé par Atreid Concept et édité par Namco. Il est sorti en Europe sur Super Nintendo en décembre 1994, puis en janvier 1995 au Japon sur Super Famicom, ainsi qu''en Amérique du Nord. Il fait partie de la série Pac-Man.', 'https://fr.wikipedia.org/wiki/Pac-In-Time'),
  ('Q7097243', 'Operation Logic Bomb: The Ultimate Search and Destroy, plus connu au Japon sous le nom Ikari no Yōsai, est un jeu vidéo de type run and gun futuriste en 2D isométrique développé et édité par Jaleco en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Operation_Logic_Bomb'),
  ('Q7105842', 'Oscar est un jeu vidéo de plates-formes édité par Flair Software en 1993. Le jeu a été porté sur Super Nintendo par Titus Software en 1996.

Il a été suivi de jeux sortis sur le DSiWare de Nintendo.', 'https://fr.wikipedia.org/wiki/Oscar_(jeu_vid%C3%A9o)'),
  ('Q7146181', 'Harvest Moon est un jeu vidéo de type simulation de vie / RPG. Il est sorti sur Super Nintendo en 1996 au Japon.

Le jeu est également sorti aux États-Unis en 1997 mais en très petite quantité, ce qui en fait un des jeux Super Nintendo américain les plus recherchés, avec une cote moyenne d''environ 3 284 $ neuf.

La version PAL est sortie le 29 janvier 1998, c''est l''un des tout derniers jeux Super Nintendo en Europe. La version PAL est sortie en Allemagne, traduite en allemand, ainsi qu''en Australie et en très petite quantité en France mais avec des textes écran en anglais.', 'https://fr.wikipedia.org/wiki/Harvest_Moon_(jeu_vid%C3%A9o)'),
  ('Q7206480', 'Pocky & Rocky 2, publié au Japon sous le titre de Kiki Kaikai: Tsukiyo Soushi, est un jeu vidéo de shoot ''em up développé et publié par Natsume sur Super Famicom au Japon le 17 juin 1994. En Europe, Pocky & Rocky 2 est édité par Ocean Software.', 'https://fr.wikipedia.org/wiki/Pocky_and_Rocky_2'),
  ('Q7230177', 'Porky Pig''s Haunted Holiday est un jeu vidéo de plates-formes développé par le studio Phoenix Interactive Entertainment et édité par Acclaim Entertainment en 1995 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Porky_Pig%27s_Haunted_Holiday'),
  ('Q7246756', 'Pro Quarterback Football est un jeu vidéo de football américain sorti en 1992 et fonctionne sur Mega Drive et Super Nintendo. Le jeu a été développé par Tradewest Sports puis édité par Sega.', 'https://fr.wikipedia.org/wiki/Pro_Quarterback_Football'),
  ('Q7301326', 'Realm est un jeu d''action plates-formes de type run and gun en 2D, à thème de science fiction. Le jeu a été développé par Flair Software et édité par Titus Software pour la Super Nintendo. Il est sorti en Amérique du Nord en décembre 1996, suivi de l''Europe en 1997.', 'https://fr.wikipedia.org/wiki/Realm'),
  ('Q7312804', 'Rendering Ranger: R2 est un jeu vidéo d''action alternant phase de type run and gun et phase de shoot them up. Il est développé par Rainbow Arts et édité par la société Virgin Interactive sur Super Famicom en 1995.

Le jeu a failli ne jamais sortir suite à son l''annulation par l''éditeur originel, Softgold, qui a déclaré que le titre ne serait pas rentable en 1995. Finalement, une filiale de Virgin Interactive a publié 5 000 exemplaires uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Rendering_Ranger:_R2'),
  ('Q7336963', 'Rival Turf!, ou Rushing Beat au Japon, est un jeu vidéo de type beat them all en 2D à défilement horizontal développé et édité par Jaleco en 1992 sur Super Nintendo. Il s''agit du premier opus de la série Rushing Beat de Jaleco.', 'https://fr.wikipedia.org/wiki/Rival_Turf!'),
  ('Q7392106', 'SOS est un jeu vidéo d''aventure et de survie développé par Human Entertainment et lancé en 1993 sur Super Nintendo par Vic Tokai. Une suite au jeu a été lancée au Japon sur PlayStation sous le nom de Septentrion: Out of the Blue.', 'https://fr.wikipedia.org/wiki/SOS_(jeu_vid%C3%A9o,_1993)'),
  ('Q7356001', 'Rocky Rodent (sorti au Japon sous le nom Nitro Punks: Might Heads est un jeu vidéo d''action/plates-formes en 2D, développé et édité par Irem. Il est sorti sur Super Famicom le 30 juillet 1993 au Japon, et la même année en Amérique du Nord.', 'https://fr.wikipedia.org/wiki/Rocky_Rodent'),
  ('Q7379529', 'Run Saber est un jeu vidéo d''action-plates-formes à défilement horizontal, développé par Horisoft et édité par Atlus sur Super Nintendo en 1993 en Amérique du Nord et en Europe. Il s''agit d''un jeu de ninja cybernétique qui a une forte ressemblance avec le jeu Strider.', 'https://fr.wikipedia.org/wiki/Run_Saber'),
  ('Q7444183', 'Tecmo Secret of the Stars: A Fantasy (Aqutallion au Japon), est un jeu vidéo de rôle au tour par tour en vue aérienne, se déroulant dans un univers fantasy et steampunk. Le jeu a été développé et édité par Tecmo pour la Super Nintendo. Il est sorti au Japon le 5 novembre 1993, suivi de l''Amérique du Nord en juillet 1995.', 'https://fr.wikipedia.org/wiki/Tecmo_Secret_of_the_Stars:_A_Fantasy'),
  ('Q7557878', 'Solid Runner est un jeu vidéo de rôle au tour par tour en vue aérienne dans un univers cyberpunk et mecha. Le jeu a été développé par Sting Entertainment et édité par ASCII, le 28 mars 1997 uniquement au Japon sur SNES.', 'https://fr.wikipedia.org/wiki/Solid_Runner'),
  ('Q7577489', 'Spindizzy Worlds est un jeu vidéo d''action développé par Electric Dreams et édité par Activision, sorti en 1990 sur Amiga, Atari ST et Super Nintendo. C''est la suite de Spindizzy.', 'https://fr.wikipedia.org/wiki/Spindizzy_Worlds'),
  ('Q7642250', 'Super Chinese est une série de jeux vidéo de type aventure et action produite par Culture Brain. L''histoire de la série raconte les aventures de Jack et Ryu, deux ninjas qui protègent le royaume de Chinaland, sorte de Chine futuriste.', 'https://fr.wikipedia.org/wiki/Super_Chinese'),
  ('Q7642257', 'Super Chinese est une série de jeux vidéo de type aventure et action produite par Culture Brain. L''histoire de la série raconte les aventures de Jack et Ryu, deux ninjas qui protègent le royaume de Chinaland, sorte de Chine futuriste.', 'https://fr.wikipedia.org/wiki/Super_Chinese'),
  ('Q7642875', 'Super Troll Islands est un jeu de plates-formes puzzle en 2D, basé sur les Troll dolls. Le jeu a été développé par Millennium Interactive et édité par Kemco au Japon, et ASC Games pour l''Amérique du Nord et l''Europe. Il est sorti en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Troll_Islands'),
  ('Q7642888', 'Super Turrican est un jeu vidéo de type run and gun développé par Factor 5 et sorti en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Super_Turrican_(Super_Nintendo)'),
  ('Q7798922', 'SimCity est un jeu vidéo de gestion de type city-builder développé par Maxis en 1989. Imaginé par Will Wright, le concept de jeu consiste à construire et à gérer une ville entière. Le jeu compte parmi les précurseurs du genre et constitue le premier épisode de la série SimCity.

Le jeu est sorti en 1989 sur Amiga, Amstrad CPC, Atari ST, Commodore 64, DOS et Mac OS, en 1990 sur ZX Spectrum et enfin en 1991 sur Amiga CDTV, Super Nintendo et Windows 3.x. Il rencontra un grand succès, se vendant à 50 000 exemplaires l''année de sa sortie en Europe, et encore plus en Amérique du Nord (500 000 exemplaires sur ordinateurs fin 1992, et 830 000 de plus jusqu''à la fin de la décennie).', 'https://fr.wikipedia.org/wiki/SimCity_(1989)'),
  ('Q7770896', 'The Twisted Tales of Spike McFan ou Chou Makai Taisen: Dorabocchan est un jeu vidéo de rôle de type action-RPG. Le jeu a été développé par Red Entertainment et édité par Naxat Soft et Bullet Proof Software. Le jeu est sorti sur Super Nintendo le 19 mars 1993 au Japon, suivi de l'' Amérique du Nord en juin 1994. Il fait partie de la série Dorabocchan.', 'https://fr.wikipedia.org/wiki/The_Twisted_Tales_of_Spike_McFang'),
  ('Q7819707', 'Val d''Isère Championship (Tommy Moe''s Winter Extreme: Skiing and Snowboarding en Amérique du Nord, Ski Paradise with Snowboard au Japon) est un jeu vidéo de ski et snowboard développé par Loriciel et édité par Mindscape, sorti en 1994 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Val_d%27Is%C3%A8re_Championship'),
  ('Q7880191', 'Ultimate Fighter, ou Hiryū no Ken S: Hyper Version au Japon, est un jeu vidéo de combat en 2D mélangeant des séquences de type beat them all et des combats en un-contre-un, développé et édité par Culture Brain en 1992 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Ultimate_Fighter'),
  ('Q8028769', 'Wizardry V: Heart of the Maelstrom est un jeu vidéo de type dungeon crawler développé et publié par Sir-Tech en 1988 sur Commodore 64, Apple II et PC booter puis porté sur SNES et FM Towns. Le jeu est le cinquième opus de la série Wizardry. À sa sortie, le jeu est plutôt bien reçu par la presse spécialisée.', 'https://fr.wikipedia.org/wiki/Wizardry_V:_Heart_of_the_Maelstrom'),
  ('Q8028768', 'Wizardry VI: Bane of the Cosmic Forge est un jeu vidéo de type dungeon crawler développé et publié par Sir-Tech en 1990 sur Amiga et DOS puis en 1995 sur SNES. Le jeu est le sixième opus de la série Wizardry et le premier de la trilogie du Dark Savant qui inclut également Wizardry VII: Crusaders of the Dark Savant et Wizardry 8.', 'https://fr.wikipedia.org/wiki/Wizardry_VI:_Bane_of_the_Cosmic_Forge'),
  ('Q8042912', 'Whirlo (connu au Japon sous le nom Xandra no Daibōken: Valkyrie to no Deai est un jeu vidéo d''action-plates-formes développé et édité par Namco. Il est sorti au Japon le 23 juillet 1992 sur Super Famicom, puis en Europe sur Super Nintendo. Ce jeu fait partie de la série Valkyrie de Namco. Il met en avant un des personnages secondaires de la série, Whirlo (Krino Xandra).', 'https://fr.wikipedia.org/wiki/Whirlo'),
  ('Q8041457', 'X-Kaliber 2097, ou Sword Maniac au Japon, est un jeu vidéo d''action-plates-formes 2D, développé par Fupac, Winds, et Opus. Il est sorti sur Super Famicom le 11 février 1994 au Japon, suivi de l''Europe et l''Amérique du Nord.', 'https://fr.wikipedia.org/wiki/X-Kaliber_2097'),
  ('Q8035815', 'World Heroes est un jeu vidéo de combat en 2D développé par ADK et édité par SNK en 1992 sur borne d''arcade Neo-Geo MVS et sur console Neo-Geo AES, puis en 1995 sur Neo-Geo CD (NGM 053). Le jeu a été porté sur les consoles Mega Drive, Super Nintendo, Saturn, PlayStation 2 et Wii. Les versions console ont été éditées par Sega, Sunsoft, Takara et Hudson Soft. C''est le premier épisode de la série World Heroes, qui est considéré comme la réponse de SNK à la sortie de Street Fighter II de Capcom.', 'https://fr.wikipedia.org/wiki/World_Heroes'),
  ('Q8034500', 'Wordtris est un jeu vidéo de réflexion développé par Realtime Associates et édité par Spectrum HoloByte, sorti en 1991 sur DOS, Mac, Super Nintendo et Game Boy.', 'https://fr.wikipedia.org/wiki/Wordtris'),
  ('Q8031770', 'Wonder Project J: Kikai no Shōnen Pīno est un jeu vidéo de simulation de vie en 2D, inspiré de Pinocchio. Le jeu a été développé par Almanic Co. et édité par Enix. Il est sorti uniquement au Japon le 9 décembre 1994. Le jeu a connu une suite sur Nintendo 64.', 'https://fr.wikipedia.org/wiki/Wonder_Project_J:_Kikai_no_Sh%C5%8Dnen_P%C4%ABno'),
  ('Q8058309', 'Young Merlin est un jeu vidéo de rôle développé par Westwood Studios et publié par Virgin Interactive sur SNES en 1994. Le joueur y incarne le jeune Merlin qui, avec l’aide de la fée Viviane, tente de vaincre le démoniaque Shadow King. Le jeu mélange des éléments d’action et de rôle. À sa sortie, le jeu est plutôt bien reçu par la presse spécialisée. Le magazine SNES N-Force lui attribue par exemple un score de 92 % et le présente comme le nouveau Zelda. De son côté, le magazine Electronic Gaming Monthly lui attribue un score de 76 % et met en avant ses niveaux énormes et la qualité de son système de contrôle et de ses graphismes. Le magazine GamePro fait le même constat mais regrette que son système de jeu manque de complexité et qu’il requière trop souvent de revenir en arrière.', 'https://fr.wikipedia.org/wiki/Young_Merlin'),
  ('Q9299894', 'King Arthur''s World, ou Royal Conquest au Japon, est un jeu vidéo de réflexion développé par Argonaut Games et édité par Jaleco en 1992 au Japon et en 1993 en Occident sur Super Nintendo.

S''inspirant du principe du jeu Lemmings, le but est d''emmener le Roi Arthur au bout du niveau, en se servant de soldats de plusieurs types (artificiers, archers, magiciens, etc.) pour franchir les différents obstacles et affronter les ennemis.

Il inspirera le jeu de stratégie en ligne King Arthur''s Gold, sorti en 2011 sur ordinateur.', 'https://fr.wikipedia.org/wiki/King_Arthur%27s_World'),
  ('Q10353565', 'Prehistorik Man est un jeu vidéo de plates-formes développé et édité par Titus Interactive en 1995 sur Super Nintendo. Une seconde version est développée sur Game Boy. Le jeu est porté sur Game Boy Advance en 2001.', 'https://fr.wikipedia.org/wiki/Prehistorik_Man'),
  ('Q11091967', 'Dragon Slayer: The Legend of Heroes est un jeu vidéo de rôle développé et édité par Falcom en 1989. À l''origine commercialisé sur NEC PC-8801, le jeu a été adapté sur les micro-ordinateurs FM Towns, PC-98, MSX2, X68000 et les consoles PC Engine, Mega Drive et Super Famicom.', 'https://fr.wikipedia.org/wiki/Dragon_Slayer:_The_Legend_of_Heroes'),
  ('Q11242769', 'SD Gundam Gaiden 2: Entaku no Kishi est un jeu vidéo de rôle développé par Bandai, et édité par Yutaka en décembre 1992 sur Super Famicom. C''est une adaptation en jeu vidéo de la série basée sur l''anime Mobile Suit Gundam et notamment Super Deformed Gundam. Il est notamment basé sur l''univers de SD Gundam Gaiden Sieg Zion Hen et c''est le dernier opus d''une série composée de cinq jeux vidéo de rôle.', 'https://fr.wikipedia.org/wiki/SD_Gundam_Gaiden_2:_Entaku_no_Kishi'),
  ('Q11289200', 'Ultra Seven est un jeu vidéo de combat un contre un en 2D à thème de superhéros. Il a été développé par Bec et édité par Bandai uniquement au Japon pour la SNES le 26 mars 1993. Il s''agit d''une adaptation de la série télévisée éponyme, Ultraseven.', 'https://fr.wikipedia.org/wiki/Ultra_Seven_(jeu_vid%C3%A9o)'),
  ('Q11309363', 'Smart Ball, ou Jerry Boy au Japon, est un jeu vidéo de plates-formes développé par Game Freak et System Sacom et édité par Sony. Il est sorti au Japon le 13 septembre 1991 et en Amérique du Nord en 1992 sur Super Nintendo. Une suite, Jelly Boy 2, prévue en 1994, a été annulée.', 'https://fr.wikipedia.org/wiki/Smart_Ball'),
  ('Q11312037', 'Varie est un éditeur et développeur de jeux vidéo japonais fondé en 1986 et disparu en 1997. La société édite et développe des jeux sur Game Boy, Famicom, Super Famicom et Mega Drive.', 'https://fr.wikipedia.org/wiki/Varie'),
  ('Q11319330', 'Tetris Battle Gaiden est un jeu vidéo de puzzle sorti en 1993 sur Super Famicom. Il a été développé et édité par Bullet-Proof Software. Il s''agit d''une variante de Tetris.', 'https://fr.wikipedia.org/wiki/Tetris_Battle_Gaiden'),
  ('Q11322841', 'Doraemon: Nobita to yōsei no kuni est un jeu vidéo de plates-formes-aventure en 2D, avec des éléments de jeu de rôle, dérivé du manga Doraemon. Il a été co-développé par Sakata SAS et Pophouse, et édité par Epoch le 19 février 1993 sur Super Famicom uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Doraemon:_Nobita_to_y%C5%8Dsei_no_kuni'),
  ('Q11332146', 'Phalanx ou Phalanx: The Enforce Fighter A-144 est un jeu d''action de type shoot them up en 2D à thème futuriste. Le jeu a été développé par Zoom Inc. et édité par Kemco. Il est sorti d''abord sur Sharp X68000 au Japon en 1991, puis sur Super Nintendo en 1992 au Japon et en Amérique du Nord. Le jeu est ressorti sur Game Boy Advance en 2001.', 'https://fr.wikipedia.org/wiki/Phalanx_(jeu_vid%C3%A9o)'),
  ('Q11323037', 'Dragon Ball Z: Super Saiya Densetsu littéralement Dragon Ball Z: La Légende des Super Saiyans est un jeu de rôle développé par TOSE et édité par Bandai sur Super Famicom sorti exclusivement au Japon le 25 janvier 1992.

Dragon Ball Z: Super Saiya Densetsu est un remake combiné des deux premiers jeux Dragon Ball Z publiés sur NES: Dragon Ball Z: Kyōshū! Saiyajin et Dragon Ball Z II: Gekishin Freeza!!. Il s''agit du premier jeu Dragon Ball Z à être publié sur Super Famicom. Bandai a édité 730 000 cartouches au Japon à 9 500 yens l''unité.

Le jeu utilise un système de cartes pour les combats, le joueur dispose de 5 cartes qui affichent les Dragon Balls pour l''attaque (dans le coin haut de la carte) et la défense (dans le coin bas), et un kanji au milieu de la carte qui représente le style de combat utilisé.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Super_Saiya_Densetsu'),
  ('Q11340195', 'Magical Drop est un jeu vidéo de puzzle développé et édité par Data East, sorti en 1995 sur le système d''arcade MLC. La version occidentale, nommée Chain Reaction remplace les billes de couleur du jeu par des aliments.

Il a été porté par la suite sur Super Famicom, Saturn, PlayStation et Game Boy Color. Il a aussi eu droit à une amélioration sur arcade nommée Magical Drop Plus 1!, qui apporte quelques améliorations graphiques.

Il a pour suite Magical Drop II.', 'https://fr.wikipedia.org/wiki/Magical_Drop'),
  ('Q11342889', 'Metal Marines est un jeu vidéo de stratégie en temps réel développé et édité par Namco, sorti en 1993 sur Windows et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Metal_Marines'),
  ('Q11673840', 'Majūō, ou King of Demons, est un jeu vidéo de plates-formes japonais développé par Eleven Co. et édité par KSS en 1995 sur Super Famicom. Le jeu met en scène l''histoire d''Abel, un homme qui doit secourir sa femme et son enfant de l''enfer. Dans ce jeu à défilement horizontal, vaincre des boss permet au joueur de se transformer en plusieurs démons. En 2024, Retro-Bit annonce une réédition physique du jeu.', 'https://fr.wikipedia.org/wiki/Maj%C5%AB%C5%8D'),
  ('Q11660555', 'Denjin Makai ou Ghost Chaser Densei est un jeu d''action Beat''em up en 2D à thème cyberpunk. Le jeu a été développé par Winkysoft et édité par Banpresto sur Arcade sous le nom Denjin Makai et porté sur Super Nintendo le 23 septembre 1994 uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Denjin_Makai'),
  ('Q12005929', 'Les Schtroumpfs est un jeu vidéo de plates-formes développé et édité par Infogrames (développé par Bit Managers pour la version 8 bits), sorti en 1993 sur Game Boy, en 1994 sur NES et Super Nintendo, en 1995 sur Master System, Game Gear, Mega Drive et Mega-CD puis en 1997 sur PC. Il est basé sur la bande-dessinée du même nom. La version 16 bits du jeu a été adaptée en 2002 sur Game Boy Advance sous le nom La Revanche des Schtroumpfs.

Ce jeu a connu deux suites, Les Schtroumpfs autour du monde, sortie en 1996 et Le Cauchemar des Schtroumpfs, sortie en 1997.', 'https://fr.wikipedia.org/wiki/Les_Schtroumpfs_(jeu_vid%C3%A9o,_1994)'),
  ('Q12170990', 'Bubsy in: Claws Encounters of the Furred Kind (Bubsy the Bobcat''s Great Adventure au Japon), souvent raccourci en Bubsy, est un jeu vidéo de plates-formes développé et édité par Accolade sorti en 1993 sur MegaDrive et Super Nintendo, puis porté en 1995 sur Microsoft Windows où il porte le nom de Super Bubsy.', 'https://fr.wikipedia.org/wiki/Bubsy_in:_Claws_Encounters_of_the_Furred_Kind'),
  ('Q13390015', 'Wing Commander est un jeu vidéo de combat spatial développé et édité par Origin Systems sur DOS en 1990. Le jeu a été porté sur Amiga, Amiga CD32, Mega-CD, Super Nintendo, 3DO et FM Towns. Il fait partie de la série Wing Commander.

Le joueur incarne un pilote de chasse dans un univers futuriste dans lequel les humains sont en guerre contre les Kilrathi.', 'https://fr.wikipedia.org/wiki/Wing_Commander_(jeu_vid%C3%A9o)'),
  ('Q15711525', 'Skyblazer, connu au Japon sous le nom Karuraou, est un jeu vidéo de plates-formes développé par Ukiyotei et édité par Sony Imagesoft sur Super Nintendo en 1994.', 'https://fr.wikipedia.org/wiki/Skyblazer'),
  ('Q15650127', 'Dragon Slayer: The Legend of Heroes II est un jeu vidéo de rôle sorti en 1992 et fonctionne sur DOS, Mega Drive, PC-Engine Super CD-ROM² et Super Famicom. Il a été développé par Nihon Falcom et fait suite à Dragon Slayer: The Legend of Heroes.', 'https://fr.wikipedia.org/wiki/Dragon_Slayer:_The_Legend_of_Heroes_II'),
  ('Q16267786', 'Power Drive est un jeu vidéo de course automobile développé par Rage Software et édité par U.S. Gold en 1994. Le jeu est disponible sur Amiga, Amiga CD32, DOS, Game Gear, Mega Drive et Super Nintendo. Le jeu a été adapté en 1995 sur Jaguar sous le titre Power Drive Rally.', 'https://fr.wikipedia.org/wiki/Power_Drive'),
  ('Q16205643', 'Where in the World Is Carmen Sandiego?, parfois connu en France sous le titre À la Poursuite de Carmen Sandiego dans le Monde, est un jeu vidéo d''aventure éducatif, développé et édité par Brøderbund en 1985. C''est le premier jeu de la franchise Carmen Sandiego.

Le joueur incarne un enquêteur d''Interpol qui parcourt le globe pour arrêter Carmen Sandiego et les membres de son organisation, la V.I.L.E. (Villains International League of Evil). L''aventure prend la forme d''un jeu de piste qui mène le joueur dans trente villes et fait appel à ses connaissances en géographie. The World Almanac était généralement inclus avec le jeu.', 'https://fr.wikipedia.org/wiki/Where_in_the_World_Is_Carmen_Sandiego%3F'),
  ('Q16670887', 'Power Instinct est un jeu vidéo de combat un contre un en 2D sorti en 1993 sur arcade. Il est ensuite sorti sur Mega Drive et Super Nintendo en 1994. Il a été développé et édité par Atlus. Il est le premier épisode de la série Power Instinct. Le jeu est resorti sur la Console virtuelle Wii en 2011.', 'https://fr.wikipedia.org/wiki/Power_Instinct_(jeu_vid%C3%A9o)'),
  ('Q16677481', 'Sonic Blast Man II est un jeu vidéo de type beat them all en 2D développé et édité par l''entreprise japonaise Taito sur Super Nintendo. Il est sorti sur SNES au Japon le 18 mars 1994 suivi de l''Amérique du Nord en novembre 1994. Il fait suite à Sonic Blast Man.', 'https://fr.wikipedia.org/wiki/Sonic_Blast_Man_II'),
  ('Q16679554', 'The Flintstones est un jeu vidéo de plates-formes développé et édité par Ocean Software en 1995 sur Super Nintendo. Il s''agit d''une adaptation du film La Famille Pierrafeu, lui-même issu de la série d''animation du même nom.', 'https://fr.wikipedia.org/wiki/The_Flintstones_(jeu_vid%C3%A9o,_1995)'),
  ('Q16382836', 'Disney''s Bonkers ou encore Bonkers Hollywood Daisakusen! au Japon, est un jeu vidéo d''action-plates-formes en 2D, adapté de la série d''animation Bonkers de Walt Disney Television Animation. Le jeu a été développé et édité par Capcom sur Super Nintendo. Il est sorti en 1994 en Amérique du Nord, suivi du Japon en 1995. Il s''agit d''un jeu distinct du jeu éponyme Bonkers de Sega sorti sur Mega Drive la même année.', 'https://fr.wikipedia.org/wiki/Disney%27s_Bonkers'),
  ('Q16661501', 'Lucky Luke est un jeu vidéo de plates-formes et d''action développé et édité par Infogrames en 1997 sur Super Nintendo et sur Windows/DOS. C''est une adaptation de la série de bande dessinée Lucky Luke.

Le jeu est adapté sur Game Boy Advance sous le nom Lucky Luke: Wanted en 2001 avec des modifications (notamment l''ajout de niveaux bonus).

Le jeu a en outre inspiré le jeu Lucky Luke, sorti en 1998 sur Playstation puis en 2000 sur PC sous le nom Lucky Luke: Sur la Piste des Dalton, et dont les graphismes sont par ailleurs en 3D.', 'https://fr.wikipedia.org/wiki/Lucky_Luke_(jeu_vid%C3%A9o,_1997)'),
  ('Q18663726', 'Stone Protectors est un jeu d''action de type Beat them all en 2D. Le jeu a été développé par Eurocom et édité par Kemco sur Super Nintendo. Il est sorti en Amérique du Nord en novembre 1994 puis au Japon le 28 avril 1995. Il s''agit d''une adaptation du dessin animé éponyme, Stone Protectors, lui-même basé sur les figurines Troll dolls.', 'https://fr.wikipedia.org/wiki/Stone_Protectors'),
  ('Q18413786', 'Jim Lee''s Wild C.A.T.S: Covert Action Teams est un jeu vidéo d''action de type Beat them all en 2D, développé par Beam Software et édité par Playmates Interactive Entertainment. Il est sorti sur Super Nintendo en novembre 1995. Le jeu est basé sur le comic éponyme créé par Jim Lee en 1992.', 'https://fr.wikipedia.org/wiki/Jim_Lee%27s_Wild_C.A.T.S:_Covert_Action_Teams'),
  ('Q18419176', 'Mario''s Early Years! Preschool Fun est un jeu pédagogique sorti en 1994 sur SNES et MS-DOS uniquement aux États-Unis. C''est un jeu s''adressant aux enfants de 6 ans. Dans ce jeu, Mario explore plusieurs îles, sur lesquelles se trouvent plusieurs mini-jeux.', 'https://fr.wikipedia.org/wiki/Mario%27s_Early_Years!_Preschool_Fun'),
  ('Q18674887', 'SWAT Kats: The Radical Squadron est un jeu vidéo d''action/plates-formes en 2D, développé par AIM et édité par Hudson Soft. Il est sorti sur Super Nintendo en août 1995 uniquement en Amérique du Nord. Il est basé sur le dessin animé éponyme produit par Hanna Barbera.', 'https://fr.wikipedia.org/wiki/SWAT_Kats:_The_Radical_Squadron'),
  ('Q20725907', 'Fighter''s History: Mizoguchi Kiki Ippatsu!! est un jeu vidéo de combat en 2D développé et édité par Data East en février 1995 sur Super Famicom, uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Fighter%27s_History:_Mizoguchi_Kiki_Ippatsu!!'),
  ('Q20726158', 'Majin Tensei II: Spiral Nemesis est jeu vidéo de rôle tactique T-RPG à thème urbain. Il a été développé et édité par Atlus. Il fait partie de la metasérie Megami Tensei. Le jeu est sorti uniquement au Japon le 19 février 1995 sur SNES et est ressorti sur la Console virtuelle (Wii) en 2011.', 'https://fr.wikipedia.org/wiki/Majin_Tensei_II:_Spiral_Nemesis'),
  ('Q19956226', 'James Bond Jr. est un jeu d''action avec des séquences de shoot ''em up, tiré de la série animée James Bond Jr. Le jeu a été développé par Gray Matter Inc. et édité par THQ sur Super Nintendo. Il est sorti en Amérique du Nord en octobre 1992 et en Europe la même année.', 'https://fr.wikipedia.org/wiki/James_Bond_Jr._(jeu_vid%C3%A9o,_1992)'),
  ('Q20725980', 'Hiryū no Ken S: Golden Fighter est un jeu vidéo de combat en 2D mélangeant des séquences de type beat them all et des combats en un-contre-un, développé et édité par Culture Brain en 1992 sur Super Famicom uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Hiry%C5%AB_no_Ken_S:_Golden_Fighter'),
  ('Q20726149', 'Magical Tarurūto-kun: Magic Adventure est un jeu d''action plates-formes en 2D. Il s''agit d''une des adaptations du manga et anime Talulu le magicien de Tatsuya Egawa. Le jeu a été développé par TOSE et édité par Bandai pour la Super Famicom. Il est sorti le 28 mars 1992, uniquement au Japon.', 'https://fr.wikipedia.org/wiki/Magical_Tarur%C5%ABto-kun:_Magic_Adventure'),
  ('Q20726154', 'Mahōjin Guru Guru est un manga japonais créé par Hiroyuki Etō.', 'https://fr.wikipedia.org/wiki/Mah%C5%8Djin_Guru_Guru'),
  ('Q25377234', 'Nightmare Busters est un jeu d''action de type run and gun en 2D développé par Arcade Zone en 1994 et édité par Super Fighter Team le 23 décembre 2013 sur Super Nintendo. Il s''agit d''un prototype annulé à l''époque après son développement et le premier jeu vidéo sorti officiellement en dehors du Japon sur Super Nintendo depuis 1998.', 'https://fr.wikipedia.org/wiki/Nightmare_Busters'),
  ('Q66139153', 'NFL Football est un jeu vidéo de football américain développé et édité par Konami, sorti en 1993 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/NFL_Football_(jeu_vid%C3%A9o,_1993)'),
  ('Q97656421', 'The Magical Quest starring Mickey Mouse est un jeu vidéo de plate-forme et d''action sorti en 1992 sur Super Nintendo. Le jeu a été développé et édité par Capcom.

Le jeu est ressorti en 2002 sur Game Boy Advance développé par Capcom Production Studio 3 sous le titre Disney''s Magical Quest starring Mickey and Minnie. Cette version ajoute la possibilité de choisir Minnie, cette dernière dispose de caractéristiques équivalentes à celles de Mickey en termes de gameplay.', 'https://fr.wikipedia.org/wiki/The_Magical_Quest_starring_Mickey_Mouse'),
  ('Q63870141', 'Elite Soccer est un jeu vidéo de football développé par Rage Software et édité par GameTek, sorti en 1994 sur Super Nintendo et Game Boy. Le jeu se nomme World Cup Striker en Allemagne et au Japon sur Super Nintendo et Soccer en Europe sur Game Boy.', 'https://fr.wikipedia.org/wiki/Elite_Soccer'),
  ('Q64011134', 'The Blues Brothers: Jukebox Adventure est un jeu vidéo de plates-formes développé et édité par Titus Interactive, sorti en 1993 sur DOS, Super Nintendo et Game Boy.', 'https://fr.wikipedia.org/wiki/The_Blues_Brothers:_Jukebox_Adventure'),
  ('Q54322', 'Super Star Wars est un jeu vidéo d''action de type run and gun développé par Sculptured Software et distribué sur Super Nintendo en 1992. Il s''agit de l’adaptation sur Super Nintendo du film Star Wars IV Un Nouvel Espoir.', 'https://fr.wikipedia.org/wiki/Super_Star_Wars'),
  ('Q54330', 'Super Star Wars: The Empire Strikes Back est un jeu vidéo d''action de type run and gun développé par Sculptured Software et distribué sur Super Nintendo en 1993. Il s''agit de l’adaptation du film Star Wars, épisode V: L''Empire contre-attaque.', 'https://fr.wikipedia.org/wiki/Super_Star_Wars:_The_Empire_Strikes_Back'),
  ('Q54335', 'Super Star Wars: Return of the Jedi est un jeu vidéo d''action de type run and gun développé par Sculptured Software et distribué sur Super Nintendo en 1994. Il s''agit de l’adaptation du film Star Wars, épisode VI: Le Retour du Jedi. Le jeu est porté sur Game Boy et Game Gear.', 'https://fr.wikipedia.org/wiki/Super_Star_Wars:_Return_of_the_Jedi'),
  ('Q18940', 'Wolfenstein 3D est un jeu vidéo de tir à la première personne développé par id Software et publié par Apogee Software le 5 mai 1992 sur MS-DOS. Il s''inspire des jeux Castle Wolfenstein et Beyond Castle Wolfenstein développés par Muse Software, respectivement en 1981 en 1984. Le joueur y incarne l''espion B. J. Blazkowicz qui tente de s''échapper d''un château nazi, dans lequel il est emprisonné, pendant la Seconde Guerre mondiale. Pour cela, il doit explorer plusieurs niveaux, combattre des ennemis et trouver un ascenseur afin d''accéder au niveau suivant. Au dernier niveau le joueur devra combattre un boss et enfin accéder à la sortie et terminer le jeu.', 'https://fr.wikipedia.org/wiki/Wolfenstein_3D'),
  ('Q111596693', 'Hokuto no Ken 7: Seiken Retsuden - Denshōsha e no Michi est un jeu vidéo de combat en 2D développé par Shouei System et édité par Toei Animation en décembre 1993 sur Super Famicom, uniquement au Japon. Il s''agit d''une adaptation du manga Ken le Survivant et est la suite du jeu Hokuto no Ken 6: Gekitō Denshōken - Haō heno Michi. Le jeu comprend un mode deux joueurs et contient neuf arènes.', 'https://fr.wikipedia.org/wiki/Hokuto_no_Ken_7:_Seiken_Retsuden_-_Densh%C5%8Dsha_e_no_Michi'),
  ('Q11322829', 'Doraemon 2: Nobita no Toys Land Daibouken est un jeu vidéo de plates-formes - aventure co-développé par Sakata SAS et Pophouse, et édité par Epoch en décembre 1993 exclusivement au Japon sur Super Famicom. Le jeu est inspiré du manga Doraemon.', 'https://fr.wikipedia.org/wiki/Doraemon_2'),
  ('Q11323038', 'Dragon Ball Z: Super Gokūden - Totsugeki-hen, littéralement « Dragon Ball Z: La grande histoire de Goku — L''Assaut » est un jeu vidéo de rôle sur l''univers de Dragon Ball, édité par Bandai et développé par TOSE. Il sort le 24 mars 1995, exclusivement au Japon sur Super Famicom.

Totsugeki-hen est le cinquième opus Super Famicom estampillé « Dragon Ball Z » (après le jeu Dragon Ball Z: Super Saiya Densetsu et les trois jeux de combat Super Butoden). Toutefois, si le jeu est commercialisé sous l''appellation Dragon Ball Z (correspondant à l''anime Dragon Ball Z qui couvre les volumes 17 à 42 du manga original Dragon Ball), il ne narre pas les évènements de cette partie. En effet, le scénario du jeu se concentre sur les volumes 1 à 16 du manga original Dragon Ball, de la rencontre entre Son Goku et Bulma, jusqu''à la fin du combat contre Piccolo.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Super_Gok%C5%ABden_-_Totsugeki-hen'),
  ('Q11323039', 'Dragon Ball Z: Super Gokūden - Kakusei-hen, littéralement « Dragon Ball Z: La grande histoire de Goku — L''Eveil » est un jeu vidéo de rôle sur l''univers de Dragon Ball, édité par Bandai et développé par TOSE, sorti le 22 septembre 1995, exclusivement au Japon sur Super Famicom.

Kakusei-hen est le sixième opus Super Famicom estampillé « Dragon Ball Z ». Il sort six mois après le précédent opus Dragon Ball Z: Super Gokūden - Totsugeki-hen dont il est la suite. Il couvre les volumes 17 à 28 du manga original Dragon Ball. La période couverte est du 23e Tenkaichi Budokai jusqu''à la conclusion de l''arc Freezer.', 'https://fr.wikipedia.org/wiki/Dragon_Ball_Z:_Super_Gok%C5%ABden_-_Kakusei-hen'),
  ('Q3519190', 'Tetris and Dr. Mario est une compilation de jeux vidéo de type puzzle game, développée par Intelligent Systems et publiée par Nintendo pour la Super Nintendo Entertainment System, sortie en 1994. Il contient des remake améliorés de Tetris (1984) et Dr. Mario (1990), qui ont été initialement publiés pour la Nintendo Entertainment System et pour la Game Boy en Amérique du Nord. Les deux jeux incluent un mode multijoueur à écran partagé et un mode Mixed Match qui fait la transition entre les deux jeux.

Le développement du jeu a été réalisé par Intelligent Systems. Le jeu a été l''un des derniers jeux SNES sortis en Amérique du Nord. La version japonaise du jeu exclut Tetris car Bullet-Proof Software détient les droits sur la série au Japon. Le remake de Dr. Mario a également été diffusé au Japon via Satellaview, mais a été rebaptisé BS Dr. Mario, et était le dernier jeu à être diffusé sur le système Satellaview. Tetris & Dr. Mario ont reçu des critiques généralement positives, les critiques faisant l''éloge de ses contrôles et de son mode multijoueur, en particulier le mode Mixed Match.', 'https://fr.wikipedia.org/wiki/Tetris_and_Dr._Mario'),
  ('Q2818867', 'A-Train III, connu au Japon sous le nom A Ressha de Ikō III, Take the A-Train III ou encore A.III., est un jeu vidéo de gestion et de simulation d''entreprise ferroviaire, développé par le studio japonais Ardink en 1990.

C''est le troisième épisode de la série A-Train et le premier à avoir été adapté en occident.', 'https://fr.wikipedia.org/wiki/A-Train_III'),
  ('Q4156284', 'Art of Fighting est un jeu vidéo de combat en 2D développé et édité par SNK sur Borne d''arcade (Neo-Geo MVS) et Neo-Geo AES en 1992 sur Neo-Geo CD (NGM / NGH 044), Mega Drive, Super Nintendo, PC-Engine (Arcade CD-ROM²).

Il s''agit du premier épisode de la série Art of Fighting. SNK récupère à l''époque du personnel de Capcom. Le character designer a réalisé ses personnages tel qu''il le souhaitait alors qu''il avait subi des contraintes pour Street Fighter 2, beaucoup considèrent Art of Fighting comme la véritable apparence que Street Fighter aurait dû recevoir.

Art of Fighting est le premier jeu de combat à intégrer un système de zoom. L''angle de vue se rapproche de l''action dès que les combattants sont proches l''un de l''autre. Les sprites apparaissent alors énormes.', 'https://fr.wikipedia.org/wiki/Art_of_Fighting_(jeu_vid%C3%A9o)'),
  ('Q1983421', 'Chuck Rock est un jeu vidéo de plates-formes développé et édité par Core Design en 1991 sur Amiga et Atari ST. Il a été adapté sur divers consoles de jeu et ordinateurs personnels.

Il a donné lieu à une suite, Chuck Rock II: Son of Chuck, sortie en 1993. Le joueur y dirige cette fois le fils de Chuck.', 'https://fr.wikipedia.org/wiki/Chuck_Rock'),
  ('Q17176439', 'College Football USA 97 est un jeu vidéo de football américain sorti en 1997 sur Mega Drive et Super Nintendo. Le jeu a été développé par Tiburon Entertainment et édité par EA Sports.', 'https://fr.wikipedia.org/wiki/College_Football_USA_97'),
  ('Q2301014', 'Dragon Quest VI est un jeu vidéo de rôle développé par Heartbeat pour l''éditeur japonais Enix. Il sort sur Super Famicom en décembre 1995 au Japon.

Le jeu bénéficie d''un remake en 3D développé par Arte Piazza pour la console portable Nintendo DS. Cette version est sortie courant 2010 au Japon et courant 2011 dans le reste du monde. Il fut renommé Dragon Quest VI: Le Royaume des songes à cette occasion.', 'https://fr.wikipedia.org/wiki/Dragon_Quest_VI_:_Le_Royaume_des_songes'),
  ('Q3062970', 'F1 est un jeu vidéo de course de Formule 1 développé par Lankhor et édité par Domark en 1993. Le jeu est disponible sur Amiga, DOS, Master System, Mega Drive et Game Gear. Il s''agit d''une version remaniée de Vroom (1991), bénéficiant de la licence officielle FOA.', 'https://fr.wikipedia.org/wiki/F1_(jeu_vid%C3%A9o,_1993)'),
  ('Q7723216', 'Mystery Dungeon: Shiren the Wanderer, ou Fushigi no Dungeon 2: Fūrai no Shiren au Japon, est un jeu vidéo de type dungeon crawler et rogue-like développé et édité par l''entreprise japonaise Chunsoft le 1er décembre 1995 sur Super Famicom, puis le 22 novembre 1996 sur Game Boy, uniquement au Japon.

Sega porte le jeu sur Nintendo DS et c''est cette dernière qui connait une sortie internationale à partir de 2008.', 'https://fr.wikipedia.org/wiki/Mystery_Dungeon:_Shiren_the_Wanderer'),
  ('Q1194133', 'Gradius III est un jeu vidéo de type shoot them up à défilement horizontal développé et édité par Konami, sorti en 1989 sur borne d''arcade puis en 1990 sur Super Nintendo.', 'https://fr.wikipedia.org/wiki/Gradius_III'),
  ('Q3518112', 'Tennis Cup est un jeu vidéo de tennis développé et édité par Loriciel en 1989. Il fonctionne sur Amiga, Amstrad CPC, Atari ST et DOS.', 'https://fr.wikipedia.org/wiki/Tennis_Cup'),
  ('Q55299563', 'Izzy''s Quest for the Olympic Rings est un jeu vidéo de plates-formes sorti en 1996 sur Mega Drive et Super Nintendo. Le jeu a été développé par Alexandria, Inc. et édité par U.S. Gold. Il met en scène Izzy, la mascotte des Jeux olympiques d''été de 1996 qui se sont déroulés à Atlanta.', 'https://fr.wikipedia.org/wiki/Izzy%27s_Quest_for_the_Olympic_Rings'),
  ('Q3276899', 'Magic Sword: Heroic Fantasy est un jeu vidéo de beat them all développé et édité par Capcom sur CP System en juin 1990. Il a ensuite été adapté sur console de jeux vidéo.', 'https://fr.wikipedia.org/wiki/Magic_Sword:_Heroic_Fantasy'),
  ('Q2413658', 'P.T.O.: Pacific Theatre of Operations, ou Teitoku no ketsudan au Japon, est une série de jeux vidéo de stratégie en temps réel développé et publié par Koei. Le premier titre de la série — P.T.O.: Pacific Theatre of Operations — est publié sur PC-88 en 1989, le jeu ayant ensuite été porté sur Mega Drive, Super Nintendo, MSX et DOS. Le jeu a bénéficié de trois suites, P.T.O. II, P.T.O. III et P.T.O. IV, publiées respectivement en 1995, 1996 et 2001.', 'https://fr.wikipedia.org/wiki/P.T.O.:_Pacific_Theater_of_Operations'),
  ('Q10349861', 'Pink Goes to Hollywood (ou Pink Panther in: Pink Goes to Hollywood) est un jeu de plates-formes de TecMagik sorti en 1993 sur Mega Drive et Super Nintendo.', 'https://fr.wikipedia.org/wiki/Pink_Goes_to_Hollywood'),
  ('Q20723089', 'Shanghai II: Dragon''s Eye est un jeu vidéo de mah-jong sorti en 1989 sur MSX. Le jeu est développé par Activision et édité par SystemSoft. Le jeu est porté sur PC l''année suivante. Une version Super Nintendo voit le jour en 1992, alors développée par Hot-B. Le jeu sort sur Mega Drive en 1994, cette fois-ci développé par Silicon & Synapse (devenu Blizzard Entertainment).', 'https://fr.wikipedia.org/wiki/Shanghai_II:_Dragon%27s_Eye'),
  ('Q4811332', 'Astral Bout ou Sougou Kakutougi: Astral Bout est une série de jeux de combat mixte développé par A-Wave, Inc et édité par King Records pour la Super Nintendo, uniquement au Japon. Elle est basée sur le championnat japonais de combat mixte Fighting Network RINGS de la première moitié des années 1990.

Les combats se déroulent un contre un sur un ring en vue latérale. Les combattants utilisent des éléments de Muay Thai, Lutte, Karate, Judo, Boxe, Kung Fu et autres arts martiaux.', 'https://fr.wikipedia.org/wiki/Astral_Bout'),
  ('Q3411064', 'Putty, aussi appelé Silly Putty, Super Putty et Putty Moon, est un jeu vidéo de plates-formes développé et édité par la société britannique System 3, sorti en 1992 sur Amiga, en 1993 sur Super Nintendo et en 1994 sur Amiga CD32.

Le joueur incarne Putty, une boule bondissante et élastique aux habilités variées. Le but du jeu est de rapatrier dans le temps imparti des robots dispersés dans des niveaux à l''architecture verticale. Les caractéristiques du personnage sont inspirés par le Silly Putty. Le jeu a donné suite à Putty Squad en 1994, qui a eu le droit à un remake sur PlayStation 3, PlayStation 4 et PlayStation Vita.', 'https://fr.wikipedia.org/wiki/Putty_(jeu_vid%C3%A9o)'),
  ('Q1543256', 'Thunder Force 3 est un jeu vidéo de type shoot ''em up à défilement horizontal de Technosoft, sorti en 1990 sur Mega Drive et la même année dans une version modifiée sur borne d''arcade sous le nom Thunder Force AC.

La version arcade est portée en 1991 sur Super Nintendo sous le titre Thunder Spirits.', 'https://fr.wikipedia.org/wiki/Thunder_Force_3'),
  ('Q1229899', 'Super 3D Noah''s Ark est un jeu vidéo de tir à la première personne sorti en 1994 sur Super Nintendo et DOS. Il a été développé et édite par Wisdom Tree. Sur le Super Nintendo, il était connu sous le nom de Super Noah''s Ark 3D. Ce jeu est la seule cartouche non officielle pour Super Nintendo qui ait été vendue commercialement.', 'https://fr.wikipedia.org/wiki/Super_3D_Noah%27s_Ark'),
  ('Q3529185', 'Tinhead est un jeu vidéo de plates-formes sorti en 1993 sur Mega Drive. Le jeu a été développé par MicroProse Software.', 'https://fr.wikipedia.org/wiki/Tinhead');

update public.game g
set summary = i.summary, summary_source = i.source
from import_summary i
where g.wikidata_id = i.wikidata_id
  and g.summary is null;

drop table import_summary;
